.context.support.AbstractApplicationContext.assertBeanFactoryActive(AbstractApplicationContext.java:956)at org.springframework.context.support.AbstractApplicationContext.getBean(AbstractApplicationContext.java:978)at org.springframework.xd.module.core.SimpleModule.getComponent(SimpleModule.java:214)at org.springframework.xd.dirt.plugins.AbstractMessageBusBinderPlugin.unbindConsumerAndProducers(AbstractMessageBusBinderPlugin.java:140)at org.springframework.xd.dirt.plugins.stream.StreamPlugin.beforeShutdown(StreamPlugin.java:74)at org.springframework.xd.dirt.module.ModuleDeployer.beforeShutdown(ModuleDeployer.java:267)at org.springframework.xd.dirt.module.ModuleDeployer.destroyModule(ModuleDeployer.java:217)at org.springframework.xd.dirt.module.ModuleDeployer.handleUndeploy(ModuleDeployer.java:197)at org.springframework.xd.dirt.module.ModuleDeployer.undeploy(ModuleDeployer.java:169)at org.springframework.xd.dirt.server.ContainerRegistrar.undeployModule(ContainerRegistrar.java:252)at org.springframework.xd.dirt.server.ContainerRegistrar$StreamModuleWatcher.process(ContainerRegistrar.java:580)at org.apache.curator.framework.imps.NamespaceWatcher.process(NamespaceWatcher.java:56)at org.apache.zookeeper.ClientCnxn$EventThread.processEvent(ClientCnxn.java:522)at org.apache.zookeeper.ClientCnxn$EventThread.run(ClientCnxn.java:498)20:15:31420  INFO main-EventThread server.ContainerRegistrar:250 - Undeploying module time-0: time type=source deploymentProperties={count=1}20:15:31420  INFO main-EventThread module.ModuleDeployer:215 - removed SimpleModule [name=time type=source group=s index=0 @51a42578]20:15:31420 ERROR main-EventThread imps.CuratorFrameworkImpl:512 - Watcher exceptionjava.lang.IllegalStateException: org.springframework.context.annotation.AnnotationConfigApplicationContext@6d223732 has been closed alreadyat org.springframework.context.support.AbstractApplicationContext.assertBeanFactoryActive(AbstractApplicationContext.java:956)at org.springframework.context.su