),('Spring_XD',1845,'XD-3445','94','{\"key\": \"XD-3445\", \"votes\": 0.0, \"blocks\": 0.0, \"sprint\": 94, \"status\": \"Done\", \"creator\": \"Sabby Anandan\", \"summary\": \"Fix Kafka Binder for s-c-s modules\", \"assignee\": \"Marius Bogoevici\", \"priority\": 4.0, \"reporter\": \"Sabby Anandan\", \"subtasks\": 0.0, \"blockedBy\": 0.0, \"issueType\": \"Story\", \"dependedOn\": 0.0, \"issueLinks\": 0.0, \"storyPoint\": 3.0, \"watchcount\": 1.0, \"description\": \"As a s-c-s developer I\'d like to fix the {{Kafka}} binder so I can create messaging microservices apps and successfully bind them to an operational Kafka broker. \", \"fixVersions\": 0.0, \"commentCount\": 0.0, \"dependedOnBy\": 0.0, \"affectedVersions\": 0.0}'),('Spring_XD',1846,'XD-3309','95','{\"key\": \"XD-3309\", \"votes\": 0.0, \"blocks\": 0.0, \"sprint\": 95, \"status\": \"Done\", \"creator\": \"Sabby Anandan\", \"summary\": \"Add direct binding option for s-c-s modules\", \"assignee\": \"Marius Bogoevici\", \"priority\": 4.0, \"reporter\": \"Sabby Anandan\", \"subtasks\": 0.0, \"blockedBy\": 0.0, \"issueType\": \"Story\", \"dependedOn\": 0.0, \"issueLinks\": 0.0, \"storyPoint\": 5.0, \"watchcount\": 1.0, \"description\": \"As a s-c-s user I\'d like to have the option to direct bind _modules_ so I don\'t have to use messaging middleware and I can eliminate latency between them. This is important for high throughput and low latency use cases. \", \"fixVersions\": 1.0, \"commentCount\": 0.0, \"dependedOnBy\": 0.0, \"affectedVersions\": 0.0}'),('Spring_XD',1847,'XD-3317','95','{\"key\": \"XD-3317\", \"votes\": 0.0, \"blocks\": 0.0, \"sprint\": 95, \"status\": \"Done\", \"creator\": \"Sabby Anandan\", \"summary\": \"Add support to resolve and add JARs to Boot loader\", \"assignee\": \"Marius Bogoevici\", \"priority\": 4.0, \"reporter\": \"Sabby Anandan\", \"subtasks\": 0.0, \"blockedBy\": 0.0, \"issueType\": \"Story\", \"dependedOn\": 2.0, \"issueLinks\": 3.0, \"storyPoint\": 8.0, \"watchcount\": 1.0