('Spring_XD',1863,'XD-3326','95','{\"key\": \"XD-3326\", \"votes\": 0.0, \"blocks\": 0.0, \"sprint\": 95, \"status\": \"Done\", \"creator\": \"Paul Harris\", \"summary\": \"Add parameter information to application definition\", \"assignee\": \"Steve Powell\", \"priority\": 4.0, \"reporter\": \"Paul Harris\", \"subtasks\": 0.0, \"blockedBy\": 0.0, \"issueType\": \"Story\", \"dependedOn\": 0.0, \"issueLinks\": 0.0, \"storyPoint\": 1.0, \"watchcount\": 1.0, \"description\": \"A ModuleDefinition contains parameters which need to be passed to the CloudFoundry application. Currently these are put directly into the application\'s environment. This issue will verify they are correctly named.\", \"fixVersions\": 1.0, \"commentCount\": 0.0, \"dependedOnBy\": 0.0, \"affectedVersions\": 0.0}'),('Spring_XD',1864,'XD-3325','95','{\"key\": \"XD-3325\", \"votes\": 0.0, \"blocks\": 0.0, \"sprint\": 95, \"status\": \"Done\", \"creator\": \"Paul Harris\", \"summary\": \"Add binding information to application definition\", \"assignee\": \"Steve Powell\", \"priority\": 4.0, \"reporter\": \"Paul Harris\", \"subtasks\": 0.0, \"blockedBy\": 0.0, \"issueType\": \"Story\", \"dependedOn\": 0.0, \"issueLinks\": 0.0, \"storyPoint\": 2.0, \"watchcount\": 1.0, \"description\": \"ModuleDefinition contains bindings that need to be passed to the ModuleRunner app. It appears these can be included in the application\'s environment.\", \"fixVersions\": 1.0, \"commentCount\": 0.0, \"dependedOnBy\": 0.0, \"affectedVersions\": 0.0}'),('Spring_XD',1865,'XD-3331','95','{\"key\": \"XD-3331\", \"votes\": 0.0, \"blocks\": 0.0, \"sprint\": 95, \"status\": \"Done\", \"creator\": \"Paul Harris\", \"summary\": \"Add real ModuleRunner application\", \"assignee\": \"Steve Powell\", \"priority\": 4.0, \"reporter\": \"Paul Harris\", \"subtasks\": 0.0, \"blockedBy\": 0.0, \"issueType\": \"Story\", \"dependedOn\": 0.0, \"issueLinks\": 0.0, \"storyPoint\": 2.0, \"watchcount\": 1.0, \"description\": \"The current ModuleRu