anFactory.java:456)at org.springframework.beans.factory.support.BeanDefinitionValueResolver.resolveInnerBean(BeanDefinitionValueResolver.java:271)at org.springframework.beans.factory.support.BeanDefinitionValueResolver.resolveValueIfNecessary(BeanDefinitionValueResolver.java:126)at org.springframework.beans.factory.support.AbstractAutowireCapableBeanFactory.applyPropertyValues(AbstractAutowireCapableBeanFactory.java:1360)at org.springframework.beans.factory.support.AbstractAutowireCapableBeanFactory.populateBean(AbstractAutowireCapableBeanFactory.java:1118)at org.springframework.beans.factory.support.AbstractAutowireCapableBeanFactory.doCreateBean(AbstractAutowireCapableBeanFactory.java:517)at org.springframework.beans.factory.support.AbstractAutowireCapableBeanFactory.createBean(AbstractAutowireCapableBeanFactory.java:456)at org.springframework.beans.factory.support.AbstractBeanFactory$1.getObject(AbstractBeanFactory.java:294)at org.springframework.beans.factory.support.DefaultSingletonBeanRegistry.getSingleton(DefaultSingletonBeanRegistry.java:225)at org.springframework.beans.factory.support.AbstractBeanFactory.doGetBean(AbstractBeanFactory.java:291)at org.springframework.beans.factory.support.AbstractBeanFactory.getBean(AbstractBeanFactory.java:193)at org.springframework.beans.factory.support.DefaultListableBeanFactory.preInstantiateSingletons(DefaultListableBeanFactory.java:589)at org.springframework.context.support.AbstractApplicationContext.finishBeanFactoryInitialization(AbstractApplicationContext.java:925)at org.springframework.context.support.AbstractApplicationContext.refresh(AbstractApplicationContext.java:472)at org.springframework.xd.module.SimpleModule.start(SimpleModule.java:97)at org.springframework.xd.dirt.module.ModuleDeployer.deployModule(ModuleDeployer.java:120)at org.springframework.xd.dirt.module.ModuleDeployer.handleMessageInternal(ModuleDeployer.java:108)at org.springframework.integration.handler.AbstractMessageHandler.handleMessage(AbstractMessageHandler.java:73)at sun.reflect.NativeMethodAccessorImpl.invoke0(Native Method)at sun.reflect.NativeMethodAccessorImpl.invoke(NativeMethodAccessorImpl.java:39)at sun.reflect.DelegatingMethodAccessorImpl.invoke(DelegatingMethodAccessorImpl.java:25)at java.lang.reflect.Method.invoke(Method.java:597)at org.springframework.expression.spel.support.ReflectiveMethodExecutor.execute(ReflectiveMethodExecutor.java:69)at org.springframework.expression.spel.ast.MethodReference.getValueInternal(MethodReference.java:84)at org.springframework.expression.spel.ast.CompoundExpression.getValueInternal(CompoundExpression.java:57)at org.springframework.expression.spel.ast.SpelNodeImpl.getTypedValue(SpelNodeImpl.java:102)at org.springframework.expression.spel.standard.SpelExpression.getValue(SpelExpression.java:102)at org.springframework.integration.util.AbstractExpressionEvaluator.evaluateExpression(AbstractExpressionEvaluator.java:126)at org.springframework.integration.util.MessagingMethodInvokerHelper.processInternal(MessagingMethodInvokerHelper.java:230)at org.springframework.integration.util.MessagingMethodInvokerHelper.process(MessagingMethodInvokerHelper.java:129)at org.springframework.integration.handler.MethodInvokingMessageProcessor.processMessage(MethodInvokingMessageProcessor.java:73)at org.springframework.integration.handler.ServiceActivatingHandler.handleRequestMessage(ServiceActivatingHandler.java:67)at org.springframework.integration.handler.AbstractReplyProducingMessageHandler.handleMessageInternal(AbstractReplyProducingMessageHandler.java:137)at org.springframework.integration.handler.AbstractMessageHandler.handleMessage(AbstractMessageHandler.java:73)at org.springframework.integration.dispatcher.UnicastingDispatcher.doDispatch(UnicastingDispatcher.java:115)at org.springframework.integration.dispatcher.UnicastingDispatcher.dispatch(UnicastingDispatcher.java:102)at org.springframework.integration.channel.AbstractSubscribableChannel.doSend(AbstractSubscribableChannel.java:77)at org.springframework.integration.channel.AbstractMessageChannel.send(AbstractMessageChannel.java:178)at org.springframework.integration.channel.AbstractMessageChannel.send(AbstractMessageChannel.java:149)at org.springframework.integration.core.MessagingTemplate.doSend(MessagingTemplate.java:304)at org.springframework.integration.core.MessagingTemplate.send(MessagingTemplate.java:165)at org.springframework.integration.endpoint.MessageProducerSupport.sendMessage(MessageProducerSupport.java:92)at org.springframework.integration.x.redis.RedisQueueInboundChannelAdapter.access$4(RedisQueueInboundChannelAdapter.java:1)at org.springframework.integration.x.redis.RedisQueueInboundChannelAdapter$ListenerTask.run(RedisQueueInboundChannelAdapter.java:110)at org.springframework.scheduling.support.DelegatingErrorHandlingRunnable.run(DelegatingErrorHandlingRunnable.java:53)at java.util.concurrent.Executors$RunnableAdapter.call(Executors.java:441)at java.util.concurrent.FutureTask$Sync.innerRun(FutureTask.java:303)at java.util.concurrent.FutureTask.run(FutureTask.java:138)at java.util.concurrent.ScheduledThreadPoolExecutor$ScheduledFutureTask.access$301(ScheduledThreadPoolExecutor.java:98)at java.util.concurrent.ScheduledThreadPoolExecutor$ScheduledFutureTask.run(ScheduledThreadPoolExecutor.java:206)at java.util.concurrent.ThreadPoolExecutor$Worker.runTask(ThreadPoolExecutor.java:886)at java.util.concurrent.ThreadPoolExecutor$Worker.run(ThreadPoolExecutor.java:908)at java.lang.Thread.run(Thread.java:662){code}',1,'Mark Fisher','Issues'),('Spring_XD','XD-1980',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-1982',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-1983',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-1984',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-1985',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-1986',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-1989',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-199','Ensure the DELETE Operation can Delete a Tap','While deleting a stream doesn\'t remove any taps right now we should be able to explicitly delete a tap.Determine whether the current DELETE works and if not make it so.',3,'Gary Russell','Issues'),('Spring_XD','XD-1990','Add Docs (or Reference) For Standard Shell Commands (e.g. script)','http://stackoverflow.com/questions/24819401/how-to-get-spring-xd-to-deploy-a-predefined-set-of-streams-and-taps-on-startupIt is documented here https://github.com/spring-projects/spring-xd/wiki/Shell#executing-a-scriptBut maybe it should also be at the top of the appendix?https://github.com/spring-projects/spring-xd/wiki/ShellReference',1,'Eric Bottard','Issues'),('Spring_XD','XD-1991','Error message about memory leak when ctrl-c xd-container and xd-admin','e.g. ^C09:42:00882 ERROR localhost-startStop-2 loader.WebappClassLoader - The web application [] appears to have started a thread named [Abandoned connection cleanup thread] but has failed to stop it. This is very likely to create a memory leak.The thread name may be different...',4,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-1993','Update rpm and brew recipes',NULL,2,'Kashyap Parikh','Issues'),('Spring_XD','XD-1994','ParentLastURLClassLoader should set itself as context ClassLoader','I am converting a Spring XD Sample (Batch notifications) from copying jars to (old way){code}$XD_HOME/lib{code}To rather copy the module jar to (new preferred way){code}$XD_HOME/modules/job/payment-import/lib{code}By doing so I hit a classloader issue. Custom classes and resources are loaded in Spring XD using *org.springframework.xd.module.support.ParentLastURLClassLoader*.However the sample is initializing custom bean definitions and one of those creates a new *DataSource* using the *EmbeddedDatabaseBuilder*. This class however under the hood uses the *Default* class loader to load SQL scripts:{code}public DefaultResourceLoader() {this.classLoader = ClassUtils.getDefaultClassLoader();}{code}Therefore the SQL scripts are NOT FOUND.*Possible Solution*A possible solution seems to be for *ParentLastURLClassLoader* to set itself as the context ClassLoader for the current thread:{code}public ParentLastURLClassLoader(URL[] classpath ClassLoader parent) {...Thread.currentThread().setContextClassLoader(this);...}{code}',4,'Gunnar Hillert','Issues'),('Spring_XD','XD-1995','Step execution count is zero for the job execution list result','For the Job execution list the step execution count for each job execution is always set to zero.For a single job execution display command the step execution count is set correctly.',4,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-1996','Inconsistent failure while deploying job from admin UI','After clicking \'deploy\' on the definitions page the \'deploy\' button is deactivated and message says:\"An error occurred. We were unable to retrieve the module name from the provided definition ....\"and web console says:TypeError: Cannot read property \'0\' of null    at Object.getModuleNameFromJobDefinition (http://localhost:9393/admin-ui/scripts/shared/services.js:43:26)    at http://localhost:9393/admin-ui/scripts/job/controllers/definition-deploy.js:35:36    at wrappedCallback (http://localhost:9393/admin-ui/lib/angular/angular.js:11319:81)    at http://localhost:9393/admin-ui/lib/angular/angular.js:11405:26    at Scope.$eval (http://localhost:9393/admin-ui/lib/angular/angular.js:12412:28)    at Scope.$digest (http://localhost:9393/admin-ui/lib/angular/angular.js:12224:31)    at Scope.$apply (http://localhost:9393/admin-ui/lib/angular/angular.js:12516:24)    at done (http://localhost:9393/admin-ui/lib/angular/angular.js:8204:45)    at completeRequest (http://localhost:9393/admin-ui/lib/angular/angular.js:8412:7)    at XMLHttpRequest.xhr.onreadystatechange (http://localhost:9393/admin-ui/lib/angular/angular.js:8351:11)',3,'Gunnar Hillert','Issues'),('Spring_XD','XD-1997',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-1998','Remove jersey test framework for xd/lib distribution','The jars jersey-test-framework-core-1.9.jar jersey-test-framework-grizzly2-1.9.jarare incorrectly classified as compile time deps in hadoop vs. testCompile.',1,'Eric Bottard','Issues'),('Spring_XD','XD-1999','Remove unused post module references',NULL,1,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-20','DIRT Runtime that deploys an application context across multiple nodes using redis.',NULL,3,'Mark Fisher','Issues'),('Spring_XD','XD-200','Creating a tap throws an exception','Creating a tap throws an exception. In local mode: Cannot resolve reference to bean \'redisConnectionFactory\' while setting constructor argument; nested exception is org.springframework.beans.factory.NoSuchBeanDefinitionException: No bean named \'redisConnectionFactory\' is defined  But also fails when using redis.',4,'David Turanski','Issues'),('Spring_XD','XD-2003','In EC2 deployment Allow users to set download jars into the lib/xd directory','In cases where the deployment requires jars that can not be included with the distribution the user should be able to pull a jar from a http site and place it in lib/xd.  The use case is that when we removed the mysql jar from the distribution the CI tests could not start the XD instances on EC2 without it.  It was suggested that we use the postgresql instead but decided to continue the use of mysql for acceptance tests.',5,'Glenn Renfro','Issues'),('Spring_XD','XD-2004','Containers stopped responding to Admin','SHA = a205d43f0b59e1984bf55c3368b031a373a03712Environment: Rabbit Transport Test 1 admin 2 containers.[Initial Event]During the run of FileJdbcTest.testPartitionedFileJdbcJob the containers quit responding to the admin server.   After the initial failure at 12:26:46 no other streams can be deployed.  [Secondary Event]When shutting down one of the container 1 the following exception occurs on the admin server:12:51:12004  INFO DeploymentSupervisorCacheListener-0 server.DepartingContainerModuleRedeployer - Container departed: Container{name=\'5353dc4b-6068-49a0-8981-fa175869edf0\' attributes={id=5353dc4b-6068-49a0-8981-fa175869edf0 host=domU-12-31-39-07-81-02 pid=1270 groups= ip=10.209.130.240}}12:51:12004 ERROR DeploymentSupervisorCacheListener-0 cache.PathChildrenCache - org.apache.zookeeper.KeeperException$NoNodeException: KeeperErrorCode = NoNode for /xd/deployments/modules/allocated/5353dc4b-6068-49a0-8981-fa175869edf0at org.apache.zookeeper.KeeperException.create(KeeperException.java:111)at org.apache.zookeeper.KeeperException.create(KeeperException.java:51)at org.apache.zookeeper.ZooKeeper.getChildren(ZooKeeper.java:1590)at org.apache.curator.framework.imps.GetChildrenBuilderImpl$3.call(GetChildrenBuilderImpl.java:214)at org.apache.curator.framework.imps.GetChildrenBuilderImpl$3.call(GetChildrenBuilderImpl.java:203)at org.apache.curator.RetryLoop.callWithRetry(RetryLoop.java:107)at org.apache.curator.framework.imps.GetChildrenBuilderImpl.pathInForeground(GetChildrenBuilderImpl.java:199)at org.apache.curator.framework.imps.GetChildrenBuilderImpl.forPath(GetChildrenBuilderImpl.java:191)at org.apache.curator.framework.imps.GetChildrenBuilderImpl.forPath(GetChildrenBuilderImpl.java:38)at org.springframework.xd.dirt.server.DepartingContainerModuleRedeployer.deployModules(DepartingContainerModuleRedeployer.java:101)at org.springframework.xd.dirt.server.ContainerListener.childEvent(ContainerListener.java:104)at org.apache.curator.framework.recipes.cache.PathChildrenCache$5.apply(PathChildrenCache.java:509)at org.apache.curator.framework.recipes.cache.PathChildrenCache$5.apply(PathChildrenCache.java:503)at org.apache.curator.framework.listen.ListenerContainer$1.run(ListenerContainer.java:92)at com.google.common.util.concurrent.MoreExecutors$SameThreadExecutorService.execute(MoreExecutors.java:297)at org.apache.curator.framework.listen.ListenerContainer.forEach(ListenerContainer.java:83)at org.apache.curator.framework.recipes.cache.PathChildrenCache.callListeners(PathChildrenCache.java:500)at org.apache.curator.framework.recipes.cache.EventOperation.invoke(EventOperation.java:35)at org.apache.curator.framework.recipes.cache.PathChildrenCache$10.run(PathChildrenCache.java:762)at java.util.concurrent.Executors$RunnableAdapter.call(Executors.java:471)at java.util.concurrent.FutureTask.run(FutureTask.java:262)at java.util.concurrent.Executors$RunnableAdapter.call(Executors.java:471)at java.util.concurrent.FutureTask.run(FutureTask.java:262)at java.util.concurrent.ThreadPoolExecutor.runWorker(ThreadPoolExecutor.java:1145)at java.util.concurrent.ThreadPoolExecutor$Worker.run(ThreadPoolExecutor.java:615)at java.lang.Thread.run(Thread.java:745)The attached container logs are only partial because they have rolled over.  The attached admin log is fairly complete.',12,'Patrick Peralta','Issues'),('Spring_XD','XD-2005','IllegalStateException when shutting down container','{noformat}13:23:57643  INFO main-EventThread server.ContainerRegistrar - Undeploying module [ModuleDescriptor@1c736092 moduleName = \'log\' moduleLabel = \'log\' group = \'paymenttap\' sourceChannelName = \'tap:job:payment\' sinkChannelName = [null] sinkChannelName = [null] index = 0 type = sink parameters = map[[empty]] children = list[[empty]]]13:23:57643 ERROR main-EventThread imps.CuratorFrameworkImpl - Watcher exceptionjava.lang.IllegalStateException: instance must be started before calling this methodat com.google.common.base.Preconditions.checkState(Preconditions.java:176)at org.apache.curator.framework.imps.CuratorFrameworkImpl.delete(CuratorFrameworkImpl.java:344)at org.springframework.xd.dirt.server.ContainerRegistrar.unregisterTap(ContainerRegistrar.java:292)at org.springframework.xd.dirt.server.ContainerRegistrar.undeployModule(ContainerRegistrar.java:257)at org.springframework.xd.dirt.server.ContainerRegistrar$StreamModuleWatcher.process(ContainerRegistrar.java:711)at org.apache.curator.framework.imps.NamespaceWatcher.process(NamespaceWatcher.java:67)at org.apache.zookeeper.ClientCnxn$EventThread.processEvent(ClientCnxn.java:522)at org.apache.zookeeper.ClientCnxn$EventThread.run(ClientCnxn.java:498){noformat}Sequence of events:* Stream module ZK path is removed* Event is raised* ZK connection is closed* Event handler causes module undeployment which includes unregistration of tap* Since connection is closed exception is thrown',3,'Patrick Peralta','Issues'),('Spring_XD','XD-2006','Logging improvements','Propose the following changes to our logging:* Create unique file names by including the pid in the file name - this allows each process (in particular containers) to maintain its own log file* Use DailyRollingFileAppender to roll files over on a daily basis',2,'Patrick Peralta','Issues'),('Spring_XD','XD-2007','Acceptance test must be able to handle log names with PID suffix','Introduced by XD-2006 admin and container logs will have a pid suffix appended to their filename.The acceptance tests will have to identify the PID for the admin server and the container servers deployed in the cluster and then append the pid value to the filename contained in the xd_container_log_dir.',4,'Glenn Renfro','Issues'),('Spring_XD','XD-2008','Verify we meet all requirements to publish to maven central','https://docs.sonatype.org/display/Repository/Central+Sync+Requirementshas a list of requirements.  This also means that https://jira.spring.io/browse/XD-1509 is critical to fix.',3,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2009','Cleanup Module Deployer','Container\'s module deployer (org.springframework.xd.dirt.module.ModuleDeployer) has some unused code and container-server.xml has listeners.xml which is no longer used. Also all the extension code is moved to SharedContextConfiguration.',1,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-201','Fix XD scripts on windows','Currently the XD scripts are broken in windows.',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2010','Fix package-info.java warnings',NULL,2,'Eric Bottard','Issues'),('Spring_XD','XD-2011','Replace xd MongoItemWriter in hdfsmongodb with spring batch MongoItemWriter','When hdfsmongodb was written Spring Batch did not have a MongoItemWriter available so Mark wrote one for XD.  The hdfsmongodb module now needs to be use Spring Batches MongoItemWriter.',3,'Glenn Renfro','Issues'),('Spring_XD','XD-2012','Upgrade to Spring Shell 1.1 GA',NULL,1,'Mark Pollack','Issues'),('Spring_XD','XD-2015','Spring XD UI: end-to-end tests do not work','Currently end-to-end tests of Spring XD UI will not run as protractor relies on a non-existing chromedriver.exe file.Either the configuration has to be removed from the Gruntfile or the necessary dependencies should be there.',2,'Gunnar Hillert','Issues'),('Spring_XD','XD-2016',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2017',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2018',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-202','Update twittersearch module for Twitter 1.0 API retirement',NULL,3,'Mark Fisher','Issues'),('Spring_XD','XD-2021',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2022','0xData - investigate embedding','0xData is a rich JVM based machine learning and scoring engine.',24,'Mark Pollack','Issues'),('Spring_XD','XD-2023','Update to Spring Hadoop 2.0.2','A bug in the HDFS Store was discovered that should be fixed.',1,'Thomas Risberg','Issues'),('Spring_XD','XD-2024',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2025',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2026','Handle random available http port for admin server','If the XD admin server lets tomcat chooses random http port by setting PORT or server.port to \'0\' the XD config logging and admin server context id still points to port zero as these are set before tomcat assigns the available random port.We also need to persist the admin servers\' ports into ZK so that this repo can be accessed by the client.',5,'Janne Valkealahti','Issues'),('Spring_XD','XD-2027',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2028',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2029',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-203',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2030',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2031','Improvements to Tuple project','Removed  various TODO comments in code and put here for proper triage.DefaultTuple  * Error handling.  When delegating to the conversion service the ConversionFailedException does not have the context of which key caused the failure.  Need to wrap ConversionFailedException with IllegalArgumentException and add that context back in.  (see method convert) * Ctor visibility.  Consider making ctor final and package protect the ctor so as to always use TupleBuilder * check for no duplicate values when initializing names/values listtuple.* top level methods to add.    String getComponentName... somethign that would indicate which stream or job this tuple is being processed in....* TupleFieldSetMapperOnly one date format?* JsonStringtoTupleConverter/JsonNodetoTupleConverter * do we want to not map id and timestamp (believe the answer is don\'t map preserve original)',1,'Mark Pollack','Issues'),('Spring_XD','XD-2032',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2033',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2034',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2035',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2037',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2038',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-204','Document processor modules','Fill in https://github.com/SpringSource/spring-xd/wiki/Processors',2,'Jennifer Hickey','Issues'),('Spring_XD','XD-2041','Fix anchor links so that they work in both the wiki and generated docs','Part of the issue is likely with the build script https://github.com/spring-projects/spring-xd/blob/master/build.gradle#L1859  We should also add a link checker to the CI build.',8,'Eric Bottard','Issues'),('Spring_XD','XD-2044','Add SFTP source','As a user I\'d like to have the option to use the _SFTP_ source module so that I can access transfer and mange files over any reliable data streams.*Reference:*[Spring Integration SFTP Adapter|http://docs.spring.io/spring-integration/reference/html/sftp.html]Need to consider the infrastructure for testing.',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2047','Easier Customization of Headers Passed by RedisMessageBus','http://stackoverflow.com/questions/25072967/spring-xd-redis-message-bus-removing-headers-from-the-message/25081538#25081538Currently you have to modify {{redis-bus.xml}} in the dirt jar.',1,'Gary Russell','Issues'),('Spring_XD','XD-205',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2050',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2057',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2058','Investigate long running tests','The goal is to optimize the build process and at the same time validate the feature capabilities as quickly as we can. Investigate the long running tests. Look for long timeout window declarations.',4,'David Turanski','Issues'),('Spring_XD','XD-206','XD AdminMain & ContainerMain should check xd.home property from scripts','Currently the system property xd.home is set as JVM_OPTS (via SPRING_XD_ADMIN_OPTS) into xd-admin & xd-container scripts.Inside the ContainerMain & AdminMain we need to check if this system property is set and use it. It seems like this check is missing now.',1,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2060','Add JDBC source','As an user I\'d like to have a native _JDBC_ source module to ingest data directly from various databases.',3,'Eric Bottard','Issues'),('Spring_XD','XD-2061','Add Redis sink','As an user I\'d like to have the ability to ingest data into _Redis_ sink.',3,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2063','Investigate setting up performance test environment on cloud providers','Use a baseline DIRT infrastructure to measure throughput HA and scalability for various payload sizes.Depends on testing infrastructure setup configuration and availability.',8,'Thomas Risberg','Issues'),('Spring_XD','XD-2067','Upgrade asciidoctor toolchain','This will in turn allow us to get rid of the custom logic for handling crossref links between documents',3,'Eric Bottard','Issues'),('Spring_XD','XD-2069','Provide a way to debug the http source','The http source does not provide debug logging to see information such as http headers and requests in particular if a non OK response is returned.I updated the log4j config for org.jboss.netty but it had no effect.  I suspect this is due to the need to configure the netty logging system via InternalLoggerFactory.setDefaultFactory(new Log4JLoggerFactory()).',5,'Marius Bogoevici','Issues'),('Spring_XD','XD-207','Provide configurable properties for hdfs sink.','The config file modules/sink/hdfs.xml has a hardcoded value to locate the namenode.<hdp:configuration register-url-handler=\"false\">fs.default.name=hdfs://localhost:9000</hdp:configuration>the fs.default.name proprety should be configurable and we should also support loading an external configuration file using    <hdp:configuration properties-location=\"${xd.home}/config/hadoop.properties\">   </hdp:configuration>',2,'Mark Fisher','Issues'),('Spring_XD','XD-2070','Get rid of custom asciidoctor link: transformations','Remove {noformat}filter { line ->// TODO: refine regex to only match local documentsdef match = (line =~ /link:(.*?)#(.*?)\\[(.*?)\\]/)if (match) match.replaceAll(\'xref:$2[$3]\') else line}{noformat}and replace link:Foo#bar by xref:Foo#bar',2,'Eric Bottard','Issues'),('Spring_XD','XD-2071','Modularize gradle build','split out build.gradle into multiple files.',2,'David Turanski','Issues'),('Spring_XD','XD-2074',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2075','Add --binary Option to MQTT Source','See http://stackoverflow.com/questions/25226527/mqtt-source-spring-xd/25227531#25227531',1,'Gary Russell','Issues'),('Spring_XD','XD-2078','\"http | hdfs\" stream starts throwing exceptions after a few minutes','Environment:- Hadoop Installation: PHD Service for PCF  (PHD1.1 based on Apache Hadoop 2.0.5:  2.0.5-alpha-gphd-2.1.0.0 ) running on vCHS- Spring XD running in singlenode mode (version 1.0.0.RC1) on a vCHS VMSteps to reproduce:1- Setup a stream in Spring XD shell: \"http --port=9000 | hdfs --rollover=10M --idleTimeout=60000\" --deploy2- Hit port 9000 every second with 1-10KB of JSON data3- Observe the temp file being created in HDFS under /xd/<stream name>4- Run `hadoop fs tail <file> --follow` to see that data is being written to HDFSExpected result:- HDFS sink continues to operate and eventually roll-over at 10MBActual:- After about 2 minutes of successful HDFS writes the HDFS sink crashes and starts throwing exceptions (see full log attached): \"\'java.io.IOException: All datanodes 192.168.109.61:50010 are bad. Aborting...\"- The temp file is never closed even after the stream is undeployed or destroyed.  Here are some details of our investigation that may be useful:- I start both the shell and the singlenode runner with --hadoopDistro phd1;  I also configured the hadoop fs namenode correctly in the XD shell.- \"http <options> | file <options>\" work as expected; so does \"http <options> | log\"- \"time | hdfs\" does not show the same crash problem. Up until now only the http source combined with hdfs sink presents this problem- Putting a 4-10MB file in HDFS via the `Hadoop fs put` commands in Spring XD worked fine; so it\'s not a disk limitation.- This could be related to PHD service running on vCHS since supporting this configuration is fairly new. But it\'s only reproducable (consistently) with Spring XD\'s \"http | hdfs\" stream.',0,'Thomas Risberg','Issues'),('Spring_XD','XD-2079','Add a Retry/Dead Letter Interceptor to the RabbitMQ Source','Provide for retry and/or dead-lettering for the rabbit source (similar to the rabbit message bus).',2,'Gary Russell','Issues'),('Spring_XD','XD-208','Document the file sink',NULL,1,'Luke Taylor','Issues'),('Spring_XD','XD-2085','Test Recommended XD Cluster Strategy on slow/bad network','h1. Run Acceptance tests on the following  deployments.  h2. Slow NetworkSimulate slow network by deploying a XD cluster where the ZK Ensemble is only available via WAN.  h2. Network packet lossSimulate cases where a network packets can be lost.',5,'Glenn Renfro','Issues'),('Spring_XD','XD-2088',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-209',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2090','Custom module packaging strategy','As a user I\'d like to have guidance to create custom modules so that I can align the development practices with recommended approach. 11/20: Update: Scope of this task is to create an example to demonstrate and document the capability.',1,'David Turanski','Issues'),('Spring_XD','XD-2091','Research approach to bootstrap custom modules','Design Spike: Investigate various approaches to bootstrap custom modules. Can Spring Boot be leveraged? Starter POM?',5,'David Turanski','Issues'),('Spring_XD','XD-2092','Enhance Container domain object','Currently org.springframework.xd.dirt.cluster.Container has name and attributes (container attributes). This can be enhanced to include all the deployed modules number of deployed modules and any more useful info. and can subsequently be used to get a detailed runtime container info.',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2093','List Streams/Jobs based with deployed modules','Currently there is a \"stream list\"/\"job list\" which shows the status of a given stream/job along with the DSL. and there is \"runtime modules\" which shows all the deployed modules with their container info.We need a better REST endpoint that gives all the deployed modules for a given stream/job along with the status.',3,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2094','UI: Cluster view of a container','We need a visual representation of the XD cluster with runtime container and deployed modules.',5,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2095','UI: Ability to deploy stream with deployment properties','Admin UI currently allows job to be deployed with deployment properties we need similar way to deploy stream with the deployment properties (module count container matching criteria).',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2096',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2097','Enable shutdown containers from admin server','When the container starts up it has a random http port for management configurations. If the container has management port enabled then we can store it as container attribute. If the admin can reach out to the container on that port then we can provide an option to shutdown container from the admin server.',5,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2098','Implement KafkaMessageBus','Kafka lends itself well as a message bus and kafka partitioning maps to MB partitioning.Implement KafkaMessageBus and supporting classes and UT/IT.',3,'Eric Bottard','Issues'),('Spring_XD','XD-21','Create syslog.xml file for module registry','Consider which properties of the syslog namespace need to use property placeholders',NULL,'Mark Fisher','Issues'),('Spring_XD','XD-2100',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2103','Add Kafka sink','As a user I\'d like to have the option to write into _Kafka_ sink so that I can publish mass data into Kafka broker.',8,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2105','MessageBus should see custom SpEL property accessors','Currently custom SI property accessors are registered by a plugin (org.springframework.xd.dirt.plugins.SpelPropertyAccessorPlugin) and are not visible by the bus.I believe they should be.This may just be a matter of moving them around.',5,'Eric Bottard','Issues'),('Spring_XD','XD-2107','Allow aggregate-counter to increment by some value of the message','Currently the aggregate counter only adds +1 to the individual values even though support is there to add any increment.This ticket is about surfacing a SpEL expression on the message to choose the increment',3,'Eric Bottard','Issues'),('Spring_XD','XD-2109','No way to set \'makeUnique\' false when creating job in UI','The resulting definition starts with --makeUnique=true even if the MakeUnique checkbox is unchecked. I can check and uncheck the box and the --make unique parameter isn\'t included. Since the default for this parameter is true the end result is the same. There doesn\'t seem to be a way to set --makeUnique=false.',3,'Gunnar Hillert','Issues'),('Spring_XD','XD-211','Document the log sink',NULL,1,'Luke Taylor','Issues'),('Spring_XD','XD-2113','Redis aggregate-counter fails when end of interval is on the hour','curl http://localhost:9393/metrics/aggregate-counters/smartgrid_h_28_load_predicted\\?resolution\\=minute\\&from\\=2013-09-01T12:55:00.000Z\\&to\\=2013-09-01T13:00:00.000Z would return 0 as the last bucket whilecurl http://localhost:9393/metrics/aggregate-counters/smartgrid_h_28_load_predicted\\?resolution\\=minute\\&from\\=2013-09-01T12:55:00.000Z\\&to\\=2013-09-01T13:05:00.000Zwould correctly return the value for 13:00:00',2,'Eric Bottard','Issues'),('Spring_XD','XD-2114','Job stuck in \"deploying\" state when no containers are available','A job gets stuck in \"deploying\" state when a job is deployed when there are no containers available.  When a container is started after this event the job doesn\'t automatically start because of the job is stuck in the \"deploying\" state instead of the \"failed\" state.  Refer to https://github.com/spring-projects/spring-xd/blob/193088dc164c73e07d7b4509de22241b28bf42b3/spring-xd-dirt/src/main/java/org/springframework/xd/dirt/server/JobDeploymentListener.javaUpdate of the status in Zookeeper is inside the NoContainerException catch block.This works correctly for streams.',5,'Patrick Peralta','Issues'),('Spring_XD','XD-2115','Using taps with deployment property module.*.count=0 causes duplication of messages','Setup: DIRT Spring XD 2 Admins 3 ContainersStep 1. Deploy the following streams (which would get deployed to all 3 containers)stream create --name httpFoo --definition \"http | file\"stream deploy httpFoo --properties \"module.*.count=0\"stream create --name httpFooTap --definition \"tap:stream:httpFoo > file\"stream deploy httpFooTap --properties \"module.*.count=0\"stream create --name httpFooCounter --definition \"tap:stream:httpFoo > counter --name=httpFooCounter\"stream deploy httpFooCounter --properties \"module.*.count=0\"Step 2. Run runtime modules to ensure each module was deployed to every containerStep 3. Do a test curl callhttp post --target http://container-1:9000 --data \"{\\\"xlmagic\\\":\\\"dorothy\\\"}\"Step 4. The httpFooTap and httpFooCounter will receive duplicate messages. The number of messages = # of containers. In our case httpFoo.out exists only one 1 container. However httpFooTap.out exists on all 3 containers and contains the same message. Similarly httpFooCounter has a value of 3.Looking at how the taps are represented in rabbit this behaviour makes sense as XD is using fanout exchanges and each instance for a given tap is a consumer.',0,'Gary Russell','Issues'),('Spring_XD','XD-2117',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2118','Create a shell command processor and sink','Create processor and sink modules that can execute a shell command using stdin and stdout to stream data.',5,'David Turanski','Issues'),('Spring_XD','XD-2119','Support accessing admin server endpoints over HTTPS','As a user I\'d like to have the option to enable HTTPS so that I can access XD\'s Admin server [endpoints|https://github.com/spring-projects/spring-xd/wiki/REST-API#xd-resources] over secured communication.Technical Implementation:This functionality is available in Spring Boot 1.2.0 M1 and has been backported into the 1.1.x branch to be released under Spring 1.1.7.  We can test against 1.1.7 SNAPSHOT.Working through the way to update the build file to pick up a new version of boot is a bit tricky :(',1,'Marius Bogoevici','Issues'),('Spring_XD','XD-212','Add http port command line option to AdminMain','Currently StreamServer has setPort but no way for end user to set it.',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2120','Provide file based storage for users groups (and roles)','As a user I\'d like to have the option to provide file based security configurations so that I can access the endpoints in a secured manner.Ideally all the listed *endpoints* (http://localhost:9393/) needs to be encapsulated within file based security layer.Reference:[Securing Web App|https://spring.io/guides/gs/securing-web/]',5,'Eric Bottard','Issues'),('Spring_XD','XD-2121','Secure all endpoints using LDAP based security configurations','As a user I\'d like to have the option to provide LDAP based security configurations so that I can access the endpoints in a secured manner.Ideally all the listed *endpoints* (http://localhost:9393/) needs to be encapsulated within LDAP based security layer.Reference:[Authentication using LDAP|https://spring.io/guides/gs/authenticating-ldap/]',8,'Marius Bogoevici','Issues'),('Spring_XD','XD-2122','Secure endpoints using either ROLE_VIEWER and ROLE_ADMIN','As a user I\'d like to have the option to configure default access control for endpoints so that I can grant access by _Admin_ or _Viewer_ roles.',8,'Eric Bottard','Issues'),('Spring_XD','XD-2123',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2124','Research integration options for Sqoop \'tasklet\'','As a user I\'d like to have the ability to mass-ingest data from various database systems so that I\'m not restricted with the current approach (_jdbchdfs_) that is dependent on JDBC drivers. *Spike Scope:** Identify integration options* Collaborate to determine the design* Document outcome (design specs)',5,'Thomas Risberg','Issues'),('Spring_XD','XD-213','Temporarily add toString() Logic in Local Mode Inter-Module Comms',NULL,2,'Gary Russell','Issues'),('Spring_XD','XD-2130','Add Cassandra sink','As a user I\'d like to have the option of _Cassandra_ sink so I can leverage the NoSQL database to write high volumes of variable data segments in high velocity.',3,'Artem Bilan','Issues'),('Spring_XD','XD-2139','Add ftp sink to default sink modules','It would be nice to have a simple ftp sink. I had to do it for one of my projects. Therefore the sink already exists. I would like to contribute but I don\'t know how you do the \'testing\' part for that kind of module.',2,'Gunnar Hillert','Issues'),('Spring_XD','XD-214',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2140','Deployment properties should use label instead of name','stream create foo --definition \"label: bar | xxxx\"stream deploy foo --properties \"module.label.yyy=zzz\" seems to work but it does not. The pre-validation is correct but downstream deployment logic still looks for module.bar (instead of module.label)',3,'Mark Fisher','Issues'),('Spring_XD','XD-2143','Add Basic Auth support','As a user I\'d like to have the option of _Basic Auth_ so that I\'m challenged to provide _user name_ and _password_ when making a request.Technical Implementation:This functionality is provided in Spring Boot 1.1.x it should be a matter of adding the spring boot security starter dependency to the spring-xd-dirt project.  It will be controlled using the spring boot property server.basic.enabled = true/false.  Our default in application.yml for this property should be false.',1,'Marius Bogoevici','Issues'),('Spring_XD','XD-2144','Support Spring Boot\'s single-user security configurations','As a user I\'d like to have the option to provide single-user security configurations so that I can override them as needed.*Reference:*[Spring Boot - Security|http://docs.spring.io/spring-boot/docs/1.1.x-SNAPSHOT/reference/html/boot-features-security.html]*Scope:*Configurations can be provided through _servers.yml_ file.',1,'Marius Bogoevici','Issues'),('Spring_XD','XD-2145','XD Shell needs to be be able to authenticate using basic auth to admin server','As a user I want to be able to provide security credentials to the XD Shell so that I can interact with an xd admin server that is secured via basic authTechnical implementation:Add ---password and --username to the admin config command.',5,'Marius Bogoevici','Issues'),('Spring_XD','XD-2146','Upgrade to spring boot 1.1.7.SNAPSHOT','As a user I\'d like to have latest Spring Boot snapshot pulled as a dependency so that I can inherit and implement the OOTB security features.',1,'Marius Bogoevici','Issues'),('Spring_XD','XD-2147','Upgrade to spring boot 1.1.7.RELEASE','As a user I\'d like to have latest Spring Boot RELEASE pulled as a dependency so that I can inherit and implement the OOTB security features.',1,'Marius Bogoevici','Issues'),('Spring_XD','XD-2148','Create separate distribution for shell','Create zip distribution for shell',1,'Kashyap Parikh','Issues'),('Spring_XD','XD-2149','Remove un-necessary libs from shell','Shell currently adds all jars from xd/lib to its classpath. Remove jars that are not needed to run shell.',1,'Kashyap Parikh','Issues'),('Spring_XD','XD-215',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2151','HDFS sink should honor --fileExtension parameter for bzip2 compressed files','Looks like the --fileExtension isn\'t used when compressing files with bzip2 some use cases requirer bz2 instead of bzip2 as the extension. Also \'.bz2\' should be the default extension. At the same time we should change the default gzip extension to \'.gz\'.',3,'Thomas Risberg','Issues'),('Spring_XD','XD-2154','Research REST endpoint approach to push custom module','As a user I\'d like to have a REST API to point and push an archive that includes custom module definitions and configurations so that I don\'t have to manually move and set it up.*Scope of this spike:** Assess customer requirement brainstorm and document options* Socialize with the team to collect feedback* Identify phases* Create new stories',8,'Eric Bottard','Issues'),('Spring_XD','XD-2155','UI: Add Tooltip Directive','Small follow up story to XD-2094 to improve tooltip handling.',1,'Gunnar Hillert','Issues'),('Spring_XD','XD-2158','Provide Docker image for developers','As a user I need a \'sandbox\' Docker Image so that I can get started to experiment XD deployment with the following setup:* Ubuntu OS* Full XD Jar* Java 7.x* Redis* RabbitMQ',5,'Eric Bottard','Issues'),('Spring_XD','XD-216',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2169','Evaluate Spring Boot dependency upgrade','As a user I\'d like to evaluate Spring Boot dependency upgrades so that I can make sure there aren\'t any side effects or impacts to existing functionalities.',3,'Marius Bogoevici','Issues'),('Spring_XD','XD-217',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2170','NoNodeException for job creation','The following exception was encountered by a few parties: for example https://gopivotal-com.socialcast.com/messages/21678398{noformat}ERROR LeaderSelector-0 leader.LeaderSelector - The leader threw an exceptionorg.apache.zookeeper.KeeperException$NoNodeException: KeeperErrorCode = NoNode for /xd/deployments/jobs/NNNN/modulesat org.apache.zookeeper.KeeperException.create(KeeperException.java:111)at org.apache.zookeeper.KeeperException.create(KeeperException.java:51)at org.apache.zookeeper.ZooKeeper.getChildren(ZooKeeper.java:1586)at org.apache.curator.framework.imps.GetChildrenBuilderImpl$3.call(GetChildrenBuilderImpl.java:214)at org.apache.curator.framework.imps.GetChildrenBuilderImpl$3.call(GetChildrenBuilderImpl.java:203)at org.apache.curator.RetryLoop.callWithRetry(RetryLoop.java:107)at org.apache.curator.framework.imps.GetChildrenBuilderImpl.pathInForeground(GetChildrenBuilderImpl.java:199)at org.apache.curator.framework.imps.GetChildrenBuilderImpl.forPath(GetChildrenBuilderImpl.java:191)at org.apache.curator.framework.imps.GetChildrenBuilderImpl.forPath(GetChildrenBuilderImpl.java:38)at org.springframework.xd.dirt.server.JobDeploymentListener.recalculateJobStates(JobDeploymentListener.java:197)at org.springframework.xd.dirt.server.DeploymentSupervisor$LeaderListener.takeLeadership(DeploymentSupervisor.java:389)at org.apache.curator.framework.recipes.leader.LeaderSelector$WrappedListener.takeLeadership(LeaderSelector.java:536)at org.apache.curator.framework.recipes.leader.LeaderSelector.doWork(LeaderSelector.java:398)at org.apache.curator.framework.recipes.leader.LeaderSelector.doWorkLoop(LeaderSelector.java:443)at org.apache.curator.framework.recipes.leader.LeaderSelector.access$100(LeaderSelector.java:63)at org.apache.curator.framework.recipes.leader.LeaderSelector$2.call(LeaderSelector.java:244)at org.apache.curator.framework.recipes.leader.LeaderSelector$2.call(LeaderSelector.java:238)at java.util.concurrent.FutureTask.run(FutureTask.java:266)at java.util.concurrent.Executors$RunnableAdapter.call(Executors.java:511)at java.util.concurrent.FutureTask.run(FutureTask.java:266)at java.util.concurrent.ThreadPoolExecutor.runWorker(ThreadPoolExecutor.java:1142)at java.util.concurrent.ThreadPoolExecutor$Worker.run(ThreadPoolExecutor.java:617)at java.lang.Thread.run(Thread.java:745){noformat}No specific details on reproducing yet; although the Socialcast thread indicates:{quote}I only hit this when I have tried to deploy a job that fails deployment the first time{quote}',5,'Patrick Peralta','Issues'),('Spring_XD','XD-2171','Document Kafka source',NULL,1,'Eric Bottard','Issues'),('Spring_XD','XD-2177','Add support for Pivotal HD 2.1 (XD 1.0.2 Release)','*XD 1.0.2 Release + PHD 2.1 Upgrade - Action Items:** Update to SHDP 2.0.3* Add Hadoop 2.5 (hadoop25)* Change PHD 2.x from phd20 to phd21* Test PHD 2.0 with phd21 * Document that both PHD 2.1 and PHD 2.0 is supported with phd21',3,'Thomas Risberg','Issues'),('Spring_XD','XD-2178','Add remote partitioning on \'jdbchdfs\' job','As a user I\'d like to have the option to supply data partitioning strategy so that I can parallelize ingest of data from RDBMS to HDFS.',8,'Thomas Risberg','Issues'),('Spring_XD','XD-2180','Expose property to change \"commit-interval\"','As a user I\'d like to override the default \"commit-interval\" so that I can configure commit interval depending on data volume.*Note:*This would apply for all OOTB jobs that has partition support. The property could be part of _servers.yml_ file.',3,'Thomas Risberg','Issues'),('Spring_XD','XD-2181','Document how to enable SSL and Basic authentication','As a user I want to know my configuration options are for enabling SSL/HTTPS and Basic authentication for administration endpoints so that I can secure my application.',1,'Marius Bogoevici','Issues'),('Spring_XD','XD-2182','Document how to enable LDAP security for admin endpoints','As a user I want to know how to enable and configure LDAP as an authentication provider for the administration server so that I can set up my security configuration accordingly.',1,'Marius Bogoevici','Issues'),('Spring_XD','XD-219',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2190','xd-shell from 1.0.1 doesn\'t work with 1.0.0 GA admin','Targeting xd-shell from 1.0.1 to 1.0.0 GA admin server failsserver-unknown:>admin config info  -------------  -------------------------------------------------------------  Result         Unable to contact XD Admin Server at \'http://localhost:9393\'.  Target         http://localhost:9393  Timezone used  Pacific Standard Time (UTC -8:00)  -------------  --------------------------------------------------------------------------------------------------------------------------------------------An exception ocurred during targeting:java.lang.NullPointerException    at org.springframework.xd.rest.client.impl.SpringXDTemplate.<init>(SpringXDTemplate.java:110)    at org.springframework.xd.rest.client.impl.SpringXDTemplate.<init>(SpringXDTemplate.java:137)    at org.springframework.xd.shell.command.ConfigCommands.target(ConfigCommands.java:106)    at org.springframework.xd.shell.command.ConfigCommands.afterPropertiesSet(ConfigCommands.java:191)',1,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2192','Fix failing script integration test','See https://build.spring.io/browse/XD-SCRIPTS-723',3,'Thomas Risberg','Issues'),('Spring_XD','XD-2196','Refactor ContainerRegistrar','Decouple from DeploymentListener. Make DL a public class to handle deployment related events.  Remove createSimpleModule() and createComposedModule() from DL.  This will be delegated to ModuleDeployer which will eventually be further refactored to use the proposed ModuleFactory.',3,'David Turanski','Issues'),('Spring_XD','XD-2197','Create ModuleFactory','ModuleFactory is responsible for determining how the Module application context is created from available sources at the resource location exposed via the ModuleDefinition. The factory creates the application context and creates a SimpleModule or CompositeModule as appropropriate. For example if an XML file is present it is assumed to be the bean definition file used to create a CXMLAC. If no XML file is present inspect the properties file for the existence of well-known properties such as base-package-name for component scanning for an @Configuration or a module-class-name for an Annotated POJO based module (see XD-2100).  The MF is also responsible for creating composite modules.   Also includes Module refactoring add getApplicationContext() and probably setApplicationContext().  Also refactor CompositeModule code to use boot SpringApplicationBuilder',5,'David Turanski','Issues'),('Spring_XD','XD-2198','Create CompositeModuleRegistry','Currently there is no ModuleRegistry contract for composite modules. The composed module definition is maintained in ZooKeeperModuleDefinitionRepository which delegates to the ModuleRegistry to define and validate component modules. The repository should be converted to a ModuleRegistry.',5,'Eric Bottard','Issues'),('Spring_XD','XD-2199','Simplify ModuleRegistry','MR is responsible for looking up existing module definitions by name and type.  ModuleDefinition should contain name type and resource; where resource is a springframework.core.io.Resource containing the root path of the module definition. This could be file classpath http hdfs or something else but the contents under this path will not be inspected or processed by MR. The exception is for composite modules which should contain a list of corresponding Resources.Simplify ModuleDefinition - remove classpath. Provide support for CompositeModuleDefinition - requires a list of resources (possibly a subclass)Also retire RedisModuleRegistry',8,'Eric Bottard','Issues'),('Spring_XD','XD-22','Create Module base abstractions','A module groups together a collection of spring configuration files.',0,'Mark Fisher','Issues'),('Spring_XD','XD-220',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2203','Make sure Spring XD\'s PDF reference doc has right release revision references','The scope is to make sure that a new PDF is generated (both for 1.0.2 and 1.1 M1 releases) and/or revision references are correctly rendered.',0,'Gunnar Hillert','Issues'),('Spring_XD','XD-2205','Add Python processor','As a user I\'d like to have a _Python_ processor so that I can efficiently perform data computations and statistical analysis. Investigate the right approach (native or via stdin/stdout) that fits Spring XD model.[Integrate Java and Python|https://wiki.python.org/moin/IntegratingPythonWithOtherLanguages#Java]',8,'David Turanski','Issues'),('Spring_XD','XD-2209','Add acceptance test to include Gemfire use case','To enrich acceptance test I\'d like to have basic coverage to evaluate Gemfire use cases. An example would be to ingest data from HTTP source and write it to Gemfire server.',2,NULL,'Issues'),('Spring_XD','XD-221','Links in asciidoctor generated HTML+docbook documentation are broken','The issue arises because the link:document[Label] asciidoc macro is meant for \"external documents\" and creates {{<ulink>}} in docbook / {{<a href=\"document\">}} in html whereas we want {{<link linkend=\"anchor\">}} / {{<a href=\"doc#anchor>}} resp. We also want it to continue working in github live view.I guess what could work is to have the macro (either override the link macro or create our own if github supports that) that looks like :{{link:document#anchor[Label]}}  (the #anchor works out of the box in asciidoc and should work in github) but override it for the html and docbook backends to render to the correct form.The thing is there are several ways to create/override macros (and templates they render to) some of which make sense to our setup:- having asciidoc.conf in the directory of the processed document (http://asciidoc.org/userguide.html#X27)- having docbook.conf/html.conf in the directory of the processed document (http://asciidoc.org/userguide.html#X27)- defining macros using attributes (http://asciidoc.org/userguide.html#_setting_configuration_entries)I tried all of those but to no avail. These DO WORK with plain asciidoc but not with our toolchain. Don\'t know if the problem is with asciidocTOR or with the gradle wrapper though.',2,'Eric Bottard','Issues'),('Spring_XD','XD-2210','Enhance JDBC sink test to include more options','To enrich acceptance test I\'d like to add coverage to JDBC sink by including *-- driverclass* and *-- url* options.',2,NULL,'Issues'),('Spring_XD','XD-2212',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2213','Add stress test','To enrich acceptance test coverage I\'d like to have stress test scenario that includes ingesting data from _HTTP_ and then writing it to _Log_ sink.',3,NULL,'Issues'),('Spring_XD','XD-2215','NPE in ContainerRedeploymentTests','Running the distributed tests ({{-Drun_distributed_tests=true}}) against d109a3a and got the following:{noformat}   java.lang.NullPointerException   at org.springframework.xd.dirt.module.store.ZooKeeperModuleMetadataRepository.updateDeploymentStatus(ZooKeeperModuleMetadataRepository.java:209)   at org.springframework.xd.dirt.module.store.ZooKeeperModuleMetadataRepository.findAllByContainerId(ZooKeeperModuleMetadataRepository.java:313)   at org.springframework.xd.dirt.container.store.ZooKeeperContainerRepository.findAllRuntimeContainers(ZooKeeperContainerRepository.java:339)   at org.springframework.xd.dirt.rest.ContainersController.list(ContainersController.java:97)   at sun.reflect.GeneratedMethodAccessor100.invoke(Unknown Source)   at sun.reflect.DelegatingMethodAccessorImpl.invoke(DelegatingMethodAccessorImpl.java:43)   at java.lang.reflect.Method.invoke(Method.java:483)   at org.springframework.web.method.support.InvocableHandlerMethod.invoke(InvocableHandlerMethod.java:215)   at org.springframework.web.method.support.InvocableHandlerMethod.invokeForRequest(InvocableHandlerMethod.java:132)   at org.springframework.web.servlet.mvc.method.annotation.ServletInvocableHandlerMethod.invokeAndHandle(ServletInvocableHandlerMethod.java:104)   at org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerAdapter.invokeHandleMethod(RequestMappingHandlerAdapter.java:749)   at org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerAdapter.handleInternal(RequestMappingHandlerAdapter.java:689)   at org.springframework.web.servlet.mvc.method.AbstractHandlerMethodAdapter.handle(AbstractHandlerMethodAdapter.java:83)   at org.springframework.web.servlet.DispatcherServlet.doDispatch(DispatcherServlet.java:938)   at org.springframework.web.servlet.DispatcherServlet.doService(DispatcherServlet.java:870)   at org.springframework.web.servlet.FrameworkServlet.processRequest(FrameworkServlet.java:961)   at org.springframework.web.servlet.FrameworkServlet.doGet(FrameworkServlet.java:852)   at javax.servlet.http.HttpServlet.service(HttpServlet.java:620)   at org.springframework.web.servlet.FrameworkServlet.service(FrameworkServlet.java:837)   at javax.servlet.http.HttpServlet.service(HttpServlet.java:727)   at org.apache.catalina.core.ApplicationFilterChain.internalDoFilter(ApplicationFilterChain.java:{noformat}',2,'Patrick Peralta','Issues'),('Spring_XD','XD-2216','Upgrade to Spring 4.1.2 SI 4.1.0 SA 1.4.0','As a user I\'d like to have Spring \'Core\' upgraded to 4.1.1 (_milestone_ ) so that I can benefit from performance improvements associated with \'compiled\' SpEL and other enhancements.',3,'Gary Russell','Issues'),('Spring_XD','XD-222',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2223','Provide proper ordering for all REST endpoints','With the implementation of XD-1864 we need to make sure that the (paginated) data returned from the REST endpoints has proper default ordering.Up to now we have done client-side ordering in the Admin UI but with server-side pagination the server-side should support proper pagination as well.Eventually we may even decide to provide more flexible ordering options (ASC vs DESC sort on different properties etc.) which may be a separate Jira.',8,'Gunnar Hillert','Issues'),('Spring_XD','XD-2224','REST: Make the Configurations REST endpoint pagination-aware','Add pagination for:http://localhost:9393/jobs/configurationsRelated to XD-1864',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2225','REST: Make the Job Execution REST endpoint pagination-aware','Implement pagination for:http://localhost:9393/jobs/executions',8,'Gunnar Hillert','Issues'),('Spring_XD','XD-2226','Add support for configurable ZK namespace','As a user I\'d like to have the flexibility to change the namespace so that I can isolate ZK _metadata_ based on each _tenant_ profile.',5,'Mark Fisher','Issues'),('Spring_XD','XD-2228','Remove logging of password in Shell','As a user I\'d like to type the _username_ and _password_ to gain access to Admin server so that I don\'t have to add it in some file; hence I don\'t have to worry about having the password getting logged somewhere.',5,'Marius Bogoevici','Issues'),('Spring_XD','XD-223',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2230','Fix the configuration problem with Filter and Transform modules','As a user I\'d like to leverage _propertieis-location_ parameter while using *Filter* or *Transform* modules so that I can load the user-defined properties included in the external properties file. Attempting to include the _propertieis-location_ attribute errors out - refer to the attachment.It could also be beneficial to load user-defined properties through stream definition similar to deployment properties.Example:--script=myscript.groovy --variables=foo=bargoo=gaz',5,'David Turanski','Issues'),('Spring_XD','XD-2231','Document job repo schema overrides','As a user I\'d like to have the flexibility to configure DB creds so that I can use a DB of choice for batch job repository (metadata persistence). The scope of this task is to have the configuration specifics documented in the wiki.',2,'Michael Minella','Issues'),('Spring_XD','XD-2234','Incorrect port in resource manager address overwrite','the resource manager address overwrite is setting the port to 8032; the value cannot be set in servers.yml.  this occurs when pushing the config to hdfs and also when attempting to start the admin server on yarn. [ConfigurationFactoryBean] - Overwriting rmAddress=[0.0.0.0:8032] with rmAddress=[host:8032][root spring-xd-1.0.1.RELEASE-yarn]# ./bin/xd-yarn start admin  .   ____          _            __ _ _ /\\\\ / ___\'_ __ _ _(_)_ __  __ _ \\ \\ \\ \\( ( )\\___ | \'_ | \'_| | \'_ \\/ _` | \\ \\ \\ \\ \\\\/  ___)| |_)| | | | | || (_| |  ) ) ) )  \'  |____| .__|_| |_|_| |_\\__ | / / / / =========|_|==============|___/=/_/_/_/ :: Spring Boot ::        (v1.1.7.RELEASE)2014-10-13 16:50:28710 INFO [ConfiguringBeanFactoryPostProcessor] - No bean named \'taskScheduler\' has been explicitly defined. Therefore a default ThreadPoolTaskScheduler will be created.2014-10-13 16:50:28724 INFO [ConfiguringBeanFactoryPostProcessor] - No bean named \'taskExecutor\' has been explicitly defined. Therefore a default SyncTaskExecutor will be created.2014-10-13 16:50:30311 INFO [SpringYarnConfiguration] - Enabling CLIENT for Yarn2014-10-13 16:50:30335 INFO [SpringYarnConfiguration] - We couldn\'t figure out if we could use existing configuration2014-10-13 16:50:30335 INFO [SpringYarnConfiguration] - Building configuration for bean \'yarnConfiguration\'2014-10-13 16:50:30383 INFO [SpringYarnConfigBuilder] - Existing yarnConfiguration: null2014-10-13 16:50:30658 INFO [ConfigurationFactoryBean] - Overwriting fsUri=[hdfs://host:8020] with fsUri=[hdfs://host:8020]2014-10-13 16:50:30659 INFO [ConfigurationFactoryBean] - Overwriting rmAddress=[0.0.0.0:8032] with rmAddress=[host:8032]',1,NULL,'Issues'),('Spring_XD','XD-2235','Basic authentication realm is always \'null\'','Besides the Basic authentication realm being always {{null}} {{security.basic.realm}} is always ignored.',1,'Marius Bogoevici','Issues'),('Spring_XD','XD-2237','Provide Python module to handle I/O for implementing a Python shell processor',NULL,2,'David Turanski','Issues'),('Spring_XD','XD-2238','Improve module deployment distribution','When a container joins the XD cluster (via ZooKeeper) it triggers stream/job module deployments for modules that need to be deployed. If multiple containers are being started at around the same time this can result in the first few containers taking all of the deployments while leaving the rest without any deployments.To solve this we will introduce a \"quiet period\" where no deployments will be triggered within _n_ seconds of a container joining where _n_ will have a default value (perhaps 5 to 10 seconds). This value will be configurable.',5,'Patrick Peralta','Issues'),('Spring_XD','XD-2239','Fix incorrect IP Address associated with containers','The XD Container IP address displayed on both \'singlenode\' and Distributed modes are incorrect both on _Shell_ as well as _Admin-UI_. *Example:*Noticed IP address as 10.10.10.*Following function in [RuntimeUtils|http://docs.spring.io/autorepo/docs/spring-xd/1.0.1.RELEASE/api/org/springframework/xd/dirt/util/RuntimeUtils.html] could be flawed:{code}public static String getIpAddress() {try {for(Enumeration<NetworkInterface> enumNic = NetworkInterface.getNetworkInterfaces();enumNic.hasMoreElements();) {NetworkInterface ifc = enumNic.nextElement();if (ifc.isUp()) {for (Enumeration<InetAddress> enumAddr = ifc.getInetAddresses();enumAddr.hasMoreElements(); ) {InetAddress address = enumAddr.nextElement();if (address instanceof Inet4Address && !address.isLoopbackAddress()) {return address.getHostAddress();}}}}}catch (IOException e) {// ignore}return \"unknown\";}{code}',5,'Gunnar Hillert','Issues'),('Spring_XD','XD-224',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2244','Streams sending to Job Queue issue','Look at the below Stream definition. This gets to \"deployed\" state even without the corresponding job. And then from there the same Job or any other Job can\'t be deployed and it goes to a hung state. Here is an example of the Stream definition:stream create --name jobName --definition \"file --ref=true --dir=/tmp/springxdsource/dropbox --pattern=*.csv > queue:job:filetsjob-sample002\" --deploy',1,NULL,'Issues'),('Spring_XD','XD-2245','Gemfire Source throws classnotfound','* Steps to reproduce.** Start admin & container.** Follow the instructions from https://github.com/spring-projects/spring-xd/wiki/Sources#gemfire-source*** When you post the message is when the stacktrace shows up in the container.Copying the gemfire-7.0.2.jar to the lib directory will resolve the error.  The stacktrace is attached.',1,'David Turanski','Issues'),('Spring_XD','XD-2246','Document default behavior if config option is not present','As a user I\'d like to have the flexibility to specify config options for IP and Hostname so that I can list the correct configuration for XD Admin and XD Container servers in the Admin-UI and Shell.',1,'Gunnar Hillert','Issues'),('Spring_XD','XD-2247','Log version number in log files','When answering support questions the first step is to determine what version of the software the customer is using. This question can be easily answered if we log the version as one of the fields in the log file. For example:{noformat}10:44:21212 1.0.2.BUILD-SNAPSHOT  INFO DeploymentSupervisorCacheListener-0 server.ContainerListener - Container arrived: Container{name=\'431baa56-b23b-48fc-b37d-18b52231e799\' attributes={ip=192.168.25.177 host=Patrick-Peralta-MacBook-Pro.local groups= pid=38004 id=431baa56-b23b-48fc-b37d-18b52231e799}}{noformat}This way when we receive log snippets (initial support inquires rarely include the entire log file) we can immediately determine if the issue has already been fixed in a later release.',2,'Patrick Peralta','Issues'),('Spring_XD','XD-225',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-2251','The HTTP Source creates the ChannelPipeline inefficiently','The ChannelPipelineFactory used by the HTTP source should cache expensive objects used by the ChannelPipeline between requests because creating them every time is inefficient (and in the case of HTTPS it can become even more expensive).',1,'Marius Bogoevici','Issues'),('Spring_XD','XD-2253','Baseline tcp measurements (DB-1)','Using the [iperf tool|https://iperf.fr/] find out the transfer rate in MB/sec between three machines in a four machine configuration.',1,'Sabby Anandan','Issues'),('Spring_XD','XD-2254','Vary message size (DB-2)','Use a single producer single consumer prefetch size = 50.  Send 1M messages and increase or decrease so that a given test iteration takes about 2 minutes.Vary the message size and measure the msg/sec rate and calculate data transfer rate in MB/sec.*Message Sizes:*100 bytes100010000100000 During the measurements look at the RabbitMQ Admin UI and see if the queue is backing up.',1,'Chris Schaefer','Issues'),('Spring_XD','XD-2255','Vary prefetch size (DB-3)','Use a single producer single consumer message size of 1000 bytes.   Send 1M messages and increase or decrease so that a given test iteration takes about 2 minutes.Vary the prefetch size.  Measure the msg/sec rate and calculate the data transfer rate in MB/sec.*Prefetch Sizes:** 1* 10* 50* 100* 10000During the measurements look at the RabbitMQ Admin UI and see if the queue is backing up.',1,'Chris Schaefer','Issues'),('Spring_XD','XD-2256','Vary consumers size (DB-4)','Using a single producer message size of 1000 bytes Pretch of 100.   Send 1M messages and increase or decrease so that a given test iteration takes about 2 minutes.Vary the number of consumers.   Measure the msg/sec rate and calculate the data transfer rate in MB/sec.*Number of consumers:** 1* 2* 4* 6* 10* 50During the measurements look at the RabbitMQ Admin UI and see if the queue is backing up.',1,'Chris Schaefer','Issues'),('Spring_XD','XD-2257','Vary producers size (DB-5)','Use the number of consumers gave a maximum throughput in the previous test (say 10 consumers) message size 100 bytes Prefetch 100.   Send 1M messagesVary the number of producers.  Measure the msg/sec rate and calculate the data transfer rate in MB/sec.*Number of producers:** 2* 4* 6* 10* 50During the measurements look at the RabbitMQ Admin UI and see if the queue is backing up.',1,'Chris Schaefer','Issues'),('Spring_XD','XD-2258','Research adding support for \'spring-cloud-config\' to configure Modules','Please refer to the GH Issue reported here: https://github.com/spring-projects/spring-xd/issues/1218',8,'Marius Bogoevici','Issues'),('Spring_XD','XD-2259','Infrastructure for RabbitMQ Cluster (DB)','Pre-requisite for Rabbit MQ Benchmarks:* Infrastructure setup* Configuration changes* Tool-chain setup',1,'Chris Schaefer','Issues'),('Spring_XD','XD-226','Cleanup and Optimize gradle tasks to bundle spring-xd distribution','We need to cleanup some of the duplicate gradle tasks that bundle spring-xd distributions. Currently distXD does the copy of distributions from \"spring-xd-dirt\" \"redis\" and \"spring-xd-gemfire-server\" projects into \"$rootDir/dist/spring-xd\".And the task \"zipXD\" makes the zip archive.These tasks should be combined with the \"distZip\" & \"docZip\" tasks.We also need to remove the duplicate artifacts configuration from these tasks.',2,'Gunnar Hillert','Issues'),('Spring_XD','XD-2260','Document Admin and Viewer roles','As a user I\'d like to have the option to configure _Admin_ and _Viewer_ roles so that I\'ll have the flexibility to decide role configurations.',0,NULL,'Issues'),('Spring_XD','XD-2261','Document user-defined permission to role mapping','As a user I\'d like to have the option to configure permissions so that I\'ll have the flexibility to bind permissions (REST endpoint) to a specific role. Default Roles:* Admin (CRUD)* Viewer (R)',2,'Eric Bottard','Issues'),('Spring_XD','XD-2262','Document \'idleTimeout\' setting','Document --idleTimeout setting to not exceed the HDFS timeout value.',1,'Thomas Risberg','Issues'),('Spring_XD','XD-2264','Infrastructure for RabbitMQ Cluster (ECB)','Pre-requisite for Rabbit MQ Benchmarks:* Infrastructure setup* Configuration changes* Tool-chain setup* IPerf',5,'Glenn Renfro','Issues'),('Spring_XD','XD-2265','Vary consumers size (ECB-4)','Using a single producer message size of 1000 bytes Pretch of 100.   Send 1M messages and increase or decrease so that a given test iteration takes about 2 minutes.Vary the number of consumers.   Measure the msg/sec rate and calculate the data transfer rate in MB/sec.*Number of consumers:** 1* 2* 4* 6* 10* 50During the measurements look at the RabbitMQ Admin UI and see if the queue is backing up.',3,'Glenn Renfro','Issues'),('Spring_XD','XD-2266','Vary producers size (ECB-5)','Use the number of consumers gave a maximum throughput in the previous test (say 10 consumers) message size 100 bytes Prefetch 100.   Send 1M messagesVary the number of producers.  Measure the msg/sec rate and calculate the data transfer rate in MB/sec.*Number of producers:** 2* 4* 6* 10* 50During the measurements look at the RabbitMQ Admin UI and see if the queue is backing up.',3,'Glenn Renfro','Issues'),('Spring_XD','XD-2268','Create a maintenance branch','As a developer I\'d like to have a maintenance branch so that I can commit MINOR release _(ex: 1.0.2)_ code changes instead of committing to MASTER.',5,'Mark Fisher','Issues'),('Spring_XD','XD-2269','Remove deprecated functions','As a follow-up action from module registry refactoring we would have to clean-up deprecated functions _(ex: download of module definitions)_ within our codebase. It may also be necessary to clean-up Shell and Admin-UI modules.',3,'Eric Bottard','Issues'),('Spring_XD','XD-227','Add jetty-util-6.1.26.jar and jsr311-api-1.1.1.jar as required jars so they will be on the XD classpath','This is needed for the use of the webhdfs:// scheme to talk to HDFS over http.',1,'Jennifer Hickey','Issues'),('Spring_XD','XD-2270','Upgrade to Spring Boot 1.2.0','As to prepare for 1.1 release we would like to upgrade to Spring Boot 1.2.0 (RC1) (depends on Spring 4.1.2) so that we can leverage the new features enhancement and bug fixes. [Spring Boot Milestones|https://github.com/spring-projects/spring-boot/milestones]',3,'Thomas Risberg','Issues'),('Spring_XD','XD-2271','Upgrade to Spring Integration 4.1.0','As to prepare for 1.1 release we would like to upgrade to Spring Integration 4.1.0 (RC) so that we can leverage the new features enhancement and bug fixes.',3,'Gary Russell','Issues'),('Spring_XD','XD-2274','Intermittent TcpModulesTests.testTcpSink test failure','{noformat}org.junit.ComparisonFailure: org.junit.ComparisonFailure: expected:<[Hi there!]> but was:<[]>org.junit.ComparisonFailure: expected:<[Hi there!]> but was:<[]>at org.junit.Assert.assertEquals(Assert.java:115)at org.junit.Assert.assertEquals(Assert.java:144)at org.springframework.xd.shell.command.TcpModulesTests.testTcpSink(TcpModulesTests.java:63)at sun.reflect.NativeMethodAccessorImpl.invoke0(Native Method)(60 more lines...){noformat}https://build.spring.io/browse/XD-JDK8-JOB1-1162/test',1,'Patrick Peralta','Issues'),('Spring_XD','XD-2275','Vary Producer and Consumer in combination using 2 Queues (ECB-6)','The results from EC2 testing show that once prefetch and message size are set varying the number of producers or consumers independently does not impact the message rate.  The in-house testing numbers need another plan to try an understand some discrepancies. Using 500 prefetch 1000 byte message size run two instances of PerfTest at the same time with each instance referencing a different queue.  Vary the number of consumer and publishers.Test 1 (one producer / one consumer):-a -u q1 -p -x 1 -y 1 -s 1000 -z 60 -q 500-a -u q2 -p -x 1 -y 1 -s 1000 -z 60 -q 500Test 2 (one producer / two consumers):-a -u q1 -p -x 1 -y 2 -s 1000 -z 60 -q 500-a -u q2 -p -x 1 -y 2 -s 1000 -z 60 -q 500Test 3 (two producers / one consumer):-a -u q1 -p -x 2 -y 1 -s 1000 -z 120 -q 500-a -u q2 -p -x 2 -y 1 -s 1000 -z 120 -q 500Test 4 (two producers / two consumers):-a -u q1 -p -x 2 -y 2 -s 1000 -z 60 -q 500-a -u q2 -p -x 2 -y 2 -s 1000 -z 60 -q 500',3,'Glenn Renfro','Issues'),('Spring_XD','XD-2276','Vary message size (EC-DB-2)','Use a single producer single consumer prefetch size = 50.  Send 1M messages and increase or decrease so that a given test iteration takes about 2 minutes.Vary the message size and measure the msg/sec rate and calculate data transfer rate in MB/sec.*Message Sizes:*100 bytes100010000100000 During the measurements look at the RabbitMQ Admin UI and see if the queue is backing up.',3,'Glenn Renfro','Issues'),('Spring_XD','XD-2277','Vary prefecth size (EC-DB-3)','Use a single producer single consumer message size of 1000 bytes.   Send 1M messages and increase or decrease so that a given test iteration takes about 2 minutes.Vary the prefetch size.  Measure the msg/sec rate and calculate the data transfer rate in MB/sec.*Prefetch Sizes:** 1* 10* 50* 100* 10000During the measurements look at the RabbitMQ Admin UI and see if the queue is backing up.',3,'Glenn Renfro','Issues'),('Spring_XD','XD-2278','Vary queue number (ECB-7)','Based on the the results from B-6 select the number of consumer/producers that give a distinct >5% increase in message rate.  Below 5% change in message rate prefer lower consumer/producer count.    Vary the number of PerfTest instances that are run simultaneously and use their own independent queue from 1 until the overall messages/sec on the broker plateaus.   Note the CPU performance using ΓÇÿtopΓÇÖ for the broker and PerfTest processes.Test 1 (2 queues)-a -u q1 -p -x 1 -y 1 -s 1000 -z 60 -q 500-a -u q2 -p -x 1 -y 1 -s 1000 -z 60 -q 500Test 2 (3 queues)-a -u q1 -p -x 1 -y 1 -s 1000 -z 60 -q 500-a -u q2 -p -x 1 -y 1 -s 1000 -z 60 -q 500-a -u q3 -p -x 1 -y 1 -s 1000 -z 60 -q 500Test 3 (4 queues)-a -u q1 -p -x 1 -y 1 -s 1000 -z 60 -q 500-a -u q2 -p -x 1 -y 1 -s 1000 -z 60 -q 500-a -u q3 -p -x 1 -y 1 -s 1000 -z 60 -q 500-a -u q4 -p -x 1 -y 1 -s 1000 -z 60 -q 500Test 4 (5 queues)-a -u q1 -p -x 1 -y 1 -s 1000 -z 60 -q 500-a -u q2 -p -x 1 -y 1 -s 1000 -z 60 -q 500-a -u q3 -p -x 1 -y 1 -s 1000 -z 60 -q 500-a -u q4 -p -x 1 -y 1 -s 1000 -z 60 -q 500-a -u q5 -p -x 1 -y 1 -s 1000 -z 60 -q 500etc.',3,'Glenn Renfro','Issues'),('Spring_XD','XD-2279','Vary consumer size (EC-DB-4)','Using a single producer message size of 1000 bytes Pretch of 100.   Send 1M messages and increase or decrease so that a given test iteration takes about 2 minutes.Vary the number of consumers.   Measure the msg/sec rate and calculate the data transfer rate in MB/sec.*Number of consumers:** 1* 2* 4* 6* 10* 50During the measurements look at the RabbitMQ Admin UI and see if the queue is backing up.',2,'Glenn Renfro','Issues'),('Spring_XD','XD-2280','Vary producer size (EC-DB-5)','Use the number of consumers gave a maximum throughput in the previous test (say 10 consumers) message size 100 bytes Prefetch 100.   Send 1M messagesVary the number of producers.  Measure the msg/sec rate and calculate the data transfer rate in MB/sec.*Number of producers:** 2* 4* 6* 10* 50During the measurements look at the RabbitMQ Admin UI and see if the queue is backing up.',3,'Glenn Renfro','Issues'),('Spring_XD','XD-2281','Vary Producer and Consumer in combination using 2 Queues (B-6)','The results from EC2 testing show that once prefetch and message size are set varying the number of producers or consumers independently does not impact the message rate.  The in-house testing numbers need another plan to try an understand some discrepancies. Using 500 prefetch 1000 byte message size run two instances of PerfTest at the same time with each instance referencing a different queue.  Vary the number of consumer and publishers.Test 1 (one producer / one consumer):* -a -u q1 -p -x 1 -y 1 -s 1000 -z 60 -q 500* -a -u q2 -p -x 1 -y 1 -s 1000 -z 60 -q 500Test 2 (one producer / two consumers):* -a -u q1 -p -x 1 -y 2 -s 1000 -z 60 -q 500* -a -u q2 -p -x 1 -y 2 -s 1000 -z 60 -q 500Test 3 (two producers / one consumer):* -a -u q1 -p -x 2 -y 1 -s 1000 -z 120 -q 500* -a -u q2 -p -x 2 -y 1 -s 1000 -z 120 -q 500Test 4 (two producers / two consumers):* -a -u q1 -p -x 2 -y 2 -s 1000 -z 60 -q 500* -a -u q2 -p -x 2 -y 2 -s 1000 -z 60 -q 500',1,'Chris Schaefer','Issues'),('Spring_XD','XD-2282','Vary queue number (B-7)','Based on the the results from B-6 select the number of consumer/producers that give a distinct >5% increase in message rate.  Below 5% change in message rate prefer lower consumer/producer count.    Vary the number of PerfTest instances that are run simultaneously and use their own independent queue from 1 until the overall messages/sec on the broker plateaus.   Note the CPU performance using ΓÇÿtopΓÇÖ for the broker and PerfTest processes.Test 1 (2 queues)* -a -u q1 -p -x 1 -y 1 -s 1000 -z 60 -q 500* -a -u q2 -p -x 1 -y 1 -s 1000 -z 60 -q 500Test 2 (3 queues)* -a -u q1 -p -x 1 -y 1 -s 1000 -z 60 -q 500* -a -u q2 -p -x 1 -y 1 -s 1000 -z 60 -q 500* -a -u q3 -p -x 1 -y 1 -s 1000 -z 60 -q 500Test 3 (4 queues)* -a -u q1 -p -x 1 -y 1 -s 1000 -z 60 -q 500* -a -u q2 -p -x 1 -y 1 -s 1000 -z 60 -q 500* -a -u q3 -p -x 1 -y 1 -s 1000 -z 60 -q 500* -a -u q4 -p -x 1 -y 1 -s 1000 -z 60 -q 500Test 4 (5 queues)* -a -u q1 -p -x 1 -y 1 -s 1000 -z 60 -q 500* -a -u q2 -p -x 1 -y 1 -s 1000 -z 60 -q 500* -a -u q3 -p -x 1 -y 1 -s 1000 -z 60 -q 500* -a -u q4 -p -x 1 -y 1 -s 1000 -z 60 -q 500* -a -u q5 -p -x 1 -y 1 -s 1000 -z 60 -q 500etc...',1,'Chris Schaefer','Issues'),('Spring_XD','XD-2283','Vary queue number on 32 core machine (ECB-8)','Rerun test XD-2278 on a EC2 32 core machine and see when we max out.',5,'Glenn Renfro','Issues'),('Spring_XD','XD-2286','Simple OOTB job for testing','Similar to {{time | log}} we should ship a simple batch job that appends a timestamp to a file. This will make it much easier to validate job functionality especially in automated tests.',2,'Patrick Peralta','Issues'),('Spring_XD','XD-2287','Have ResourceModuleRegistry transparently proxy a remote root thru filesystem','ArchiveModuleRegistry and the use of Boot Archives inherently relies on java.io.FileHave ResourceModuleRegistry extend/compose ArchiveMR to transparently download and cache (remote) jars that may be located in a (non-file:) location.The staging area should be customizable but some subdir of java.io.tmpdir sounds like a sensible default',5,'Eric Bottard','Issues'),('Spring_XD','XD-229','Add RabbitMQ-based implementation of ChannelRegistry',NULL,8,'Mark Fisher','Issues'),('Spring_XD','XD-2296','Add config parameter to enable/disable message rates in cluster view','As a user I\'d like to have a config parameter preferably in _servers.yml_ file so that I can enable/disable message rates in the cluster view.',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-2298','Review POC and identify scope for gpload as OOTB Batch Job','As a user I\'d like to mass ingest data from databases (and others) into HDFS/HAWQ/GPDB so that I don\'t have to write custom code and as well as be able to ingest in an efficient way.',5,'Thomas Risberg','Issues'),('Spring_XD','XD-2299','Placeholder for 1.0.2 and 1.1M1 release testing effort',NULL,8,'Sabby Anandan','Issues'),('Spring_XD','XD-23','add file source and sink modules',NULL,1,'Mark Fisher','Issues'),('Spring_XD','XD-230','Add RabbitMQ source module','configurable parameters should include the queue-name(s) and optional binding key patternconnection info such as host and port should also be configurable but with defaults (localhost and default port) and that should likely fallback to a rabbit.properties file in the $XD_HOME/config directory',3,'Mark Fisher','Issues'),('Spring_XD','XD-2300','Document automatic declaration of DQL for each consumer queue','The scope is to document the automatic creation and binding of DLQ for each \'pipe\' (consumer queue).',0,'Gary Russell','Issues'),('Spring_XD','XD-2301','Research Spark integration options','*Spike scope:** Brainstorm* Identify options* Document',8,'Mark Fisher','Issues'),('Spring_XD','XD-2302','UI: Update AngularJS to v1.3','* https://docs.angularjs.org/guide/migration#migrating-from-1-2-to-1-3* http://angularjs.blogspot.com/2014/10/ng-europe-angular-13-and-beyond.html* http://angularjs.blogspot.com/2014/10/angularjs-130-superluminal-nudge.html',4,'Gunnar Hillert','Issues'),('Spring_XD','XD-2304','Research refactoring effort for Kafka source to use simple consumer instead of high-level API','As a user I\'d like to use Kafka source through simple consumer API (as opposed to high-level) so that I can gain full control to offsets and partition assignment deterministically.*Spike scope*:- Study simple consumer API functionality- Document findings approach and next steps',8,'Marius Bogoevici','Issues'),('Spring_XD','XD-2305','POC for Spark Integration','*Spike Scope:** Experiment with identified options* POC with the logical integration choice',8,'Mark Fisher','Issues'),('Spring_XD','XD-2306','Add support to install custom module archive','As a user I\'d like to push the custom module (built as uber-jar) via a REST API so that I can install the custom module in cluster.',8,'Eric Bottard','Issues'),('Spring_XD','XD-2307','Add support for PHD 2.1 (XD 1.1 M1 Release)','*XD 1.1 M1 Release + PHD 2.1 Upgrade - Action Items:** Update to SHDP 2.1.M2 * Add Hadoop 2.5 (hadoop25)* Remove hadoop22* Remove PHD 1.0 (phd1) * Change PHD 2.x from phd20 to phd21* Test PHD 2.0 with phd21',3,'Thomas Risberg','Issues'),('Spring_XD','XD-2308','Create sample app to demonstrate Kafka integration','As a user I\'d like to have a sample app (GitHub project) so that I can use it as a reference while provisioning Spring XD cluster with Kafka.Consider:* Kafka as message bus* Kafka as source',8,'Marius Bogoevici','Issues'),('Spring_XD','XD-2309','Incremental data import with jdbchdfs job','Enhance the current jdbchdfs job in spring-xd to have an incremental load / delta load feature similar to sqoop. See sqoop documentation [here|http://sqoop.apache.org/docs/1.4.5/SqoopUserGuide.html#_incremental_imports]. The job will need to maintain some state between executions in order to decide the start point for the next data load. The jdbchdfs job definition could take the following 2 new options. h5. checkColumn optionalSpecifies the column to be examined when determining which rows to import. (the column should not be of type CHAR/NCHAR/VARCHAR/VARNCHAR/ LONGVARCHAR/LONGNVARCHAR). Column should be numeric or timestamp.h5. lastValue optionalIf specified this will override any data saved from previous job runs. If not specified will take the saved max-value from the last job run. If no last job run data is available then it will not be an incremental load and all the data which satisfies the query will be used.Sqoop provides 2 modes of operation for incremental load \'append\' and \'lastModified\'. For jdbchdfs the job will always append as it is writing to a hdfs file.Example: To import data from the database table some_table which has a last update column called lastUpdated you could use.{code}xd:> job create myjob --definition \"jdbchdfs --sql=\'select col1col2col3 from some_table\' --checkColumn=lastUpdated\" --deploy{code}The batch job should also be capable of being partitioned to run in parallel across multiple containers',5,'Michael Minella','Issues'),('Spring_XD','XD-231','Add Twitter gardenhose source module','we have a prototype gardenhose adapter that was built directly upon RestTemplate (streaming on a background thread) but Spring Social Twitter has an issue on its 1.1 roadmap that is relevant:https://jira.springsource.org/browse/SOCIALTW-2',3,'Luke Taylor','Issues'),('Spring_XD','XD-2310','Parsing issues with kafka-bus.xml','Using Kafka as a transport option yields:[2014-11-04 12:18:30.528] boot - 24061 ERROR [main] --- SpringApplication: Application startup failedorg.springframework.beans.factory.parsing.BeanDefinitionParsingException: Configuration problem: Failed to import bean definitions from URL location [classpath*:/META-INF/spring-xd/transports/kafka-bus.xml]Offending resource: class path resource [META-INF/spring-xd/bus/message-bus.xml]; nested exception is org.springframework.beans.factory.xml.XmlBeanDefinitionStoreException: Line 9 in XML document from URL [jar:file:/Users/mbogoevici/.gradle/caches/modules-2/files-2.1/org.springframework.xd/spring-xd-dirt/1.1.0.BUILD-SNAPSHOT/cf6a9a013dbde49d2925e2b5177d01a028379758/spring-xd-dirt-1.1.0.BUILD-SNAPSHOT.jar!/META-INF/spring-xd/transports/kafka-bus.xml] is invalid; nested exception is org.xml.sax.SAXParseException; lineNumber: 9; columnNumber: 26; Open quot