2)at org.springframework.integration.channel.AbstractSubscribableChannel.doSend(AbstractSubscribableChannel.java:77)... 24 more10:47:14928 ERROR task-scheduler-4 handler.LoggingHandler:140 - org.springframework.integration.MessageDeliveryException: Dispatcher has no subscribers for channel \'SimpleModule [name=time type=source group=stream1 index=0].output\'.at org.springframework.integration.channel.AbstractSubscribableChannel.doSend(AbstractSubscribableChannel.java:81)at org.springframework.integration.channel.AbstractMessageChannel.send(AbstractMessageChannel.java:178)at org.springframework.integration.channel.AbstractMessageChannel.send(AbstractMessageChannel.java:149)at org.springframework.integration.core.MessagingTemplate.doSend(MessagingTemplate.java:304)at org.springframework.integration.core.MessagingTemplate.send(MessagingTemplate.java:165)at org.springframework.integration.endpoint.SourcePollingChannelAdapter.handleMessage(SourcePollingChannelAdapter.java:97)at org.springframework.integration.endpoint.AbstractPollingEndpoint.doPoll(AbstractPollingEndpoint.java:199)at org.springframework.integration.endpoint.AbstractPollingEndpoint.access$000(AbstractPollingEndpoint.java:51)at org.springframework.integration.endpoint.AbstractPollingEndpoint$1.call(AbstractPollingEndpoint.java:143)at org.springframework.integration.endpoint.AbstractPollingEndpoint$1.call(AbstractPollingEndpoint.java:141)at org.springframework.integration.endpoint.AbstractPollingEndpoint$Poller$1.run(AbstractPollingEndpoint.java:273)at org.springframework.integration.util.ErrorHandlingTaskExecutor$1.run(ErrorHandlingTaskExecutor.java:52)at org.springframework.core.task.SyncTaskExecutor.execute(SyncTaskExecutor.java:49)at org.springframework.integration.util.ErrorHandlingTaskExecutor.execute(ErrorHandlingTaskExecutor.java:49)at org.springframework.integration.endpoint.AbstractPollingEndpoint$Poller.run(AbstractPollingEndpoint.java:268)at org.springframework.scheduling.support.DelegatingErrorHandlingRunnable.run(DelegatingErrorHandlingRunnable.java:53)at org.springframework.scheduling.concurrent.ReschedulingRunnable.run(ReschedulingRunnable.java:81)at java.util.concurrent.Executors$RunnableAdapter.call(Executors.java:439)at java.util.concurrent.FutureTask$Sync.innerRun(FutureTask.java:303)at java.util.concurrent.FutureTask.run(FutureTask.java:138)at java.util.concurrent.ScheduledThreadPoolExecutor$ScheduledFutureTask.access$301(ScheduledThreadPoolExecutor.java:98)at java.util.concurrent.ScheduledThreadPoolExecutor$ScheduledFutureTask.run(ScheduledThreadPoolExecutor.java:206)at java.util.concurrent.ThreadPoolExecutor$Worker.runTask(ThreadPoolExecutor.java:895)at java.util.concurrent.ThreadPoolExecutor$Worker.run(ThreadPoolExecutor.java:918)at java.lang.Thread.run(Thread.java:680)Caused by: org.springframework.integration.MessageDispatchingException: Dispatcher has no subscribersat org.springframework.integration.dispatcher.UnicastingDispatcher.doDispatch(UnicastingDispatcher.java:109)at org.springframework.integration.dispatcher.UnicastingDispatcher.dispatch(UnicastingDispatcher.java:102)at org.springframework.integration.channel.AbstractSubscribableChannel.doSend(AbstractSubscribableChannel.java:77)... 24 more10:47:15930 ERROR task-scheduler-1 handler.LoggingHandler:140 - org.springframework.integration.MessageDeliveryException: Dispatcher has no subscribers for channel \'SimpleModule [name=time type=source group=stream1 index=0].output\'.at org.springframework.integration.channel.AbstractSubscribableChannel.doSend(AbstractSubscribableChannel.java:81)at org.springframework.integration.channel.AbstractMessageChannel.send(AbstractMessageChannel.java:178)at org.springframework.integration.channel.AbstractMessageChannel.send(AbstractMessageChannel.java:149)at org.springframework.integration.core.MessagingTemplate.doSend(MessagingTemplate.java:304)at org.springframework.integration.core.MessagingTemplate.send(MessagingTemplate.java:165)at org.springframework.integration.endpoint.SourcePollingChannelAdapter.handleMessage(SourcePollingChannelAdapter.java:97)at org.springframework.integration.endpoint.AbstractPollingEndpoint.doPoll(AbstractPollingEndpoint.java:199)at org.springframework.integration.endpoint.AbstractPollingEndpoint.access$000(AbstractPollingEndpoint.java:51)at org.springframework.integration.endpoint.AbstractPollingEndpoint$1.call(AbstractPollingEndpoint.java:143)at org.springframework.integration.endpoint.AbstractPollingEndpoint$1.call(AbstractPollingEndpoint.java:141)at org.springframework.integration.endpoint.AbstractPollingEndpoint$Poller$1.run(AbstractPollingEndpoint.java:273)at org.springframework.integration.util.ErrorHandlingTaskExecutor$1.run(ErrorHandlingTaskExecutor.java:52)at org.springframework.core.task.SyncTaskExecutor.execute(SyncTaskExecutor.java:49)at org.springframework.integration.util.ErrorHandlingTaskExecutor.execute(ErrorHandlingTaskExecutor.java:49)at org.springframework.integration.endpoint.AbstractPollingEndpoint$Poller.run(AbstractPollingEndpoint.java:268)at org.springframework.scheduling.support.DelegatingErrorHandlingRunnable.run(DelegatingErrorHandlingRunnable.java:53)',3,'Jennifer Hickey','Issues'),('Spring_XD','XD-811','Add REST endpoint for launching Job','We need a REST endpoint to launch a job.Given the constraint on JobRegistry being not persistent and not available outside the container JVM we can not use the batch job admin controller/service to launch the job.One possible way is to use the trigger source to launch the job at XD.',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-812',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-813','Destroying XD job should remove job\'s entries at batch job repositories/batch job locator','When an XD job is destroyed/deleted the batch jobRepository entries for the job (associated JobInstances JobExecutions etc.) and the BatchJobLocator entries.',4,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-816','Support for composed streams','Some recent changes caused this to be turned off. Basically the change was to police whether a stream is well formed at create time rather than deploy time.  By deferring that check we can create composed streams that are not deployable by themselves but that are when used as building blocks in proper streams.',2,'Andy Clement','Issues'),('Spring_XD','XD-82','Documentation for \"tail | file\" processing','Put on the guide as a section in an \'input-stream\' wiki page.',3,NULL,'Issues'),('Spring_XD','XD-820','Jobs and taps should not require a leading : since they have name spaces.',NULL,3,'Glenn Renfro','Issues'),('Spring_XD','XD-822','TupleBuilder.fromString() should not overwrite original id and timestamp fields','When converting a JSON string to a tuple the JSON may contain id. This method should handle this. Same with timestamp',2,'Luke Taylor','Issues'),('Spring_XD','XD-823','add discardDeletes property to twitterstream source','If true(default): filter for delete messages in the twitter stream and route to a discard channel. This creates a twitter stream including only new tweets and no references to deleted ones.',1,'David Turanski','Issues'),('Spring_XD','XD-824','Rename ChannelRegistry','My current thinking is...   ChannelRegistry -> MessageBus   RabbitChannelRegistry -> RabbitMessageBus   ...Then method names change like so:   createInbound -> registerConsumer   createOutbound -> registerProducer',3,'Mark Fisher','Issues'),('Spring_XD','XD-827','provide a property on twittersearch to enable the object-to-json transformer','Twitter search source should produce JSON or Pojo. The Pojo requires a custom wrapper class that is JSON friendly (e.g. zero arg constructor). The twittersearch module should have a parameter --json true/false (default true) to control the output type.',2,'David Turanski','Issues'),('Spring_XD','XD-828','rename Bridge to Binding and add direction','org.springframework.integration.x.bus.Bridge should now be called Bindingwe can also move the INBOUND/OUTBOUND direction (or possibly the CONSUMER/PRODUCER role) into this class; that should simplify its usage in conditional code within the MessageBus code and also reduce the use of \"in\" and \"out\" as Strings in that same code',2,'Mark Fisher','Issues'),('Spring_XD','XD-83',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-831','Update docs to cover Module config and lib directory structure',NULL,2,'Eric Bottard','Issues'),('Spring_XD','XD-832','Update docs for new Tap syntax','Now that taps are just channels we need to update the docs.The preceding colon is no longer needed (and will be removed altogether) so all examples should be like this:{code}tap:foo > bar{code}',2,'Jennifer Hickey','Issues'),('Spring_XD','XD-838','Refactor out Trigger docs from the Batch Job chapter',NULL,2,NULL,'Issues'),('Spring_XD','XD-84','Documentation for \"http | gemfire\" processing','Put on the guide as a section in an \'input-stream\' wiki page.',3,'David Turanski','Issues'),('Spring_XD','XD-847','Revise the available hadoopDistro options','We should adjust our --hadoopDistro options to the ones supported in the new spring-data-hadoop 1.0.1.RELEASE - hadoop12 (default) cdh4 hdp13 phd1 hadoop20This includes updating the wiki pages',5,'Thomas Risberg','Issues'),('Spring_XD','XD-85','Documentation for \"gemfirecq | file\" processing','Put on the guide as a section in an \'input-stream\' wiki page.',3,'David Turanski','Issues'),('Spring_XD','XD-854','Update doc about modules and spring','The doc at http://docs.spring.io/spring-xd/docs/1.0.0.M3/reference/html/#_modules_and_spring refers to an old version of the counter sink when it was still hardwired to use redis.The text next to it that explains placeholders is out of date (with respect to the redis placeholders)',2,'Jennifer Hickey','Issues'),('Spring_XD','XD-857','Refactor FileModuleRegistry as \"ResourceModuleRegistry\"','Apart from sanity checks there is not much that ties FileModuleRegistry to actual java.io.Files. Using the Resource abstraction would work just the same and would allow loading modules from the classpath in constrained environments or other file systems/locations. (HDFS /HTTP)',5,'Eric Bottard','Issues'),('Spring_XD','XD-858','Upgrade to Spring Data Redis 1.1.0.RELEASE',NULL,1,'Jennifer Hickey','Issues'),('Spring_XD','XD-859','Support for listing of modules in the REST API','From the CLI one should be able to get a listing of modules and be able to specifically ask for jobs sources sinks and processors.  A brief description of them would also be nice - this might come from adding some metadata into the definition.Finer grained description/implementation suggestion TBD',8,'Glenn Renfro','Issues'),('Spring_XD','XD-86','Documentation for \"twittersearch | file\" processing','Put on the guide as a section in an \'input-stream\' wiki page.',3,'Thomas Risberg','Issues'),('Spring_XD','XD-861',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-862','First class JSON Path support','Similar to xpath with XML there are now some initial support in SI that enable the use of filter/routers based on JSON Path expressions.  That support needs to be reviewed and then brought up to the level of exposure in Spring XD so that router/filter modules could use JSON Path.  json-path-filter/router are components that need to be created perhaps others.This story needs to be broken down further.',10,'Mark Fisher','Issues'),('Spring_XD','XD-863','Serialization of Spring Batch Context Objects','Needs some investigation on how the update information from Spring Batch listeners can be sent as a message across modules in a single node configuration as well as across JVMs in a distributed node configuration.',4,'Gunnar Hillert','Issues'),('Spring_XD','XD-864','Move BatchJobExecutionsByJobName to BatchJobsController from BatchJobExecutionsController','We need to move the BatchJobExecutionsByJobName method to BatchJobsController as that seems appropriate',1,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-866','Remove remaining Thread.sleeps from the job tests','Get rid of all the thread.sleeps and code that supported them.',1,'Glenn Renfro','Issues'),('Spring_XD','XD-868','Create microbenchmark performance test of reactor syslog adapter vs standard syslog adapter','We need to verify that we are seeing improved throughput when using the reactor based syslog adapter.  A suggestion on a basic stream to perform a microbenchmark this would be using in-memory counters singlenode with the stream definition \"syslog | counter\".Based on the results of this microbenchmark other stories may need to be created.',4,'Jon Brisbin','Issues'),('Spring_XD','XD-87','Documentation that introduces taps','Put on the guide as a section in an \'input-stream\' wiki page.',3,'Luke Taylor','Issues'),('Spring_XD','XD-870','Support for listing of modules in the Shell','Commands that pair up with the functionality described in XD-859module list  (would list all modules in a table format)module list --type=source  (would list only source modules)and so on.',4,'Glenn Renfro','Issues'),('Spring_XD','XD-871','No errors in Shell when creating stream with HTTP Source + already used port','2 issues exist:1) Current this does not create an error in the shell{code}stream create --name s1 --definition \"http | log\"stream create --name s2 --definition \"http | log\"{code}On the server-side I see:{code}Caused by: java.net.BindException: Address already in useat sun.nio.ch.Net.bind0(Native Method)at sun.nio.ch.Net.bind(Net.java:344)at sun.nio.ch.Net.bind(Net.java:336)at sun.nio.ch.ServerSocketChannelImpl.bind(ServerSocketChannelImpl.java:199)at sun.nio.ch.ServerSocketAdaptor.bind(ServerSocketAdaptor.java:74)at org.jboss.netty.channel.socket.nio.NioServerBoss$RegisterTask.run(NioServerBoss.java:193)at org.jboss.netty.channel.socket.nio.AbstractNioSelector.processTaskQueue(AbstractNioSelector.java:366)at org.jboss.netty.channel.socket.nio.AbstractNioSelector.run(AbstractNioSelector.java:290)at org.jboss.netty.channel.socket.nio.NioServerBoss.run(NioServerBoss.java:42)... 3 more{code}2)The Stream should not be saved to the StreamDefinitionRepo in case of an error.',4,'David Turanski','Issues'),('Spring_XD','XD-874','For file based item reader jobs step/job completion message should have name of file sent on named channel','It looks like we don\'t handle deletion of source files currently. We should provide some support for that - Maybe there is a way to into Spring Integration\'s PseudoTransactionManager support:http://docs.spring.io/spring-integration/api/org/springframework/integration/transaction/PseudoTransactionManager.htmlThe *File Source* should possibly also support File archival functionality (But that might also be a dedicated processor?). Not sure where we want to set the semantic boundaries for the File Source.',8,'Luke Taylor','Issues'),('Spring_XD','XD-875','Handle AdminServer shutdown cleanly','The admin Server\'s tomcat is not shutdown properly. There is an existing method shutdownCleanly() on AdminServer but the spring-xd-shell tests hang when we use this method to shutdown the admin server.',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-877','Taps do not work when JMX is enabled','When JMX is enabled the Module\'s output channel processed by StreamPlugin is a Proxy. Thus it fails the \"instanceof\" test used to apply the WireTap to the output channel.',3,'Jennifer Hickey','Issues'),('Spring_XD','XD-879','Cleanup hsqldb data directory used by tests after each test completion','Currently the \"data\" directory created by the HSQLDB process during the tests run is not cleaned up and may cause issues. We should delete the \"data\" directory after each test completion.',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-88','Documentation for counter taps','Put on the guide as a section in an \'input-stream\' wiki page.',3,'David Turanski','Issues'),('Spring_XD','XD-880','Update Java Version to 7',NULL,1,'Gary Russell','Issues'),('Spring_XD','XD-885','Add Batch Job Listeners Automatically','Add Batch Job Listeners Automatically* Each major listener category should send notifications to own channel (StepExecution Chunk Item etc.)* Add attribute to disallow automatic adding of listeners',8,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-886','Fix package tangle between org.springframework.xd.dirt.plugins.job and org.springframework.xd.dirt.job',NULL,1,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-887','Package modules with their support jars','Currently a lot of jars that are on the classpath of xd-dirt are there to support modules.We should move those to the lib/ construct of a module and remove them from the CP of dirt.But this should not be done by simple \"mv\" as we\'d lose version tracking and dependency management offered by gradle.Pending a \"dependency-aware\" ModuleRegistry we should be able to alter the build.gradle file so that it- knows about individual modules (maybe handles them as project)- copies its libs into the appropriate directory- does not copy dependencies that are already legitimate dependencies of xd-dirt (this can be achieved by runtime introspection of the dependeny tree of both projects)',6,'Eric Bottard','Issues'),('Spring_XD','XD-889','Change default admin port from 8080','This conflicts with and \'out of the box\' hadoop installation that uses 8080 as the \'map reduce shuffle port\'.8088 sound ok?',1,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-89','Documentation for gauge taps','Put on the guide as a section in an \'input-stream\' wiki page.',3,'Luke Taylor','Issues'),('Spring_XD','XD-890','Run JavaScript tests (Jasmine) as part of the build process','We probably need to look into some options to run our JavaScript tests (Jasmine) as part of the build process - some possibilities:* Jasmine Gradle Plugin https://github.com/dzhaughnroth/jasmine-gradle-plugin* Saga - http://timurstrekalov.github.io/saga/Looks like Maven has slightly better support: http://searls.github.io/jasmine-maven-plugin/index.htmlSee also: XD-865',8,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-891','Provide a way to access currently deployed modules','For testing it would be useful to access the deployed Module instances to connect sources and or sinks to a module\'s input and output channels etc. This could be a simple as exposing the deployedModuleMap on ModuleDeployer or possibly something more elaborate if this level of granularity is generally useful for runtime administration.',3,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-896','Add --inputType and --outputType module parameters','The ability to configure message conversion via parameters. Consider programatic configuration of data type channels. Values can be media type e.g. application/json or a java class name.',8,'David Turanski','Issues'),('Spring_XD','XD-897',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-898',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-899','xd-container should start even if xd-admin is not running','currently xd-container will not start due to a DB connection failure if the xd-admin is not already runningIn fact if someone is not using Batch jobs at all with XD they should not even need a DB connection for either xd-admin or xd-container to runso... consider using LazyConnectionDataSourceProxy so a connection failure would only occur when the DataSource is actually invoked to retrieve a connection',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-9','Basic implementation of a reactor based tcp server',NULL,13,'Gary Russell','Issues'),('Spring_XD','XD-90','Documentation for rich gauge taps','Put on the guide as a section in an \'input-stream\' wiki page.',3,'David Turanski','Issues'),('Spring_XD','XD-900','Move SpEL PropertyAccessors to Module Parent Context','When INT-3133 is resolved SpEL {{PropertyAccessor}} s are inherited from parent contexts.Instead of adding the {{JsonPropertyAccessor}} to each module\'s context add it to the parent instead.',1,'Gary Russell','Issues'),('Spring_XD','XD-901','Wrong Jetty Util on classpath for WebHdfs','We currently include jetty-util-6.1.26.jar but we need to add correct jar for different distributions - PHD uses jetty-util-7.6.10.v20130312.jarNeed to check hadoop-hdfs dependencies for the distros and add jetty-util-* to the jar copy for each distro',3,'Thomas Risberg','Issues'),('Spring_XD','XD-905','Container start/stop publish events are not getting processed','It looks like Container\'s ContainerStartedEvent and ContainerStoppedEvent are published from ContainerLauncher\'s context whereas the ContainerEventListeners are running in XDContainer\'s context. This makes the container start/stop events not getting processed.',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-906','Add aggregate counter monthly resolution query support',NULL,5,'Luke Taylor','Issues'),('Spring_XD','XD-907','Add aggregate counter year resolution query support',NULL,3,'Luke Taylor','Issues'),('Spring_XD','XD-908','Add aggregate counter query by number of points','It should be possible to supply a start or end date (or none for the present) plus a \"count\" value for the number of points required (i.e. after or prior to the given time).',3,'Luke Taylor','Issues'),('Spring_XD','XD-91','Documentation for field value taps','Put on the guide as a section in an \'input-stream\' wiki page.',3,'David Turanski','Issues'),('Spring_XD','XD-910','Add a Processor for Restful webservices','Offers the functionality to make http request to a web service. i.e. outbound http gateway.Example implementations:stream create --name foo --definition \"trigger |rest --reply-timeout=1 --url=http://earthquake.usgs.gov/earthquakes/feed/geojson/all/day|log\"stream create --name foos --definition \"trigger --payload=lat=34.0567006&lon=-84.34368810000001&site=all&smap=1&searchresult=Roswell%2C%20GA%2030076%2C%20USA#.UktzaWSG1Dd | rest --url=http://forecast.weather.gov/MapClick.php? |log\"',1,'Glenn Renfro','Issues'),('Spring_XD','XD-914','Add documentation for #jsonPath functionality with SpEL based processors','See issue https://jira.springsource.org/browse/XD-862The docs should be updated to include examples that show how to use the standard \'SpEL\' based splitter transformer filters with #jsonPath expressions.',2,NULL,'Issues'),('Spring_XD','XD-915','Convert modules to be CP-aware','Once XD-887 is merged gradually convert more modules.Recipe:1) Move the <module>.xml file to <module>/config/<module>.xml2) Declare a :module.<type>.<module> gradle project3) Move dependencies from dirt project to newly created module project4) gradle build picks it up.gradle clean build + manual testAlso have a look at gradle cleanEclipse eclipse',8,'Eric Bottard','Issues'),('Spring_XD','XD-916','File source should be able to produce file contents or file reference','File source should output either the File itself (serialized File object) or the contents as a byte[]. This option is configured by a parameter --contents=true.  The byte[] may be converted to a String using XD Message Conversion e.g. --output = text/plain;charset=UTF-8',4,'David Turanski','Issues'),('Spring_XD','XD-919','Remove json parameter from twittersearch source','json parameter is no longer required. Use --outputType=application/json instead',2,'David Turanski','Issues'),('Spring_XD','XD-920','MQTT source module does not cleanly undeploy','Was attempting to test mqtt turns out I don\'t have the proper rabbitmq thing installed. So far so good I get these kinds of exceptions:{noformat}Unable to connect to server (32103) - java.net.ConnectException: Connection refusedat org.eclipse.paho.client.mqttv3.internal.TCPNetworkModule.start(TCPNetworkModule.java:75)at org.eclipse.paho.client.mqttv3.internal.ClientComms$ConnectBG.run(ClientComms.java:521)at java.lang.Thread.run(Thread.java:724)Caused by: java.net.ConnectException: Connection refusedat java.net.PlainSocketImpl.socketConnect(Native Method)at java.net.AbstractPlainSocketImpl.doConnect(AbstractPlainSocketImpl.java:339)at java.net.AbstractPlainSocketImpl.connectToAddress(AbstractPlainSocketImpl.java:200)at java.net.AbstractPlainSocketImpl.connect(AbstractPlainSocketImpl.java:182)at java.net.SocksSocketImpl.connect(SocksSocketImpl.java:392)at java.net.Socket.connect(Socket.java:579)at org.eclipse.paho.client.mqttv3.internal.TCPNetworkModule.start(TCPNetworkModule.java:66)... 2 more{noformat}Problem is I still get them after undeploying my \"mqtt | log\" stream',2,'Gary Russell','Issues'),('Spring_XD','XD-921','Add more \"hands on\" example to MQTT doco','Not everyone may be familiar with MQTT or esp. with MQTT inside Rabbit',3,'Glenn Renfro','Issues'),('Spring_XD','XD-922','Handle SingleNodeServer\'s stop()  method cleanly','SingleNode server needs to stop cleanly with stopping both the admin server & container server. Also all the tests that require SingleNode main server needs to handle the server shutdown appropriately.',2,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-923','Error Channel for streams modules that fail to process a message','As a user I\'d like to be notified when a exception is thrown in a module so that I can tap into an error channel to receive the failures for each stream/module.',8,'Gary Russell','Issues'),('Spring_XD','XD-924','Split integration.x in dedicated XD projects where appropriate','Similar to what is done for e.g. hadoop reactor and http some of the classes in the .x package (namely gemfire splunk twitter) should go in dedicated (albeit small) projects. This would enable further modularization (see XD-915)',3,'Eric Bottard','Issues'),('Spring_XD','XD-925','Investigate Swagger to generate REST API Documents',NULL,3,'Eric Bottard','Issues'),('Spring_XD','XD-926','Update Core Spring Dependency to 4.0.0.M3',NULL,8,'Gary Russell','Issues'),('Spring_XD','XD-927','ModuleType  Refactor','Remove ModuleType.getModuleTypeByTypeName.  All code should use the enum.',3,'Eric Bottard','Issues'),('Spring_XD','XD-928','Refactor src/test/resources in Dirt','* In the testmodules.source** Rename source-config to packaged-source** Rename source-config to packaged-source-no-lib* All xml files should be prefixed with test.  i.e. testsource testsink* Make sure all tests pass with new configuration',1,'Eric Bottard','Issues'),('Spring_XD','XD-931',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-933','Remove work around Spring HATEOAS#89','See https://github.com/spring-projects/spring-hateoas/issues/89Updating HATEOAS version and removing in a lot of controllers should be possible now. See eg https://github.com/spring-projects/spring-xd/blob/4919ea2498a13ef47aaa9437937308fb26a7a24f/spring-xd-dirt/src/main/java/org/springframework/xd/dirt/rest/XDController.java#L219',2,'Eric Bottard','Issues'),('Spring_XD','XD-935','Implement Kryo serialization for Tuple','Currently TupleCodec uses JSON for serialization/deserialization. It should use Kryo. This will require some customization and potentially changes to Tuple to address the Tuple\'s conversionService field.',3,'David Turanski','Issues'),('Spring_XD','XD-937','Inject ModuleDefinitionRepository into ModulesController','Currently ModulesController creates the ModuleDefinitionRepository instance with ModuleRegistry. Instead we should inject the moduleDefinitionRepository into ModulesController directly.',1,'Mark Fisher','Issues'),('Spring_XD','XD-940','Splunk Pulls in an Old SI Jar into STS',NULL,1,'Gary Russell','Issues'),('Spring_XD','XD-941','Convert remaining modules to be CP-aware','Now that XD-924 is merged we can convert splunk twitter and gemfire modules to rely on the newly created projects.The hadoop module will get its own story as classpath handling is a bit more tricky for that one.From there on no new dependency should be added to DIRT for the sole purpose of a module. Rather it should directly be created as a CP-aware module and project.',3,'Eric Bottard','Issues'),('Spring_XD','XD-942','Change repo links in build.gradle repo.spring.io',NULL,1,'David Turanski','Issues'),('Spring_XD','XD-944','Clean up unused JSON mapping classes','There are a few obsolete classes lurking around TypedJsonMapper comes to mind but there are likely some others',1,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-945','Spike for writing to HDFS','See Epic https://jira.springsource.org/browse/XD-234',10,'Thomas Risberg','Issues'),('Spring_XD','XD-946','Spike for EC2 deployments',NULL,20,'Glenn Renfro','Issues'),('Spring_XD','XD-947','Spike for Deployment SPI','SPI for deployment on to YARN + Local \'dirt\' cluster.',20,'Mark Pollack','Issues'),('Spring_XD','XD-948','Spike for job that imports data from CSV file to HDFS','TBD',10,'Luke Taylor','Issues'),('Spring_XD','XD-949','Spike for job that exports HDFS CSV data to JDBC',NULL,10,NULL,'Issues'),('Spring_XD','XD-950','Spike for advanced Job Orchestration features',NULL,20,'Ilayaperumal Gopinathan','Issues'),('Spring_XD','XD-953','Richer module options metadata','Module options are currently implemented using PropertySourcesPlaceholderConfigurer doing simple \"text\" replacements.This story proposes to introduce a richer model for module options which could take the following xml representation (keeping in mind that there would be an underlying set of classes that could also apply to e.g. @Configuration approach):{code:xml}<xd:params>  <xd:param name=\"port\" help=\"the http port to listen on\" /></xd:params>{code}So the very first obvious benefit is providing help metadata.The second one is an easy way to list available option names without resorting to brittle PropertySourcesPlaceholderConfigurer hacks (we wouldn\'t for example detect xd.stream.name or XD_TRANSPORT as a valid option)One could also specify defaults/computations this time benefiting from SpEL everywhere:{code:xml}<xd:params>  <xd:param name=\"directory\" default=\"headers.directory\" /></xd:params>{code}Lastly this opens the door to better type checking / combinations / optionality support:{code:xml}<xd:params valid=\"fixedDelay || cron\">  <xd:param name=\"fixedDelay\" type=\"int\" />  <xd:param name=\"cron\" type=\"string\" /></xd:params>{code}The \'valid\' attribute can e.g. be evaluated by SpEL.Some final remarks:- That construct can be compatible with our current approach by behaving as a PropertySource itself (instead of creating a PropertySource the StreamPlugin would give this new bean the java.util.Properties)- Plugins could benefit from a hook in that construct and advertise the fact that they expect/provide new options (e.g. --inputType)There is a slight problem though which is that if this construct lives in the same AppContext as the module definition itself then the AppContext needs to be refreshed for the logic to kick in. One could circumvent that using profiles or we could rely on a different filename convention (e.g. <module>-params.xml)',10,'Eric Bottard','Issues'),('Spring_XD','XD-954',NULL,NULL,NULL,NULL,'Issues Summary'),('Spring_XD','XD-955','Update Jobs documentation to include \"job launch\" command','This is currently missing and probably supersedes some of the stuff that\'s in there now.',1,'Glenn Renfro','Issues'),('Spring_XD','XD-956','Refactor DSL parser according to latest syntax proposals','We have recently revised the syntax for stream definitions this issue covers that refactoring.',12,'Andy Clement','Issues'),('Spring_XD','XD-957','Update SI Dependency to 4.0.0.BUILD-SNAPSHOT',NULL,3,'Gary Russell','Issues'),('Spring_XD','XD-961','Accessing xd-admin URLs in the browser return XML and not JSON','Here is an example:the following request for streams:http://ec2-23-20-25-30.compute-1.amazonaws.com:9393/streamsReturns:This XML file does not appear to have any style information associated with it. The document tree is shown below.<errors xmlns:atom=\"http://www.w3.org/2005/Atom\"><error logref=\"HttpMessageNotWritableException\"><message>Could not marshal [PagedResource { content: [links: [<http://ec2-23-20-25-30.compute-1.amazonaws.com:9393/streams/ticktock>;rel=\"self\"]] metadata: Metadata { number: 0 total pages: 1 total elements: 1 size: 20 } links: [] }]: null; nested exception is javax.xml.bind.MarshalException - with linked exception: [com.sun.istack.SAXException2: unable to marshal type \"org.springframework.xd.rest.client.domain.StreamDefinitionResource\" as an element because it is not known to this context.]</message></error></errors>',1,'Eric Bottard','Issues'),('Spring_XD','XD-962','fix gradle clean test','Currently ./gradlew clean test fails since the module dependencies are not packaged before the test task.',1,'David Turanski','Issues'),('Spring_XD','XD-966','User requests that XD team members are issued EC2 accounts','* Setup groups for xd user* Setup privileges so users can only see their instances* Setup user accounts** Send created access key to users** Send username and passwords to user',5,'Glenn Renfro','Issues'),('Spring_XD','XD-969','Add functionality to provision EC2 instance and mount EBS','* The Application should **  Create a Spring Application Context.**  Should take a command line parameter --config that will point to a property file with key/value pairs specified below.  By default the file xd-ec2.properties will be looked for on the classpath** Associate EBS shared volume for each machine instance* Packaging ** Use gradle application plugin to generate a ΓÇÿbinΓÇÖ directory with a script to start the application.  Seehttp://www.gradle.org/docs/current/userguide/application_plugin.html** The config file xd-ec2.properties should be in a directory (ideally a \'config\' directory parallel to \'bin\' and will be loaded by the application by default - loading via the CP is probably the easiest way.** Create a POJO to easily reference these properties vs. using a raw java Properties object.How to verify it works* Integration testing** Create JUnit based tests.  JClouds itself has extensive testing can look at those for structure.** Verify what you created has been installed.** Verify ports are openInstance Information** EBS of 50GB Base for each instance.* Report successful and failed Instances.Key-Value pairs in configuration fileproperties may include: * cluster-name= a name describing the cluster you are creating* aws-access-keys= the access key assigned to you by admin* aws-secret-key= the secret key assigned to you by admin* private-key-file= the private key file assigned to you by admin.  Used for ssh-ing into * multi-node=true/false if true then installer will run the number of nodes as enumerated in the number-nodes property value.  if false the installer will start a single node server* number-nodes=The number of nodes(containers) to deploy for this cluster.  Value is an integer > 0* machine-size=The size of machines to be assigned for admin and nodes.  small medium large* redis-port=6379* rabbit-port=5279* xd-dist-url=The url to download the XD to install.  for example: http://blahblahblah.zip* ami = The ami image to use for your cluster. for example: ami-dfadsfdadf',10,'Glenn Renfro','Issues'),('Spring_XD','XD-972','Create CI for XD-EC2 project','Automated test will use directly use the Deployer class* asserts on basic info of RunningInstance** check that EBS was mounted** that application was unzipped** redis and rabbit are running via port checks* http requests on admin port for ** root path** list of modules* @AfterClass that will look for the cluster name and terminate all instancesLook at ΓÇÿliveΓÇÖ tag in JClouds tests for some additional tactics',5,'Glenn Renfro','Issues'),('Spring_XD','XD-976','Bootstrap Project for XD AWS Installer','* Create a Spring application context.  (XML or Java dealers choiceΓÇª)* Use XD eclipse code format policy* Create Source Package structure* Create Test Package Structure* Gradle build* JClouds and Spring deps',5,'Glenn Renfro','Issues'),('Spring_XD','XD-977','Add functionality to download XD distribution zip to each EC2 instance as specified by user','* User specifies download distribution zip file from properties file.  See XD-969 for key-value pairs* Copy the distribution from the shared EBS/S3  the ebs volume assigned to the each node/admin instance  .  ** If not on shared ebs/s3 pull from http site specified by user and put on the shared EBS volume. ** Unzip the distribution from on the ebs volume for the instance to the /home/ubuntu directory** make sure privileges are set to ubuntu not root.How to verify it works* Create a JUNit style integration test that** Deletes a known .zip distribution from EBS/S3.** Invoke the application functionality (should be a 1 liner) that will start up the instance and download the .zip distribution from the URI provided in xd-ec2.properties.  Verify the file is now in EBS/S3 and also on the instance** Tear down created instance** Create new instance passing in the same URI of the .zip distribution.  Verify as before',5,'Glenn Renfro','Issues'),('Spring_XD','XD-978','Installer needs to launch a single node XD instance','* Create a Deployer class has methods** RunningInstance  deploySingleNode*** takes into account machine size as specified in properties file** void  destroyAllInstances()  *** or whatever JClouds returns from the destroy call** ctor gets passed in the root boostrapping credentials.* Install Script Steps** Setup XD_HOME variable** Make sure privileges are set to ubuntu not root.** start up redis and rabbit using ports as specified in xd-ec2.properties** Use port watch to make sure they started** Start singlenode after configuration.** Display hostname of singlenode server** Report successful and failed startup** Hit root of xd-admin to see if there is a response on 9393* Integration Testing** Verify that config files have been setup** Verify XD has been started** Verify XD can process a basic http post',10,'Glenn Renfro','Issues'),('Spring_XD','XD-98','Documentation on the module system and how to contribute new modules','For people who are familiar with Spring/Spring Integration provide documents that show how to add additional input sources/sinks.',3,'David Turanski','Issues'),('Spring_XD','XD-981','Missing guava-11.0.2.jar dependency for hadoop distros','We used to have a shared guava-11.0.2.jar dependency in the lib dir. That\'s no longer there so hadoop distros that require this now fail (at least any hadoop 2.0.x based ones)We should also upgrade to current Hadoop versions (Hadoop 2.2 stable)',3,'Thomas Risberg','Issues'),('Spring_XD','XD-984','Create OOTB batch job for import and processing multiple files to JDBC','Create a sample batch job for inclusion in the distribution that will perform the following tasks.ItemReader* Read a from a directory with multiple files (configurable)* Support for CSV (assume first line has header values)* Convert to tuple data structureItemProcessor* Provide groovy based no-op ItemProcessor.  (configurable)ItemWriter* Write to JDBC.** Provide ** Assume there is an DB instance running somewhere specify connection info (configurable)**The sample job should be documented**',10,'Luke Taylor','Issues'),('Spring_XD','XD-985','Create OOTB \'file to HDFS\' batch import job that is launched by a stream.','Same processing as XD-984 but the job instacne is launched via an event from the input file source.  Supporting a single file per job launch is OK.> job create blah --definition \"filehdfs\"> stream create csvStream --definition \"file --ref=true --dir=/Users/luke --pattern=*.csv > job:blah\"*the job should be documented*',5,'Luke Taylor','Issues'),('Spring_XD','XD-987','Create OOTB batch job for export and processing multiple files from HDFS to MongoDB','The ItemReader will read multiple files from HDFS and the data will be converted to a tuple data structureThe ItemProcessor will be a no-op groovy script.The ItemWriter will write the data to a MongoDB collection** A TupleToDBObject converter will need to be developed.*the sample job should be documented*',8,'Luke Taylor','Issues'),('Spring_XD','XD-988','Create OOTB batch job for export and processing multiple files from HDFS to JDBC','Same setup as XD-987 for ItemReader and ItemProcessor but should write to HDFS.  One can assume that the table structure has been created already external to the batch job execution.',5,'Luke Taylor','Issues'),('Spring_XD','XD-99','Sonar build is failing','https://build.springsource.org/browse/XD-SONAR-34Caused by: java.lang.ClassNotFoundException: org.sonar.api.Plugin        at org.codehaus.plexus.classworlds.strategy.SelfFirstStrategy.loadClass(SelfFirstStrategy.java:50)        at org.codehaus.plexus.classworlds.realm.ClassRealm.loadClass(ClassRealm.java:244)        at org.codehaus.plexus.classworlds.realm.ClassRealm.loadClass(ClassRealm.java:230)        ... 94 more',1,'Gunnar Hillert','Issues'),('Spring_XD','XD-990','The HDFS Store Library should support writing text with delimiter','Support writing lines of text separated by a delimiterSupport writing a CSV (comma-separated variables) TSV (tab-separated variables)No compression',8,'Janne Valkealahti','Issues'),('Spring_XD','XD-991','The HDFS Store Library should support compression when writing text','Need to support writing text in compressed formatshould initially support: - bzip2 - LZO',8,'Janne Valkealahti','Issues'),('Spring_XD','XD-995','Refactor tests with FileSink|FileSource to use eventually() matcher','Some tests (esp. ModuleClasspathTests.testModuleWithClasspathAfterServerStarted) seem to fail because of a race condition.Add a Hamcrest matcher that knows how to read the content of a FileSink|Source and refactor those to read like e.g.assertThat(fileSink eventually(hasContent(\"foo)))',5,'Eric Bottard','Issues'),('Spring_XD','XD-997','The HDFS Sink should support writing POJOs to HDFS using Avro/Kite SDK with support for partitioning','Support for partitioning on a field e.g. date.',4,'Thomas Risberg','Issues'),('Spring_XD','XD-998','Add documentation for gemfire cache-listener source','Need some sample usage docs for https://github.com/spring-projects/spring-xd/tree/master/modules/source/gemfire',1,'David Turanski','Issues'),('Spring_XD','XD-999','Return the step execution information in the current job execution controller','Related to https://jira.springsource.org/browse/BATCH-2109DistributedJobService#listJobExecutionsForJob overrides SimpleJobService#listJobExecutionsForJoband does not include the *StepExecution*s. This is due to serializion issues with Jackson. In order to fix this we need to add a Jackson MixIn.',4,'Gunnar Hillert','Issues'),('UserGrid','USERGRID-1000','get apm/apigeeMobileConfig throws exception when its not set','2015-09-04 22:34:01420 [http-bio-8080-exec-22] ERROR org.apache.usergrid.rest.exceptions.AbstractExceptionMapper- Uncaught Exceptionjava.lang.IllegalArgumentException: JSON source MUST not be null        at com.sun.jersey.api.json.JSONWithPadding.<init>(JSONWithPadding.java:90)        at org.apache.usergrid.rest.applications.ApplicationResource.getAPMConfig(ApplicationResource.java:613)        at sun.reflect.NativeMethodAccessorImpl.invoke0(Native Method)        at sun.reflect.NativeMethodAccessorImpl.invoke(NativeMethodAccessorImpl.java:62)        at sun.reflect.DelegatingMethodAccessorImpl.invoke(DelegatingMethodAccessorImpl.java:43)        at java.lang.reflect.Method.invoke(Method.java:483)        at com.sun.jersey.spi.container.JavaMethodInvokerFactory$1.invoke(JavaMethodInvokerFactory.java:60)        at com.sun.jersey.server.impl.model.method.dispatch.AbstractResourceMethodDispatchProvider$TypeOutInvoker._dispatch(AbstractResourceMethodDispatchProvider.java:185)        at com.sun.jersey.server.impl.model.method.dispatch.ResourceJavaMethodDispatcher.dispatch(ResourceJavaMethodDispatcher.java:75)        at com.sun.jersey.server.impl.uri.rules.HttpMethodRule.accept(HttpMethodRule.java:302)        at com.sun.jersey.server.impl.uri.rules.RightHandPathRule.accept(RightHandPathRule.java:147)        at com.sun.jersey.server.impl.uri.rules.SubLocatorRule.accept(SubLocatorRule.java:137)        at com.sun.jersey.server.impl.uri.rules.RightHandPathRule.accept(RightHandPathRule.java:147)        at com.sun.jersey.server.impl.uri.rules.SubLocatorRule.accept(SubLocatorRule.java:137)        at com.sun.jersey.server.impl.uri.rules.RightHandPathRule.accept(RightHandPathRule.java:147)        at com.sun.jersey.server.impl.uri.rules.ResourceClassRule.accept(ResourceClassRule.java:108)        at com.sun.jersey.server.impl.uri.rules.RightHandPathRule.accept(RightHandPathRule.java:147)        at com.sun.jersey.server.impl.uri.rules.RootResourceClassesRule.accept(RootResourceClassesRule.java:84)        at com.sun.jersey.server.impl.application.WebApplicationImpl._handleRequest(WebApplicationImpl.java:1542)        at com.sun.jersey.server.impl.application.WebApplicationImpl._handleRequest(WebApplicationImpl.java:1473)        at com.sun.jersey.server.impl.application.WebApplicationImpl.handleRequest(WebApplicationImpl.java:1419)        at com.sun.jersey.server.impl.application.WebApplicationImpl.handleRequest(WebApplicationImpl.java:1409)        at com.sun.jersey.spi.container.servlet.WebComponent.service(WebComponent.java:409)        at com.sun.jersey.spi.container.servlet.ServletContainer.service(ServletContainer.java:558)        at com.sun.jersey.spi.container.servlet.ServletContainer.doFilter(ServletContainer.java:927)        at com.sun.jersey.spi.container.servlet.ServletContainer.doFilter(ServletContainer.java:875)        at com.sun.jersey.spi.container.servlet.ServletContainer.doFilter(ServletContainer.java:829)        at org.apache.catalina.core.ApplicationFilterChain.internalDoFilter(ApplicationFilterChain.java:241)        at org.apache.catalina.core.ApplicationFilterChain.doFilter(ApplicationFilterChain.java:208)        at org.apache.shiro.web.servlet.AbstractShiroFilter.executeChain(AbstractShiroFilter.java:449)        at org.apache.shiro.web.servlet.AbstractShiroFilter$1.call(AbstractShiroFilter.java:365)        at org.apache.shiro.subject.support.SubjectCallable.doCall(SubjectCallable.java:90)        at org.apache.shiro.subject.support.SubjectCallable.call(SubjectCallable.java:83)        at org.apache.shiro.subject.support.DelegatingSubject.execute(DelegatingSubject.java:383)        at org.apache.shiro.web.servlet.AbstractShiroFilter.doFilterInternal(AbstractShiroFilter.java:362)        at org.apache.shiro.web.servlet.OncePerRequestFilter.doFilter(OncePerRequestFilter.java:125)        at org.springframework.web.filter.DelegatingFilterProxy.invokeDelegate(DelegatingFilterProxy.java:343)        at org.springframework.web.filter.DelegatingFilterProxy.doFilter(DelegatingFilterProxy.java:260)        at org.apache.catalina.core.ApplicationFilterChain.internalDoFilter(ApplicationFilterChain.java:241)        at org.apache.catalina.core.ApplicationFilterChain.doFilter(ApplicationFilterChain.java:208)        at org.apache.usergrid.rest.filters.ContentTypeFilter.doFilter(ContentTypeFilter.java:92)        at org.apache.catalina.core.ApplicationFilterChain.internalDoFilter(ApplicationFilterChain.java:241)        at org.apache.catalina.core.ApplicationFilterChain.doFilter(ApplicationFilterChain.java:208)        at org.apache.catalina.core.StandardWrapperValve.invoke(StandardWrapperValve.java:220)        at org.apache.catalina.core.StandardContextValve.invoke(StandardContextValve.java:122)        at org.apache.catalina.authenticator.AuthenticatorBase.invoke(AuthenticatorBase.java:503)        at org.apache.catalina.core.StandardHostValve.invoke(StandardHostValve.java:170)        at org.apache.catalina.valves.ErrorReportValve.invoke(ErrorReportValve.java:103)        at org.apache.catalina.valves.AccessLogValve.invoke(AccessLogValve.java:950)        at org.apache.catalina.core.StandardEngineValve.invoke(StandardEngineValve.java:116)        at org.apache.catalina.connector.CoyoteAdapter.service(CoyoteAdapter.java:421)        at org.apache.coyote.http11.AbstractHttp11Processor.process(AbstractHttp11Processor.java:1070)        at org.apache.coyote.AbstractProtocol$AbstractConnectionHandler.process(AbstractProtocol.java:611)        at org.apache.tomcat.util.net.JIoEndpoint$SocketProcessor.run(JIoEndpoint.java:314)        at java.util.concurrent.ThreadPoolExecutor.runWorker(ThreadPoolExecutor.java:1142)        at java.util.concurrent.ThreadPoolExecutor$Worker.run(ThreadPoolExecutor.java:617)        at org.apache.tomcat.util.threads.TaskThread$WrappingRunnable.run(TaskThread.java:61)',3,'Shawn Feldman','Issues'),('UserGrid','USERGRID-1005','Add Background processing for delete application',NULL,2,'Shawn Feldman','Issues'),('UserGrid','USERGRID-1007','Implement a cache for Shiro & permissions','How will a cache help improve performance?* Reduce load on Tomcat ES and C* caused by permissons calculation.          Do we need a distributed cache?* YES: Todd says we tried non-distributed cache (w/EhCache) and the caching was not effective (bad hit/mss ratio).Implementation ideas:* Use Cassandra column family implementation * Use Hazelcast cache* Use EhCache configured for distributed operationHow much should we expect performance to improve? How can we test this?* JUnit + metrics collection in our cache implementationSimplest approach seems to be Cassandra. Here\'s a design:h1. Add new Core Persistence Cache moduleThis is a new module that depends only on the Core Persistence Common module (and maybe Model?) and provides a generic cache interface that is \"segmented\" by a cache scope. When you put or get things you specify the cache scope and it is possible to invalidate all things within a cache scope with one call.{code}public interface SegmentedCache<KV> {   /** Put value into segment with ttl */   void put( CacheScope scope K key V value long ttl );   /** Get value from segment */   V get( CacheScope segment K key );   /** Delete all cache data of all types and of all scopes */   void invalidate();   /** Delete all cache data within specified segment */   void invalidate( CacheScope segment );}{code}Caches are stored in Cassandra *Usergrid_Cache* column family:* Row-key is applicationId* Column key is toString() of K key* Value is serialized V value objecth1. Plugin our Cache into Shiro at the REST module levelTo plugin to Shiro we provide implementations of the Shiro *CacheManager* and *Cache* interfaces that are backed by the Cache module. When permissions are updated we need need to ensure that the old cached permissions are invalidated. So we will modify the *EntityManager* revoke and grant methods to call invalidate for the application\'s cache scope.',5,'David Johnson','Issues'),('UserGrid','USERGRID-1012','Geolocation with limit of 610.000 returns a result with distance of 610.09','Testing with the following entities and locations shows that we are rounding when people might not be expecting it:    UsergridEntity e = new UsergridEntity(collectionName);    e.setLocation(37.334115 -121.894340);    e.setProperty(\"name\" \"Apigee Office\");    e.POST();    UsergridEntity amicis = new UsergridEntity(collectionName);    amicis.setLocation(37.335616 -121.894168);    amicis.setProperty(\"name\" \"Amicis\");    amicis.POST();    UsergridEntity sanPedroMarket = new UsergridEntity(collectionName);    sanPedroMarket.setLocation(37.336499 -121.894356);    sanPedroMarket.setProperty(\"name\" \"SanPedroMarket\");    sanPedroMarket.POST();    UsergridEntity saintJamesPark = new UsergridEntity(collectionName);    saintJamesPark.setLocation(37.339079 -121.891422);    saintJamesPark.setProperty(\"name\" \"saintJamesPark\");    saintJamesPark.POST();    UsergridEntity sanJoseNews = new UsergridEntity(collectionName);    sanJoseNews.setLocation(37.337812 -121.890784);    sanJoseNews.setProperty(\"name\" \"sanJoseNews\");    sanJoseNews.POST();    UsergridEntity deAnza = new UsergridEntity(collectionName);    deAnza.setLocation(37.334370 -121.895081);    deAnza.setProperty(\"name\" \"deAnza\");    deAnza.POST();?ql=select+*++WHERE+location++within+610.0+of+37.334110260009766-121.89434051513672',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-1013','Automate upload of api baas 2.1 build to s3',NULL,3,NULL,'Issues'),('UserGrid','USERGRID-1014','Push Notification Delivery Expiration Not Working','When setting the \"expire\" property on notification entities the notification delivery attempts are not expiring (will the notification provider is re-trying the delivery even past the notification expiration).',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1015','Test Notification Migration',NULL,3,'Shawn Feldman','Issues'),('UserGrid','USERGRID-1016','Remove UUID field encoding in our ES fields','We shouldn\'t encode a UUID as a specific UUID field type since we\'re encoding it as a string.  To keep our index tuples simple and support both queries we should store it as a string type.  We should support the following formats.{code}select * where myUuid = \'aaa65d8a-16a6-11e5-86ea-7b4f7ff44431\'{code}As well as {code}select * where myUuid = aaa65d8a-16a6-11e5-86ea-7b4f7ff44431{code}Notice the addition of single quotes in the first query vs the parsing as a UUID type in the second query.  This will enable users to use both versions but does not affect performance.',3,'Shawn Feldman','Issues'),('UserGrid','USERGRID-1017','Create a job to clean unused edges','We need a system job that audits edges and ensures they point to an entity.  If not the edge should be removed.',3,'Todd Nine','Issues'),('UserGrid','USERGRID-1018','Create a job to remove duplicate connections and fix connection write logic','A bug in 2.0 has led to multiple edges on a connection.  We need a job that scans all connections and keeps the lowest timestamp on the connection.  Other edges should be deleted.',3,'Todd Nine','Issues'),('UserGrid','USERGRID-1021','Improve Location Attribute Handling to not require Lat/Lon and also be indexable','We should be able to store entities which have a \'location\' attribute which does not have both \'lat\' an \'lon\'.  These fields should also be queryable and therefore indexed.',NULL,'Shawn Feldman','Issues'),('UserGrid','USERGRID-1022','remove batching in index processing',NULL,1,'Shawn Feldman','Issues'),('UserGrid','USERGRID-1023','Delete from collection does not use SQS or the event service',NULL,3,'Shawn Feldman','Issues'),('UserGrid','USERGRID-1024',NULL,NULL,NULL,NULL,'Issues Summary'),('UserGrid','USERGRID-1025','Cass status fails in a 2.0 cluster','When the /status page is called in a UG 2.0 cluster running against a 2.0 cassandra the following stack is generated and the status incorrectly reports RED.{code}2015-09-16 22:25:57065 [http-bio-8080-exec-10] WARN  com.netflix.astyanax.connectionpool.impl.Slf4jConnectionPoolMonitorImpl- TokenRangeOfflineException: [host=ruc017sy.ap-sy.4.apigee.com(10.10.30.26):9160 latency=2(2) attempts=1]UnavailableException()2015-09-16 22:25:57065 [http-bio-8080-exec-10] ERROR org.apache.usergrid.persistence.collection.impl.EntityCollectionManagerImpl- Error connecting to Cassandracom.netflix.astyanax.connectionpool.exceptions.TokenRangeOfflineException: TokenRangeOfflineException: [host=ruc017sy.ap-sy.4.apigee.com(10.10.30.26):9160 latency=2(2) attempts=1]UnavailableException()        at com.netflix.astyanax.thrift.ThriftConverter.ToConnectionPoolException(ThriftConverter.java:165)        at com.netflix.astyanax.thrift.AbstractOperationImpl.execute(AbstractOperationImpl.java:65)        at com.netflix.astyanax.thrift.AbstractOperationImpl.execute(AbstractOperationImpl.java:28)        at com.netflix.astyanax.thrift.ThriftSyncConnectionFactoryImpl$ThriftConnection.execute(ThriftSyncConnectionFactoryImpl.java:151)        at com.netflix.astyanax.connectionpool.impl.AbstractExecuteWithFailoverImpl.tryOperation(AbstractExecuteWithFailoverImpl.java:119)        at com.netflix.astyanax.connectionpool.impl.AbstractHostPartitionConnectionPool.executeWithFailover(AbstractHostPartitionConnectionPool.java:338)        at com.netflix.astyanax.thrift.AbstractThriftCqlQuery.execute(AbstractThriftCqlQuery.java:41)        at org.apache.usergrid.persistence.collection.impl.EntityCollectionManagerImpl.getHealth(EntityCollectionManagerImpl.java:439)        at org.apache.usergrid.corepersistence.CpEntityManagerFactory.getEntityStoreHealth(CpEntityManagerFactory.java:730)        at org.apache.usergrid.rest.RootResource.getStatus(RootResource.java:199)        at sun.reflect.NativeMethodAccessorImpl.invoke0(Native Method)        at sun.reflect.NativeMethodAccessorImpl.invoke(NativeMethodAccessorImpl.java:62)        at sun.reflect.DelegatingMethodAccessorImpl.invoke(DelegatingMethodAccessorImpl.java:43)        at java.lang.reflect.Method.invoke(Method.java:497)        at org.glassfish.jersey.server.model.internal.ResourceMethodInvocationHandlerFactory$1.invoke(ResourceMethodInvocationHandlerFactory.java:81)        at org.glassfish.jersey.server.model.internal.AbstractJavaResourceMethodDispatcher$1.run(AbstractJavaResourceMethodDispatcher.java:144)        at org.glassfish.jersey.server.model.internal.AbstractJavaResourceMethodDispatcher.invoke(AbstractJavaResourceMethodDispatcher.java:161)        at org.glassfish.jersey.server.model.internal.JavaResourceMethodDispatcherProvider$TypeOutInvoker.doDispatch(JavaResourceMethodDispatcherProvider.java:205)        at org.glassfish.jersey.server.model.internal.AbstractJavaResourceMethodDispatcher.dispatch(AbstractJavaResourceMethodDispatcher.java:99)        at org.glassfish.jersey.server.model.ResourceMethodInvoker.invoke(ResourceMethodInvoker.java:389)        at org.glassfish.jersey.server.model.ResourceMethodInvoker.apply(ResourceMethodInvoker.java:347)        at org.glassfish.jersey.server.model.ResourceMethodInvoker.apply(ResourceMethodInvoker.java:102)        at org.glassfish.jersey.server.ServerRuntime$2.run(ServerRuntime.java:309)        at org.glassfish.jersey.internal.Errors$1.call(Errors.java:271)        at org.glassfish.jersey.internal.Errors$1.call(Errors.java:267)        at org.glassfish.jersey.internal.Errors.process(Errors.java:315)        at org.glassfish.jersey.internal.Errors.process(Errors.java:297)        at org.glassfish.jersey.internal.Errors.process(Errors.java:267)        at org.glassfish.jersey.process.internal.RequestScope.runInScope(RequestScope.java:317)        at org.glassfish.jersey.server.ServerRuntime.process(ServerRuntime.java:292)        at org.glassfish.jersey.server.ApplicationHandler.handle(ApplicationHandler.java:1139)        at org.glassfish.jersey.servlet.WebComponent.service(WebComponent.java:460)        at org.glassfish.jersey.servlet.ServletContainer.service(ServletContainer.java:386)        at org.glassfish.jersey.servlet.ServletContainer.doFilter(ServletContainer.java:548)        at org.glassfish.jersey.servlet.ServletContainer.doFilter(ServletContainer.java:489)        at org.glassfish.jersey.servlet.ServletContainer.doFilter(ServletContainer.java:426)        at org.apache.catalina.core.ApplicationFilterChain.internalDoFilter(ApplicationFilterChain.java:241)        at org.apache.catalina.core.ApplicationFilterChain.doFilter(ApplicationFilterChain.java:208)        at org.apache.shiro.web.servlet.AbstractShiroFilter.executeChain(AbstractShiroFilter.java:449)        at org.apache.shiro.web.servlet.AbstractShiroFilter$1.call(AbstractShiroFilter.java:365)        at org.apache.shiro.subject.support.SubjectCallable.doCall(SubjectCallable.java:90)        at org.apache.shiro.subject.support.SubjectCallable.call(SubjectCallable.java:83)        at org.apache.shiro.subject.support.DelegatingSubject.execute(DelegatingSubject.java:383)        at org.apache.shiro.web.servlet.AbstractShiroFilter.doFilterInternal(AbstractShiroFilter.java:362)        at org.apache.shiro.web.servlet.OncePerRequestFilter.doFilter(OncePerRequestFilter.java:125)        at org.springframework.web.filter.DelegatingFilterProxy.invokeDelegate(DelegatingFilterProxy.java:343)        at org.springframework.web.filter.DelegatingFilterProxy.doFilter(DelegatingFilterProxy.java:260)        at org.apache.catalina.core.ApplicationFilterChain.internalDoFilter(ApplicationFilterChain.java:241)        at org.apache.catalina.core.ApplicationFilterChain.doFilter(ApplicationFilterChain.java:208)        at org.apache.usergrid.rest.filters.ContentTypeFilter.doFilter(ContentTypeFilter.java:92)        at org.apache.catalina.core.ApplicationFilterChain.internalDoFilter(ApplicationFilterChain.java:241)        at org.apache.catalina.core.ApplicationFilterChain.doFilter(ApplicationFilterChain.java:208)        at org.apache.catalina.core.StandardWrapperValve.invoke(StandardWrapperValve.java:220)        at org.apache.catalina.core.StandardContextValve.invoke(StandardContextValve.java:122)        at org.apache.catalina.authenticator.AuthenticatorBase.invoke(AuthenticatorBase.java:505)        at org.apache.catalina.core.StandardHostValve.invoke(StandardHostValve.java:170)        at org.apache.catalina.valves.ErrorReportValve.invoke(ErrorReportValve.java:103)        at org.apache.catalina.valves.AccessLogValve.invoke(AccessLogValve.java:957)        at org.apache.catalina.core.StandardEngineValve.invoke(StandardEngineValve.java:116)        at org.apache.catalina.connector.CoyoteAdapter.service(CoyoteAdapter.java:423)        at org.apache.coyote.http11.AbstractHttp11Processor.process(AbstractHttp11Processor.java:1079)        at org.apache.coyote.AbstractProtocol$AbstractConnectionHandler.process(AbstractProtocol.java:620)        at org.apache.tomcat.util.net.JIoEndpoint$SocketProcessor.run(JIoEndpoint.java:316)        at java.util.concurrent.ThreadPoolExecutor.runWorker(ThreadPoolExecutor.java:1142)        at java.util.concurrent.ThreadPoolExecutor$Worker.run(ThreadPoolExecutor.java:617)        at org.apache.tomcat.util.threads.TaskThread$WrappingRunnable.run(TaskThread.java:61)        at java.lang.Thread.run(Thread.java:745)Caused by: UnavailableException()        at org.apache.cassandra.thrift.Cassandra$execute_cql3_query_result.read(Cassandra.java:38685)        at org.apache.thrift.TServiceClient.receiveBase(TServiceClient.java:78)        at org.apache.cassandra.thrift.Cassandra$Client.recv_execute_cql3_query(Cassandra.java:1597)        at org.apache.cassandra.thrift.Cassandra$Client.execute_cql3_query(Cassandra.java:1582)        at com.netflix.astyanax.thrift.ThriftCql3Query.execute_cql_query(ThriftCql3Query.java:34)        at com.netflix.astyanax.thrift.AbstractThriftCqlQuery$1.internalExecute(AbstractThriftCqlQuery.java:46)        at com.netflix.astyanax.thrift.AbstractThriftCqlQuery$1.internalExecute(AbstractThriftCqlQuery.java:43)        at com.netflix.astyanax.thrift.AbstractOperationImpl.execute(AbstractOperationImpl.java:60)        ... 65 more{code}When I run this command in cqlsh it succeeds{code}cqlsh> SELECT now() FROM system.local; now()-------------------------------------- 64cc0050-5cc2-11e5-bec7-61ce9a33c087(1 rows){code}',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-1026','Logic to detect (N+1)-d arrays catches a case where there is no 2-d array','This entity is not fully indexed with the error message below.  It does not have a (direct) 2-d array.  It does have nested arrays however.2015-09-18 03:20:28190 [Usergrid-RxIOPool-151] WARN  org.apache.usergrid.persistence.index.impl.EntityMappingParser- Encountered 2 collections consecutively.  N+1 dimensional arrays are unsupported only arrays of depth 1 are supported{   \"type\" : \"example\"   \"name\" : \"8980031\"   \"created\" : 1442527975706   \"modified\" : 1442547269098   \"FacilityName\" : \"ALICES RESTAURANT\"   \"LastUpdateOn\" : \"9/17/2015\"   \"Locations\" : [ {     \"Addresses\" : [ {       \"Zip\" : \"94062\"       \"AddressLine1\" : \"17288 Skyline Blvd\"       \"LatNbr\" : \"37.386916\"       \"LongNbr\" : \"-122.265383\"       \"State\" : \"CA\"       \"AddrUseCd\" : \"PH\"       \"City\" : \"WOODSIDE\"     } ]     \"Phones\" : [ {       \"PhnUseCd\" : \"PH\"       \"PhoneNbr\" : \"123-456-3534\"     } ]     \"LocSeq\" : \"1\"     \"PracLocStrtDt\" : \"1/1/9999\"     \"PracLocEndDt\" : \"3/31/9999\"     \"Accepting\" : false     \"PracLocSpecialties\" : [ {       \"SpcltyPrimInd\" : \"Y\"       \"SpcltyDsc\" : \"PANCAKES\"       \"SpcltyCd\" : \"BRKF\"     } ]   } ]   \"TheId\" : 8980031   \"ProviderType\" : \"FAC\"   \"PvdrEndDt\" : \"3/31/2008\"   \"PvdrSpecialties\" : [ {     \"SpcltyPrimInd\" : \"Y\"     \"SpcltyDsc\" : \"PANCAKES\"     \"SpcltyCd\" : \"BRKF\"   } ] }',1,'Michael Russo','Issues'),('UserGrid','USERGRID-1027','Occational MIsses on Indexing into Elasticsearch','Occasionally applications still aren\'t being indexed into elasticsearch. Need to investigate why these might be occuring.',8,NULL,'Issues'),('UserGrid','USERGRID-1029','When PUTing by uuid or name add the entry into entity_id_sets column family','When a PUT occurs in 1.0 then entry to Entity_Id_Sets is not re-inserted.  We need to ensure it is re-written.',3,'Todd Nine','Issues'),('UserGrid','USERGRID-103','Upgrade to latest Jersey 2.x release','JAX-RS 2.0 brings lots of new features much better extensible and async support are ones I think most useful',5,'David Johnson','Issues'),('UserGrid','USERGRID-1031','Test and confirm Usergrid 1.0 works with Cassandra 2.1','1) Test locally2) Confirm in e2e',2,'Michael Russo','Issues'),('UserGrid','USERGRID-1032','Test and confirm Usergrid 2.1 works with Cassandra 2.1',NULL,2,'Michael Russo','Issues'),('UserGrid','USERGRID-1033','Test and confirm Usergrid 2.0 works with Cassandra 2.1',NULL,1,'Michael Russo','Issues'),('UserGrid','USERGRID-1038','2.1-release: fix index batching from SQS reader',NULL,3,'Shawn Feldman','Issues'),('UserGrid','USERGRID-1044','Support for gatling load testing with unlimited feed','Support for multi-worker testing that can create an unlimited number of entities that can be audited. Includes a new interleaving feed for creating new entities as well as creating chunked CSV files in the audit format so that creation and indexing can be validated.',NULL,'Mike Dunker','Issues'),('UserGrid','USERGRID-1046',NULL,NULL,NULL,NULL,'Issues Summary'),('UserGrid','USERGRID-1047','GET on missing Asset file in S3 generates 500 error not 404','When doing a GET on an asset file that doesn\'t exist it should return a 404 rather than a 500 error because the file is not there.',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-1048','When reading messages from SQS an elevated consistency may be needed with latent replication','Occasionally Cassandra multi-region replication lags during high load.  During this high load messages fail to process because it cannot read the entity from Cassandra.  Rather than fail we should retry with a high consistency level of quorum in all regions to ensure we replicate the data correctly.',3,'Todd Nine','Issues'),('UserGrid','USERGRID-1049','Add originating region to SQS queue message','The region will be used to optimize handling of SQS messages that arrive faster than the corresponding C* changes.Name in the SQS message body \"sourceRegion\".',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1050','Remove SQS implementation','SQS impl is no longer necessary with the current implementation.  We should always use the SNS implementation.  Remove it and configure the SNS implementation to work with a single region.',NULL,NULL,'Issues'),('UserGrid','USERGRID-1051','When ElasticSearch rejects a Search request Usergrid should not return 200 OK with an empty array','Currently if the search queue is full a 200 response is returned with an empty entity array.',1,'George Reyes','Issues'),('UserGrid','USERGRID-1052','After large deletions graph seek time becomes slow','After a large number of deletions 100k + seek time on graph becomes very slow when searching collections.  Identify the issue and implement a fix based off of sha  a09485a3a5ac8b4217b294f4754ea8a70a7ec447',5,'Todd Nine','Issues'),('UserGrid','USERGRID-1053','[SPIKE] Audit TODOs in the code','We need to audit the TODO statements in the code.  For each we must:1) Check if there is an existing ticket- If there is no ticket create one2) Update the TODO statement with the link to the ticket3) Prioritize based on:- Will this generate a P1 case with a customer?- What is the usability impact of the product?Once we have audited these we will prioritize and schedule fixes',5,'Todd Nine','Issues'),('UserGrid','USERGRID-1056','ES Documents not getting deleted when deleting entities','EntityDeleteEvents are not processing successfully causing no documents to get deleted when an entity is deleted.{code}2015-10-21 03:17:02177 [QueueConsumer_3] ERROR org.apache.usergrid.corepersistence.asyncevents.AmazonAsyncEventService- Received empty index sequence message:(d51bd93b-f26d-4bb1-a643-19ff097f4ba5) body:({\"entityDeleteEvent\":{\"creationTime\":1445396528637\"sourceRegion\":\"us-east-1\"\"entityIdScope\":{\"id\":{\"uuid\":\"3504d238-7467-11e5-b7a4-123f5d920dd1\"\"type\":\"testentity\"}\"applicationScope\":{\"application\":{\"uuid\":\"857fd592-7385-11e5-93f4-0af922a4f655\"\"type\":\"application\"}}}}}){code}',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1058','Ability to generate a master Jacoco coverage report','In addition to separate Jacoco reports for each module we should also be able to generate a master Jacoco report.',3,'David Johnson','Issues'),('UserGrid','USERGRID-1062','Entity Edges are not getting deleted from graph when handling delete event',NULL,NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1064','Create a system endpoint to de-dup connections per application','We need the ability to de-dupe connections per application.  This will enable migrating specific user applications when a shared keyspace is used.',NULL,'Todd Nine','Issues'),('UserGrid','USERGRID-1065','Create a system endpoint for the superuser to GET all apps for an org',NULL,NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1066','Create a system endpoint for the superuser to GET all orgs in the system',NULL,NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1067','Finish 2.1 release testing','We need to test the following issues to verify they\'ve been fixed.Multi region writes and index syncingMulti region mass collection deletes: Delete the entire collection then ensure that seek times are fast with no query language.',3,'Mike Dunker','Issues'),('UserGrid','USERGRID-1068','Create a per app migration script','Create a python script that will allow users to upgrade from 2.0 to 2.1 per application.  This will ultimately allow an incremental deployment across an existing 2.0 cluster without user impact.  Template for full system script that already exists: https://github.com/apache/usergrid/blob/2.1-release/stack/scripts/migrate_entity_data.pyIt should allow for the following migration process:tenant 11) setup new 2.1 tomcat2) run migration bootstrap3) migrate appinfo4) reindex mgmt app only5) run de-dup for whatever APP6) reindex whatever APP7) add 2.1 tomcats to customer ELB after 1-6 completed for all customer apps8) run delta re-index/migration for all customer appstenant 21) reset appinfo version2) migrate app info3) reindex mgmt app4) run de-dup for whatever APP5) reindex whatever app7) add 2.1 tomcats to customer ELB after 1-6 completed for all customer apps8) run delta re-index/migration for all customer appsafter all apps migration1) migrate entity data',2,'David Johnson','Issues'),('UserGrid','USERGRID-1069','implement build metrics in jenkins',NULL,1,'Shawn Feldman','Issues'),('UserGrid','USERGRID-1071','Test iOS push notifications',NULL,1,'Shawn Feldman','Issues'),('UserGrid','USERGRID-1072','Test Android push notifications',NULL,1,'Shawn Feldman','Issues'),('UserGrid','USERGRID-1073','Test Windows phone',NULL,1,'Shawn Feldman','Issues'),('UserGrid','USERGRID-1074','[SPIKE] Evaluate read repair of unique values in 1.0',NULL,1,'George Reyes','Issues'),('UserGrid','USERGRID-1075','Create Repair Tool to address Service Resource Exceptions from users who cannot be queried for their data','Find a way to resolve the state where a user may still have an entity ref but is not able to be queried or retrieved without uuid.',5,'George Reyes','Issues'),('UserGrid','USERGRID-1076','Create a Repair tool that will address null pointer exceptions on entity returns and then properly handle them','500 null pointer exceptions return when data is present in an entity reference but not returned from cassandra while this may be a data consistency issue an investigation needs to be done. That said in the mean time a tool should be created that either can retrieve the data and restore it ( update ) or to delete the left over entity reference.',5,'George Reyes','Issues'),('UserGrid','USERGRID-1079','Add 2 endpoints for password hash migration','It is currently possible to migrate from a 1.0 installation to a 2.1 installation via a RESTful client.  However due to the inability to securely move password hashes application user\'s passwords are not retained.   Add the following.# In the 1.x branch add the ability to retrieve the password hash.   This should only be allowed by the superuser.# In 2.1-release add the ability to write the password hash to an application user.  This should only be allowed by the superuser.Note that the reason this is only allowed as a superuser is that we want to disable this functionality by default.  Any UG installation that is public facing should not have superuser enable.  This allows us to disable this functionality in environments that are publicly available environments.',5,'Todd Nine','Issues'),('UserGrid','USERGRID-1080','Change elasticsearch query for retrieving versions','Currently using scroll and also does a select * followed by post query filters which may be hugely inefficient.New solution uses repeated requests where we query (not scroll) through the results by ordering by edge timestamp and then excluding previously found timestamp range in successive queries.Michael/Mike pairing.',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1083','getEntityByName 404 API response logs unnecessary Uncaught Exception ERROR','2015-10-29 00:50:19056 [http-bio-8080-exec-342] ERROR org.apache.usergrid.rest.exceptions.AbstractExceptionMapper- Uncaught Exceptionorg.apache.usergrid.persistence.exceptions.EntityNotFoundException: Cannot find entity with name: test2307924        at org.apache.usergrid.services.AbstractCollectionService.getItemByName(AbstractCollectionService.java:155)',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-1085','Create RPM Distributable for Usergrid 2.1',NULL,5,'Michael Russo','Issues'),('UserGrid','USERGRID-1088','Objects nested in arrays are not getting indexed.','In Usergrid we don\'t support n+1 arrays for indexing however if you have objects nested within arrays we should index the nested object\'s key/value pairs.In the below document *\"nestedKey\": \"nestedValue\"* and *\"key\": \"value\"* should get indexed.  The value  *\"1\" in nestedLists* should still NOT be indexed.{code}{  \"name\": \"region3\"  \"nestedLists\": [    [      \"1\"    ]  ]  \"nestedObjects\": [    {      \"array\": [        {          \"nestedKey\": \"nestedValue\"        }      ]      \"key\": \"value\"    }  ]}{code}',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1090','DELETE on missing User entity returns 401 not 404','DELETE on /org/app/users/{missing_uuid} returns 401.  It should return 404 when there is a valid token used.',NULL,'Mike Dunker','Issues'),('UserGrid','USERGRID-1091','AbstractReadGraphFilter produces and queues empty queue operations','When read repair is triggered it is possible that there are now deIndexRequests to be queued.  Currently we\'re queueing empty operations and need to filter this properly.',1,'Michael Russo','Issues'),('UserGrid','USERGRID-1093','Load test in-memory queue with current consumer and queue implementation',NULL,3,'Michael Russo','Issues'),('UserGrid','USERGRID-1095','Investigate query parsing and execution issues related to order of operations',NULL,NULL,NULL,'Issues'),('UserGrid','USERGRID-1098','Perform quorum reads only after waiting and retrying','If indexing requests make it to another region before C* has replicated the data and a local quorum read fails we retry with a quorum read immediately. It would be better to give some time for C* to replicate the data so we should put the message back in the queue at least once before trying the quorum read.The delete issues we had show how bad large amounts of quorum reads can be on a C* cluster so we should avoid where possible.',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1099','Order of operations error in Query Execution','I have a test that shows that queries of this form work:C = c and ( A > a or B = false )But the very same query formed like this will not work properly:( A > a or B = false ) and C = c',5,'David Johnson','Issues'),('UserGrid','USERGRID-11','Limit the size of entities posted to Usergrid','Currently you can post items of almost any size to UG. We should determine the maximum size that is still optimum (15-16MB?) and enforce this.[~zznate] do you have a recommendation?',NULL,'Todd Nine','Issues'),('UserGrid','USERGRID-1100','POST /users/{user}/devices/notifications does not work.',NULL,1,'Michael Russo','Issues'),('UserGrid','USERGRID-1101','Unique Value Cleanup in 2.1 - cleaning up old columns for old versions','Ensure code makes it in to prevent wide rows in unique_values CF due to old versions not getting cleaned up',3,NULL,'Issues'),('UserGrid','USERGRID-1104','Indexes in Elasticsearch created with alias names','This was seen when running the index mapping migration plugin on an elastic search cluster that\'s already running with indexes that have the latest mapping we see the following exception and the migration does not complete:{code}2015-11-11 19:26:17468 [Index migrate data formats] INFO  org.apache.usergrid.persistence.core.migration.data.DataMigrationManagerImpl- Migration version 2.  Failed to migrate reason is appended.  Error \'failed to update\' org.elasticsearch.index.mapper.MergeMappingException: Merge failed with failures {[mapper [entityVersion] has different index values mapper [entityVersion] has different doc_values values mapper [entityVersion] has different tokenize values mapper [entityVersion] has different index_analyzer mapper [edgeName] has different index values mapper [edgeName] has different doc_values values mapper [edgeName] has different tokenize values mapper [edgeName] has different index_analyzer mapper [entityNodeType] has different index values mapper [entityNodeType] has different doc_values values mapper [entityNodeType] has different tokenize values mapper [entityNodeType] has different index_analyzer mapper [edgeTimestamp] has different doc_values values mapper [entityType] has different index values mapper [entityType] has different doc_values values mapper [entityType] has different tokenize values mapper [entityType] has different index_analyzer mapper [entitySize] has different doc_values values mapper [_all] enabled is true now encountering false mapper [edgeSearch] has different index values mapper [edgeSearch] has different doc_values values mapper [edgeSearch] has different tokenize values mapper [edgeSearch] has different index_analyzer mapper [entityId] has different index values mapper [entityId] has different doc_values values mapper [entityId] has different tokenize values mapper [entityId] has different index_analyzer mapper [nodeId] has different index values mapper [nodeId] has different doc_values values mapper [nodeId] has different tokenize values mapper [nodeId] has different index_analyzer mapper [applicationId] has different index values mapper [applicationId] has different doc_values values mapper [applicationId] has different tokenize values mapper [applicationId] has different index_analyzer object mapping [fields] can\'t be changed from non-nested to nested]}        at org.elasticsearch.cluster.metadata.MetaDataMappingService$4.execute(MetaDataMappingService.java:511)        at org.elasticsearch.cluster.service.InternalClusterService$UpdateTask.run(InternalClusterService.java:352)        at org.elasticsearch.common.util.concurrent.PrioritizedEsThreadPoolExecutor$TieBreakingPrioritizedRunnable.runAndClean(PrioritizedEsThreadPoolExecutor.java:184)        at org.elasticsearch.common.util.concurrent.PrioritizedEsThreadPoolExecutor$TieBreakingPrioritizedRunnable.run(PrioritizedEsThreadPoolExecutor.java:154)        at java.util.concurrent.ThreadPoolExecutor.runWorker(ThreadPoolExecutor.java:1142)        at java.util.concurrent.ThreadPoolExecutor$Worker.run(ThreadPoolExecutor.java:617)        at java.lang.Thread.run(Thread.java:745)Caused by: rx.exceptions.OnErrorThrowable$OnNextValue: OnError while emitting onNext value: rug000dn_a47ce531-0020-11e5-bfa2-0a0dfc3edbb7_write_alias        at rx.exceptions.OnErrorThrowable.addValueAsLastCause(OnErrorThrowable.java:104)        at rx.internal.operators.OperatorDoOnEach$1.onNext(OperatorDoOnEach.java:81)        at rx.internal.operators.OperatorMerge$MergeSubscriber.emitScalar(OperatorMerge.java:364)        at rx.internal.operators.OperatorMerge$MergeSubscriber.tryEmit(OperatorMerge.java:326)        at rx.internal.operators.OperatorMerge$InnerSubscriber.onNext(OperatorMerge.java:802)        at rx.internal.operators.OnSubscribeFromIterable$IterableProducer.slowpath(OnSubscribeFromIterable.java:97)        at rx.internal.operators.OnSubscribeFromIterable$IterableProducer.request(OnSubscribeFromIterable.java:73)        at rx.Subscriber.setProducer(Subscriber.java:211)        at rx.internal.operators.OnSubscribeFromIterable.call(OnSubscribeFromIterable.java:49)        at rx.internal.operators.OnSubscribeFromIterable.call(OnSubscribeFromIterable.java:32)        at rx.Observable.unsafeSubscribe(Observable.java:7710)        at rx.internal.operators.OperatorMerge$MergeSubscriber.onNext(OperatorMerge.java:231)        at rx.internal.operators.OperatorMerge$MergeSubscriber.onNext(OperatorMerge.java:140)        at rx.internal.operators.OperatorMap$1.onNext(OperatorMap.java:55)        at rx.internal.operators.OnSubscribeToObservableFuture$ToObservableFuture.call(OnSubscribeToObservableFuture.java:74)        at rx.internal.operators.OnSubscribeToObservableFuture$ToObservableFuture.call(OnSubscribeToObservableFuture.java:42)        at rx.Observable$2.call(Observable.java:162)        at rx.Observable$2.call(Observable.java:154)        at rx.Observable$2.call(Observable.java:162)        at rx.Observable$2.call(Observable.java:154)        at rx.Observable$2.call(Observable.java:162)        at rx.Observable$2.call(Observable.java:154)        at rx.Observable$2.call(Observable.java:162) at rx.Observable$2.call(Observable.java:154)        at rx.Observable$2.call(Observable.java:162)        at rx.Observable$2.call(Observable.java:154)        at rx.Observable$2.call(Observable.java:162)        at rx.Observable$2.call(Observable.java:154)        at rx.Observable.subscribe(Observable.java:7804)        at rx.Observable.subscribe(Observable.java:7772)        at rx.Observable.subscribe(Observable.java:7484)        at org.apache.usergrid.persistence.index.migration.EsIndexMappingMigrationPlugin.run(EsIndexMappingMigrationPlugin.java:97)        at org.apache.usergrid.persistence.core.migration.data.DataMigrationManagerImpl.lambda$migrate$2(DataMigrationManagerImpl.java:124)        at org.apache.usergrid.persistence.core.migration.data.DataMigrationManagerImpl$$Lambda$121/1554791835.accept(Unknown Source)        at java.util.ArrayList.forEach(ArrayList.java:1249)        at org.apache.usergrid.persistence.core.migration.data.DataMigrationManagerImpl.migrate(DataMigrationManagerImpl.java:122)        at org.apache.usergrid.rest.system.MigrateResource$1.run(MigrateResource.java:99){code}',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1106','Fix test: clientCredentialsFlowWithHeaderAuthorization()','Currently this test is ignored in Usergrid master branch:ApplicationResourceIT.clientCredentialsFlowWithHeaderAuthorization()If it is still relevant we should fix it and un-ignore it.',3,'David Johnson','Issues'),('UserGrid','USERGRID-1112','Test and Fix Shard Delete','There is a race condition between shard allocation and shard delete.  When a shard has been allocated it is getting removed AFTER edges are present.  This needs resolved.',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1113','Improve NotificationsService test coverage','Currently many of the NotificationsServiceIT and NotifiersServiceIT test are either broken or incomplete because we were unable to create the mocks we need to test the code. We should revisit this and figure out how to get better test coverage for notifications in general.Search the code for USERGRID-1113 to find the tests that should be unignored fixed replace or deleted.',2,'Michael Russo','Issues'),('UserGrid','USERGRID-1115','Fix AdminUsersIT tests','Six of the AdminUsersIT tests are ignored because they interfere with other tests and other reasons.  Figure out how to run those tests serially or some other way to test admin user features.',5,'David Johnson','Issues'),('UserGrid','USERGRID-1116','Fix MessagesIT tests','Four of the MessagesIT tests are ignored. Fix these tests and un-ignore them.',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-1118','Fix EventsResource and IT','The EventsResource was broken during two-dot-o development and the tests in EventsResourceIT were marked ignore.Fix the EventsResource and re-enable the tests.',3,'George Reyes','Issues'),('UserGrid','USERGRID-1119','Fix GroupResourceIT.postGroupActivity() test',NULL,3,'David Johnson','Issues'),('UserGrid','USERGRID-1120','Fix CounterIT.testIncrementAndDecrement() test',NULL,NULL,'George Reyes','Issues'),('UserGrid','USERGRID-1122','NullPointerException during read repair','In buildEntityDelete in EventBuilderImpl it can return null.  This is causing NPEs in AbstractReadGraphFilter.  We should return a result set with an empty observable instead of returning null.',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1124','Internal \"size\" within entity metadata is not displayed when doing a GET by entity name','This request does not come back with size in metadata object. GET /org/app/collection/entityName{code}{  \"action\" : \"get\"  \"application\" : \"ec2df3b3-6e0e-11e5-9798-0223e9015bf9\"  \"params\" : { }  \"path\" : \"/regions\"  \"uri\" : \"https://testing\"  \"entities\" : [ {    \"uuid\" : \"2dcf254c-8ef5-11e5-87c2-069a7df27e87\"    \"type\" : \"region\"    \"name\" : \"region6\"    \"created\" : 1447961939135    \"modified\" : 1447961939135    \"metadata\" : {      \"path\" : \"/regions/2dcf254c-8ef5-11e5-87c2-069a7df27e87\"    }  } ]  \"timestamp\" : 1447976782774  \"duration\" : 77  \"organization\" : \"org\"  \"applicationName\" : \"app\"}{code}However get with the entity\'s UUID does return the metadata size.GET /org/app/collection/2dcf254c-8ef5-11e5-87c2-069a7df27e87{code}{  \"action\" : \"get\"  \"application\" : \"ec2df3b3-6e0e-11e5-9798-0223e9015bf9\"  \"params\" : { }  \"path\" : \"/regions\"  \"uri\" : \"https://testing\"  \"entities\" : [ {    \"uuid\" : \"2dcf254c-8ef5-11e5-87c2-069a7df27e87\"    \"type\" : \"region\"    \"name\" : \"region6\"    \"created\" : 1447961939135    \"modified\" : 1447961939135    \"metadata\" : {      \"path\" : \"/regions/2dcf254c-8ef5-11e5-87c2-069a7df27e87\"      \"size\" : 334    }  } ]  \"timestamp\" : 1447977010952  \"duration\" : 36  \"organization\" : \"org\"  \"applicationName\" : \"app\"}{code}',1,'Michael Russo','Issues'),('UserGrid','USERGRID-1126','Documents not getting index when JSON contains latitude or longitude fields with empty string values','Exception seen:{code}2015-11-21 21:40:37249 [Usergrid-SQS-Pool-88] ERROR org.apache.usergrid.corepersistence.asyncevents.AmazonAsyncEventService- Failed to index message: 7435e8a3-9f4c-4a08-a833-307698c45cbdjava.lang.RuntimeException: Error during processing of bulk index operations one of the responses failed.MapperParsingException[failed to parse]; nested: NumberFormatException[empty String];{code}Inside the entities there are latitude and longitude fields which contain empty strings.  These are mapped in Usergrid/Elasticsearch as geo_point types which are expected to be numbers or non-empty strings that can parse to coordiantes.  This is causing the document to get rejected upon indexing.  See the following for ensuring we are pre-validating so documents don\'t get rejected: https://www.elastic.co/guide/en/elasticsearch/reference/1.7/mapping-geo-point-type.htmlNeeds to be fixed here to not add the lat and lon properties if the values are null or empty strings  (non empty strings index without a problem).org/apache/usergrid/persistence/index/impl/EntityMappingParser.java:133A temporary workaround is just to assign a number value for these fields or just don\'t include them at all in the JSON request.Current:{code}\"geographicCoordinates\": {              \"latitude\": \"\"              \"longitude\": \"\"            }{code}Example workaround:{code}\"geographicCoordinates\": {              \"latitude\": 1              \"longitude\": 1            }{code}',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1128','Entity request by uuid that doesn\'t exist returns 401 instead of 404','Note: validated fixed in 2.1 unresolved in 1.0. Do we need to mark this as #wontfix?If you call the following without auth:https://api.usergrid.com/brandon.apigee/sandbox/tests/b3037a1a-4cd6-11e5-8aa2-0b8eb3ce43efYou can an entity response.If you call:https://api.usergrid.com/brandon.apigee/sandbox/tests/b3037a1a-4cd6-11e5-8aa2-0b8eb3ce43eeYou get the correct error body but the response status code is 401. Expect it to be 404.',NULL,'Mike Dunker','Issues'),('UserGrid','USERGRID-1181','Allow notification entities to be deleted if they are not \"in progress\"','Update NotificationsService to be allow removal of notifications that are not in a processing state:{code}@Override    protected boolean isDeleteAllowed(ServiceContext context Entity entity) {        Notification notification = (Notification) entity;        Notification.State state = notification.getState();        return !(state.equals(Notification.State.CREATED) || state.equals(Notification.State.STARTED) ||                state.equals(Notification.State.SCHEDULED));    }{code}',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1182','Support GCM 3.0 for Android Push Notifications',NULL,2,'Michael Russo','Issues'),('UserGrid','USERGRID-1183','Support APNS VoIP Push Notifications','If using older APNS binary provider multiple certificates would need to be managed as VoIP certificates are provisioned separately by Apple.  If using newer HTTP/2 implementation  Apple allows a single cert (provisioned with one or more topics) to work for regular voip watch notifications for example.  Using HTTP/2 implementation is preferred.',2,'Michael Russo','Issues'),('UserGrid','USERGRID-1185','PUT by name does a GET on an entity twice','We are tracking down the need for lots of GC on continuous PUT by name (different name/entities).  When looking at this we discovered that there are two GETs of an entity when doing PUT by name: 1) GET to see if it exists and 2) GET to get the entity to update (since PUT is really a PATCH).It would be more optimal to only have one GET in this scenario',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1186','Add DELETE for Admin Users','#NAME?',2,'George Reyes','Issues'),('UserGrid','USERGRID-1187','Ensure that PUT or POST does not create duplicate org association connections.','Doing PUT creates a duplicate edge on /management/orgs/org/users/emailfor existing users who were already on the org the POST command to /management/orgs/org/users/email creates a duplicate edge',2,'George Reyes','Issues'),('UserGrid','USERGRID-119','Automate create of Usergrid release bundles','There are two parts to this:1. The source code release bundleApache releases are source code so this is the \"primary\" release bundle. It should be a Tar and/or Gzipped Tar file that contains all of our source code.2. The binary release bundleThis is intended to be a convenience for people who want to get a copy of the Usergrid that is ready for deployment. It should contain the ROOT.war file the launcher Jar and the Portal Zip file plus a pointer to docs that explain how to deploy and run them.',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-1191','Create 2.1 Release for Apache','We need to create a 2.1 release for Apache.  Would be nice to have a binary WAR distribution.',3,'David Johnson','Issues'),('UserGrid','USERGRID-1192','Evaluate GC and profile 2.1 for GC settings optimization','We have seen a large number of long GC pauses',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1193','Evaluate code to reduce GC pressure','Review the code paths and look at areas where we can improve the code (low hanging fruit obvious things) which reduce the GC pressure.',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1197','Test and confirm DELETE APP in an integration environment','We need integration test validation for DELETE APP.  We also need to handle really deleting the application data.[~djohnson]',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-1200','Org config override for portal and API URLs','1. Add usergrid.api.url.base property (defaults to http://localhost:8080/ROOT) that can be overridden for an org.2. The confirmation and activation properties are hardcoded paths and don\'t need org overrides. Example:usergrid.admin.activation.url is built by concatenating usergrid.api.url.base and \"/management/users/%s/activate\"3. swagger.basepath removed and replaced by usergrid.api.url.base.4. Refactor orgconfig to return system defaults if not configurable by org.usergrid.redirect_root changes will happen later -- org not known when setting is being used so no need to add an org config item.',NULL,'Mike Dunker','Issues'),('UserGrid','USERGRID-1203','Allow certs in notifiers to be updated and store their details in the entity.',NULL,1,'Michael Russo','Issues'),('UserGrid','USERGRID-1205','Duplicate Admin Repair','Develop a duplicate admin user repair tool that is testable with a dry-run feature.',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-1207','Notification statistics are not accurate','In org.apache.usergrid.services.notifications.TaskManager the task updates an entity but in a multi-threaded environment this can lead to inconsitiencies due to the way it\'s implemented with getting an entity incrementing the stats at this point in time and then writing it back. If 2 threads do this at nearly the same time they both could be incrementing from the same base entity data and each overwrite with a single increment rather than the value being incremented on the latest update to date changes. Need to make this thread safe or see about using counters for these type of statistics.',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1208','Complete Push Notifications TestAdapter functionality.','Add all of the necessary functionality to the TestAdapter instead of having its interface implementations be empty methods. With this introduce a new NotificationServiceIT for the test adapter and do any mock testing here.  Remove the option for USE_REAL_CONNECTIONS in apns and gcm tests as they should always use real connections and TestAdapter mock a \"no provider\" scenario.',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1209','GET on missing Asset file in S3 generates 500 error not 404',NULL,1,'George Reyes','Issues'),('UserGrid','USERGRID-1210','Fix AwsAssetResourceIT','Fix all the broken asset tests',3,'George Reyes','Issues'),('UserGrid','USERGRID-1211','Migrate locks from Hector to Astyanax','Implement locks and a lock manager using Astyanax driver.',3,'Michael Russo','Issues'),('UserGrid','USERGRID-1240','Test and integrate Pushy SOCKS changes','Test changes in https://github.com/relayrides/pushy/pull/215 and confirm it works for using APNS via a SOCKS proxy.  This is important for users of Usergrid which are behind corporate firewalls.For reference: https://github.com/relayrides/pushy/issues/99#issuecomment-175152811',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1241','Org config settings for view redirects','The usergrid.view.* properties are currently used to redirect on activation or confirmation of organizations or users. These may need to be configured differently for different customers.The usergrid.view.* property names are made by concatenating package template and class names so instead of adding them as hardcoded org config items add a property (usergrid.org.config.property.regex) to specify the regex for additional properties that may be configured by org.Also add check for org overrides for the redirect properties.',NULL,'Mike Dunker','Issues'),('UserGrid','USERGRID-1243','Replace logging string concatenation with formatting','Concatenating strings when logging creates temporary strings that can have a negative effect on GC. Instead log4j\'s string formatting functionality should be used.Example:Replacelogger.info(\"Invalid property value. name = \" + name + \" value = \" + value);withlogger.info(\"Invalid property value. name = {} value = {}\" name value);Also:1) Standardize on slf4j version 1.7.2 which includes variable argument support.2) Remove extraneous object creation (for when variable argument support didn\'t exist).3) Change debug statements for element creation/deletion connections etc. to trace.',NULL,'Mike Dunker','Issues'),('UserGrid','USERGRID-1244','Upgrade pushy library to use latest version (HTTP/2 APNS implementation)','Additional system requirements will need to be met (https://github.com/relayrides/pushy#system-requirements):1) require openssl to be installed on servers running Usergrid and have specific compiled versions of usergrid for the supported platforms for running Usergrid (os version etc.).  http://netty.io/wiki/forked-tomcat-native.html2) require an additional jar file added to the boot classpath of the jvm (alpn-boot) which is specific to the JDK version being usedIt may make sense to see about having the ability to disable push so that no push notification services are bootstrapped in the event someone wants to use Usergrid but does not require push and does not want to manage these additional system requirements.Option 1 preferred at the moment as having OpenSSL installed is an easy requirement and and the platform configurations for http://netty.io/wiki/forked-tomcat-native.html seem limited.',2,'Michael Russo','Issues'),('UserGrid','USERGRID-1245','Find alternative to com.clearspring.analytics','com.clearspring.analytics.hash.MurmurHash is found in the fasterutil dependency which is 16MB.  We want to pare down the size of the REST WAR file.  Let\'s see if there is an alternative.Here is the maven dependency:{code}    <dependency>      <groupId>com.clearspring.analytics</groupId>      <artifactId>stream</artifactId>      <version>2.7.0</version>    </dependency>{code}Look for the com.clearspring.analytics package.  Seems to be used in GCM Adapter:{code}   private Batch getBatch( Map<String Object> payload) {       synchronized (this) {           long hash = MurmurHash.hash64(payload);           Batch batch = batches.get(hash);           if (batch == null && payload != null) {               batch = new Batch(notifier payload);               batches.put(hash batch);           }           return batch;       }   }{code}Also the CountMinSketch is used from this dependency:org/apache/usergrid/services/notifications/impl/ApplicationQueueManagerImpl.java:111{code}final CountMinSketch sketch = new CountMinSketch(0.0001.997364181); //add probablistic counter to find dups{code}',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1246','Remove Unnecessary dependencies','You can see/sort the dependency files in /Users/ApigeeCorporation/code/usergrid/apache/usergrid/stack/rest/target/ROOT and use the dependency tree/graph in IntelliJList:- Hazelcast- Choose netty-all-4.0.23.Final or netty-3.6.6.Final or netty-3.2.7.Final- snappy-java- usergrid-core: org.boss.netty- antlr-2.7.7 vs antlr-3.5.2- jersey-client-2.21 vs jersey-client-1.19- metrics-core-3.0.0 vs metrics-core-2.2.0- cloudfiles-1.9.0.jar vs cloudfiles-uk-1.9.0.jar vs cloudfiles-us-1.9.0.jar- collection-2.1.1-SNAPSHOT-tests- common-2.1.1-SNAPSHOT-tests- commons-collections-3.2.1.jar vs commons-collections4-4.0.jar- uuid-3.2.0.jar vs uuid-3.2.jar',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-1248','Please delete old releases from mirroring system','To reduce the load on the ASF mirrors projects are required to delete old releases [1]Please can you remove all non-current releases?i.e. the ones listed as affected.Thanks![1] http://www.apache.org/dev/release.html#when-to-archive',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-1250','Create additional push notification tests for the node.js integration tests','Need to test the following example endpoints:/users/michael/notifications/users/michael/devices/notifications/users/michael/devices/*/notifications/users;ql=select * where username=\'michael\'/notifications/devices/*/notifications/devices/device1/notifications/devices/af94a111-a927-11e5-8d9c-12c60bce005f/notifications/devices;ql=select * where uuid=\'a4b7dc0b-b4d3-11e5-80bb-12c60bce005f\'/notificationsAlso it\'s important to test creating groups of users and sending notifications to 1 or more groups.',NULL,'Abhinav Sinha','Issues'),('UserGrid','USERGRID-1251','Handle index processing event case where an edge exists but entity is missing.','In the event an edge exists in graph and the entity has been deleted ensure this is handled as OK when processing the index event in AmazonAsyncEventService.  Currently it logs an exception because when it tries to fetch the entity data it doesn\'t exist and therefore 0 messages are returned for an event that should have returned 1 message. Ideally this should trigger a graph node compaction (read repair) to remove that edge.',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1252','Default entity types do not show up on GET /<application> endpoint when there are 0 entities','Default entity types do not show up on GET /<application> endpoint when there are 0 entities of that type (none in the collection)e.g. usersDue to this the portal may not show the default collections when there are 0 entities in the collection.  This is happening now that graph edges are cleaned up properly but we should discuss showing these since they are default reserved typed entities in Usergrid.',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-1253','Investigate and Refactor WriteUniqueVerify','Seeing a lot of exceptions like the following which indicate that the current workflow for writing and validating unique values (e.g. name/username/email properties):Caused by: java.lang.RuntimeException: Could not retrieve unique value for field email unable to verify        at org.apache.usergrid.persistence.collection.mvcc.stage.write.WriteUniqueVerify$ConsistentReplayCommand.executeStrategy(WriteUniqueVerify.java:201)        at org.apache.usergrid.persistence.collection.mvcc.stage.write.WriteUniqueVerify$ConsistentReplayCommand.run(WriteUniqueVerify.java:173)        at org.apache.usergrid.persistence.collection.mvcc.stage.write.WriteUniqueVerify$ConsistentReplayCommand.run(WriteUniqueVerify.java:150)        at com.netflix.hystrix.HystrixCommand$1.call(HystrixCommand.java:294)        ... 21 moreCaused by: rx.exceptions.OnErrorThrowable$OnNextValue: OnError while emitting onNext value: org.apache.usergrid.persistence.collection.mvcc.stage.CollectionIoEvent.class        at rx.exceptions.OnErrorThrowable.addValueAsLastCause(OnErrorThrowable.java:104)        at rx.internal.operators.OperatorDoOnEach$1.onNext(OperatorDoOnEach.java:81)        at rx.internal.util.ScalarSynchronousObservable$ScalarSynchronousAction.call(ScalarSynchronousObservable.java:115)        at rx.internal.schedulers.ScheduledAction.run(ScheduledAction.java:55)        at rx.schedulers.ExecutorScheduler$ExecutorSchedulerWorker.run(ExecutorScheduler.java:98)We should see how to improve this so we can handle unique values at scale (likely introducing something like akka with consistent hash routing of the write operation).',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-1256','Introduce Datastax Java Driver in effort to migration away from Astyanax',NULL,1,'Michael Russo','Issues'),('UserGrid','USERGRID-1259','Re-indexing ElasticSearch entity data from Cassandra - Possible Memory Leaks in Usergrid','Full system re-index job (http://localhost:8080/system/index/rebuild) seems to stop / hang after 20-30 hours of indexing. Usergrid seems to exhaust the 4.5 GB of RAM. Please see logs below:1. UserGrid logs (out of java heap space)Feb 04 17:06:32 Usergrid-2 catalina.out:  06:36:31961  WARN OioServerSocketPipelineSink:83 - Failed to accept a connection.Feb 04 17:06:32 Usergrid-2 catalina.out:  java.lang.OutOfMemoryError: Java heap spaceFeb 04 15:05:03 Usergrid-2 catalina.out:  04:34:25166  WARN jvm:203 - [default] [gc][old][29454][2683] duration [54.2s] collections [3]/[54.3s] total [54.2s]/[13.2h] memory [4.4gb]->[4.4gb]/[4.4gb] all_pools {[young] [532.5mb]->[532.5mb]/[532.5mb]}{[survivor] [62.5mb]->[65mb]/[66.5mb]}{[old] [3.8gb]->[3.8gb]/[3.8gb]}Feb 03 20:38:34 Usergrid-2 catalina.out: 10:08:34616 ERROR AmazonAsyncEventService:361 - Failed to index message: 886ea9bd-708d-4bea-ab1c-844ff97c947c 2. ES logs (time out removed non-data node from cluster)Feb 04 16:00:33 Elasticsearch elasticsearch.log:  [2016-02-04 05:31:17243][INFO ][cluster.service          ] [Arlette Truffaut] removed {[default][3GuynlamR6GvdiCAhhTBmw][ip-10-0-0-237][inet[/10.0.0.237:9301]]{client=true data=false}} reason: zen-disco-node_failed([default][3GuynlamR6GvdiCAhhTBmw][ip-10-0-0-237][inet[/10.0.0.237:9301]]{client=true data=false}) reason failed to ping tried [3] times each with maximum [30s] timeoutFeb 04 16:00:33 Elasticsearch elasticsearch.log:  [2016-02-04 05:31:17256][DEBUG][action.admin.cluster.node.stats] [Arlette Truffaut] failed to execute on node [3GuynlamR6GvdiCAhhTBmw]Feb 04 16:00:33 Elasticsearch elasticsearch.log:  org.elasticsearch.transport.NodeDisconnectedException: [default][inet[/10.0.0.237:9301]][cluster:monitor/nodes/stats[n]] disconnectedIs it possible that the re-indexing code in Usergrid could have memory leaks and thus uses up all the java heap memory.Please help.ThanksJaskaran',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1260','Asset and Accept Header changes','Fixes:1. GET entity with text/html was returning an error. Now entity retrieval returns 406 Not Acceptable if text/html is only acceptable type (must allow application/json even if text/html is preferred).2. PUT was leaving all files in the payload of the entity -- only text/plain files should be embedded in the entity payload.3. PUT/POST file was being allowed even on non entities. Now only PUT /collection/entity POST /collection/entity and POST /collection (auto-creates entity) are allowed. Others return 400 Bad Request.4. GET of asset file streams is now locked down to GET /collection/entity. Other URL patterns return 404 Not Found.5. For GET of asset file streams if either the entity itself or the asset for an entity is not found it now returns 404.6. Accept header was not being validated for GET of asset file streams. Now an accept header that is compatible with the file type is required (otherwise returns 406 Not Acceptable).7. Other errors in GET asset streams function were cleaned up (404 when asset not found 500 when something goes wrong with retrieval).8. Added tests and fixed other tests (since text/html entity requests are now locked down).',NULL,'Mike Dunker','Issues'),('UserGrid','USERGRID-1262','Always return JSON as application/json','Sometimes Usergrid returns JSON data as text/html so that it may be displayed in a browser. This is a bad practice and should be discontinued.',NULL,NULL,'Issues'),('UserGrid','USERGRID-1266','401 when 404 is expected on missing entity','This missing entity should return a 404: https://api-connectors-prod.apigee.net/appservices/api-connectors/sdksandbox/nodejs/2f2ec3d7-d40f-11e5-860f-0a65ea91a1eb {\"error\":\"service_resource_not_found\"\"timestamp\":1455559868909\"duration\":0\"error_description\":\"Service resource not found\"\"exception\":\"org.apache.usergrid.services.exceptions.ServiceResourceNotFoundException\"}',NULL,'Mike Dunker','Issues'),('UserGrid','USERGRID-1267','Simplify Central SSO: eliminate ext token validation end-point','Instead of requiring that clients first validate tokens obtained from an external \"Central SSO\" system when Usergrid is configured for using Central SSO it should attempt to verify any unknown token itself.This can be implemented by moving the validate external token logic from the ManagementResource and into the TokenService.',3,'David Johnson','Issues'),('UserGrid','USERGRID-1268','Proof of Concept: use Akka for Unique Value enforcement','By using an distributed Actor System we can ensure that only one thread accesses any one unique value at a time. I have a working proof of concept of this that writes to Cassandra (via Java Native Driver).Initial design is here:https://docs.google.com/document/d/1o9okFgNb_c1RY0eIcZMhijhxE9v7BxHYDiuI8BqkLgU/edit#Proof of Concept (POC) code is here:https://github.com/snoopdave/akka_poc1Presentation that explains the POC is here:https://docs.google.com/presentation/d/11ARSPZ6IAxOYSTo4jcmEdnzXvOgVGNGslznmVtLOZjY/edit?usp=sharing',8,'David Johnson','Issues'),('UserGrid','USERGRID-1270','Enhance shard compaction to track the \'end\' of a shard\'s valid Edges','During the shard compaction process columns (edges) are moved from a source shard (row) to a target shard to balance the size against the configured shard size in Usergrid.This causes tombstones to be created and can make seeks slower or potentially cause timeout exceptions in Astyanax if the tombstone overwhelming exception from Cassandra is thrown. Implement the ability to \'mark\' a shard\'s last valid edge so that can be fed into the range scan when retrieving the row (shard).',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1272','Set a property to turn off usergrid\'s dependency on elasticsearch','Have a property that can tell Usergrid whether we want to use elasticsearch or not. If we don\'t we shouldn\'t have any errors should just work as is with only graph searches .',5,'Michael Russo','Issues'),('UserGrid','USERGRID-1281','Download page must link to ASF mirrors for KEYS sigs hashes','The download page currently links to  https://dist.apache.org/repos/dist/ for KEYS sigs and hashes.Such links must use the ASF mirrors eghttps://www.apache.org/dist/usergrid/KEYS',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-1283','Improve ServiceManager.init() start-up logic','Changes related to management app / startup logic1) Lock Manager setup now happens in the EntityManagerFactory and is invoked as part of the normal /database/setup process.2) CpEntityManagerFactory now checks for the existence of the management app and will retry if it cannot be found unless Usergrid has not yet been bootstrapped. It will log the root cause exception and a track trace. Max retries and interval are configurable.3) CpEntityManagerFactory now keeps a \"cache\" of the latest fetched Management App object. EntityManager cache will update the cached Management App object whenever it is successfully fetched.4) CpEntityManagerFactory\'s cache of EntityManagers will not cache bad EntityManagers i.e. those that cannot fetch their own applications or the application\'s name is null.5) EntityManager cache size configurable via a new property \'\'entity.manager.cache.size\"6) Additional logging for when EntityManager EntityManagerFactory QueueManager or QueueManagerFactory is null.',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-1289','Make /org/app/users/me permissions more robust.',NULL,NULL,'David Johnson','Issues'),('UserGrid','USERGRID-1293','Asset files do not appear to be deleted','Need to add a test case to services layer to prove that the asset binary files get deleted when an entity is deleted and fix if proven.  Per request from mailing list appears there is a bug around this as ServiceResults.Type.COLLECTION is almost always used.  There does not appear to be a services layer test cases for assets only REST layer tests which test creation.  Any deletion test in REST would only verify that an entity got deleted but could not check specifically if the asset binary file is gone hence the need for services layer test.I think Usergrid is an amazing project and I use it as my application\'s backbone. But I always cannot delete binary files and here is my question about deleting asset binary files through rest API.`stack/rest/src/main/java/org/apache/usergrid/rest/applications/ServiceResource.java` has this code snippet:   {code}    ServiceResults sr = executeServiceRequest( ui response ServiceAction.DELETE null );    // if we deleted an entity (and not a connection or collection) then    // we may need to clean up binary asset data associated with that entity    if (    !sr.getResultsType().equals( ServiceResults.Type.CONNECTION )        && !sr.getResultsType().equals( ServiceResults.Type.COLLECTION )) {        // Execute binaryStore.delete(){code}So I learn Usergrid has a way to delete binary files. Here comes my question. The if-else statement does not allow a ServiceResult whose ResultType equals COLLECTION. But take a look `stack/services/src/main/java/org/apache/usergrid/services/AbstractCollectionService.java` (I remember almost services extend this class):  {code}    @Override    public ServiceResults deleteItemById( ServiceContext context UUID id ) throws Exception {        checkPermissionsForEntity( context id );             // skip some contents ...        return new ServiceResults( this context Type.COLLECTION Results.fromEntity( item ) null null );    }{code}Above method always returns a ServiceResults whose ResultType equals Type.COLLECTION. So it always cannot access the code snippet inside of the if-else statement. Is that a bug? Or it\'s my misunderstanding ? I look forward your help and hope you can explain a little bit more if I\'m understanding. Thank you so much.',NULL,NULL,'Issues'),('UserGrid','USERGRID-1295','Enhance de-index on update/delete logic to find old versions using Cassandra','Currently old versions of entities in Elasticsearch are found by querying elasticsearch.  This can lead to many documents being returned and also put high stress on Elasticsearch.  This information should exist in Cassandra.  We should query and get older versions and then build the docIds for ES directly and send a de-index request ( or batches of de-index requests).',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1296','Selecting nested fields in query select cause not working',NULL,NULL,'David Johnson','Issues'),('UserGrid','USERGRID-1297','PUT /{collection}/{entityName} giving 400 Status with DuplicateUniquePropertyExistsException',NULL,NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1298','When cursor queryparam is passed in with an empty value 500 response code is thrown','Whenever bad input is received the API should response with 400 Bad Request and a meaningful error response message.',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1304','HTTP 500 error when retrieving Entity via connection','From the Usergrid mailing list:I\'ve noticed that the errors Usergrid returns seem somewhatinconsistent. For example when attempting to GET an entity that doesn\'texist directly from the collection (omitting org and app from path forclarity):GET /things/ferrariwill return an error \"entity_not_found\" but attempting to GET the sameentity through a connection where I \"own\" the entity:GET /users/me/owns/things/ferrariwill return an \"uncaught\" error with error_description \"Internal ServerError.\"Is this intentional? I was expecting to get an \"entity_not_found\" errorin both cases as I think this would be a pretty common situation tohave in a system where entities are created and deleted dynamically.(If /things/ferrari actually exists and I own it both queries return itas expected so that\'s cool.)If I\'ve understood the design intent behind Usergrid correctly theseconnections are extremely important because I can map permissions tothem. Therefore it\'s not always possible to access objects directlyunder the collection as the user may only have permission to accessobjects through a connection (e.g. \"owns\"). I like this scheme a lotit\'s simple intuitive yet powerful.Here are curl commands that reproduce the behavior:curl -X POST \"http://localhost/udwc/brikoleur/token\" -d \'{ \"grant_type\"ΓÇª: \"password\"  \"username\" : \"abogdanov\" \"password\" : \"thepassword\" }\'{\"access_token\":\"YWMtpgdKYDbyEeaD2zHg-adLzwAAAVWSPvYGkxL-sP9RrdRTbAGgQJijcOXcApE\"\"expires_in\":604800\"user\":{\"uuid\":\"2349d142-317a-11e6-9322-080027cf389a\"\"type\":\"user\"\"name\":\"AlexanderBogdanov\"\"created\":1465831132919\"modified\":1465841524921\"username\":\"abogdanov\"\"email\":\"psulonen@gmail.com\"\"activated\":true\"picture\":\"http://www.gravatar.com/avatar/fd1ebc06694e703c1b0c64215890a865\"\"metadata\":{\"size\":608}\"repeatPassword\":\"thepassword\"}}ΓÇªcurl --header \"Authorization: BearerYWMtpgdKYDbyEeaD2zHg-adLzwAAAVWSPvYGkxL-sP9RrdRTbAGgQJijcOXcApE\"\"http://localhost/udwc/brikoleur/users/abogdanov/owns/things/ferrari\"{\"error\":\"uncaught\"\"timestamp\":1466432732273\"duration\":0\"error_description\":\"InternalServerError\"\"exception\":\"org.apache.usergrid.rest.exceptions.UncaughtException\"\"error_id\":\"d87217ed-36f2-11e6-b273-080027cf389a\"}',NULL,'Ayesha Amrin Dastagiri','Issues'),('UserGrid','USERGRID-1305','Error trying to send push notifications / iterate collections','The graph read filter will attempt to queue up read repair events to de-index deleted entities.  However if it encounters a non-time UUID the deIndex code throws an exception:Caused by: java.lang.UnsupportedOperationException: Not a time-based UUIDat java.util.UUID.timestamp(UUID.java:293)at org.apache.usergrid.corepersistence.index.IndexServiceImpl.deIndexEntity(IndexServiceImpl.java:284)at org.apache.usergrid.corepersistence.asyncevents.EventBuilderImpl.buildEntityDelete(EventBuilderImpl.java:132)at org.apache.usergrid.corepersistence.pipeline.read.traverse.AbstractReadGraphFilter.lambda$null$1(AbstractReadGraphFilter.java:159)',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-1310','No cursor returned when paging incoming connections','Investigate and fix: no cursor returned when getting incoming connections?---From Andrew Lane on the user mailing list:Let\'s say I have some collection called someentity that has connections to other entities via a verb subscribedto. For a particular entity with id some_id I\'d like to pull all the entities that are connected to this entity via the subscribedto verb. I can do that via this GET request:/org/app/someentity/some_id/subscribedtoHowever I\'m not sure how I stream or page through this data if there are thousands or more results. I\'m not getting back a cursor or anything. Is having a huge number of connections to a particular entity something that\'s just not a smart thing to do with Usergrid?From Dave Johnson:---Usergrid is designed to support a huge number of connections and we implemented \"edge sharding\" to ensure that we are not thwarted by Cassandra\'s 2-billion column limitation. The normal way to page through results is to have a cursor so the fact that you did not get a cursor is a problem and most likely a bug -- can you share the exact API call you are making as a curl (or HTTPie) command?  Do you see any errors in the logs? From Andrew Lane:---I have a collection of events and users can subscribe to those events via a connection called \"subscribedto\".  For a particular event (some_event_id) I\'m trying to stream all the users that are subscribed to that event.  In my scenario there are over 1000 subscribers.  I\'m issuing something like this (note the \"connecting\" part of the URL which I accidentally ommitted previously):curl -X GET \"http://myserver:8080/myorg/sandbox/events/some_event_id/connecting/subscribedto?limit=5\"It\'s correctly limiting to 5 users but I\'m not getting any cursor where I can continue streaming.  If I remove the limit clause I only get the first 1000 results which I expect.  But again no cursor to continue to pull data.From Andrew Lane:---I should be clear that I DO get a cursor when querying the relationship in the opposite direction.  That is if a single user is subscribed to more than 1 event I can stream those successfully and I get a cursor.  It\'s the inverse direction that\'s not giving me a cursor.',NULL,'Ayesha Amrin Dastagiri','Issues'),('UserGrid','USERGRID-1314','Or queries fail when field \"name\" is included','When I fixed the Query Validator module I found that about 5 of the tests fail to return correct results.All of the failing queries use an OR operator with a field named \"name\" for example these queries (from EntityIndexTest in the query index module) work fine:        testQuery( scope searchTypes \"age > 35\" 29 );        testQuery( scope searchTypes \"age <= 35\" 73 );        testQuery( scope searchTypes \"age <= 35 or age > 35\" 102 );But this query returns 0 results because the presence of the \"name\" field seems to turn the OR query into an AND query.        testQuery( scope searchTypes \"name = \'astro*\' or age > 35\" 29 );Until this is fixed I have marked the five failing tests in UserQueryIT (in the query-validator module) with the @Ignore annotations.',NULL,'Ayesha Amrin Dastagiri','Issues'),('UserGrid','USERGRID-1336','Implement a query analyzer','Implement a query analyzer such that the following things can be taken into consideration based on applicatino set limits:size of collection (in count of entities and total bytes)size of index (total bytes)number of query operandsnumber of query sort predicatesIf one exceeds the limit mark it as a violation.The initial approach for this will be log only such that we can alert based on logs if something extremely abnormal is detected.  Also provide the client a new queryparam \"analyzeOnly\" so that for any existing query they can run this and get back the warnings without having the query execute against Elasticsearch.',NULL,'Michael Russo','Issues'),('UserGrid','USERGRID-144','Assets: File meta not refreshed after PUT','In the new implementation of assets PUT operations update the asset data but do not update the file metadata.This means that if the content-type of the asset changes GET operations fail if I specify the expected content-type in the Accept header.For example if I attach an asset with content-type: image/jpeg I can PUT a new jpeg and retrieve the new image with the Accept: image/jpeg header.But...If I PUT a text file the file metadata remains content-type: image/jpeg so a GET with Accept: text/plain fails.But...A GET with Accept: image/jpeg succeeds and I get back the data for my text file.',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-193','SaveCollectionMembers in Export does not correctly export all entity data','The saveConnections() and saveDictionaries() methods are called at the end of SaveCollectionMembers() in file ExportServiceImpl.java  but if collection for an entity was null then it would just return and not export the connections and dictionaries for that particular entity thus calling these functions in the start of the method ensures that all connections and dictionaries are always exported.',3,'David Johnson','Issues'),('UserGrid','USERGRID-216','GET an non-exists entity by ID or Name throws 401 if no authorisation is required','for exampleget /sandbox/users/non-exist-username throws 401 error codethis is because below code{code}@Providerpublic class ServiceResourceNotFoundExceptionMapper extends AbstractExceptionMapper<ServiceResourceNotFoundException> {    @Override    public Response toResponse( ServiceResourceNotFoundException e ) {        if ( SubjectUtils.getSubjectUserId() == null ) {            return toResponse( UNAUTHORIZED e );        }        else {            return toResponse( NOT_FOUND e );        }    }}{code}',2,'George Reyes','Issues'),('UserGrid','USERGRID-228','Portal should not give username/password error when error was due to some other problem','Sometimes when Usergrid starts it errors gracefully if one of the ports is in use (7000) sometimes it gives a timeout (8080) and sometimes it works (8080) even though the port is used but then when you try the portal it tells you the username/password was not valid when in fact the error is a 501 on ΓÇÿOPTIONSΓÇÖ though it could be a different error depending on what is already using the port (screenshot below).  This same behavior happens if the port cannot be reached.  So the questions are:1) Can we configure all the different ports using the Launcher JAR?  Including Cassandra?2) Can we update the portal to display something other than invalid user/name when this happens?',NULL,'ryan bridges','Issues'),('UserGrid','USERGRID-238','Remove ARS Maquette font from Portal','portal/css/arsmarquette/*dist/usergrid-portal/css/arsmarquette/*dist-cov/usergrid-portal/css/arsmarquette/*These fonts are Copyright (c) ARS Type┬«-Angus R. Shamal 1999-2010. All rights reserved. Do we have a license to redistribute them?',2,'David Johnson','Issues'),('UserGrid','USERGRID-254','1 Add Event system to Collections module use it to clean up old indices','When the Core module EntityManager deletes or updates Entities in the Collections module the Query Index records for the old versions of that Entity need to be deleted.To enable this we added an eventing system to the Collections module so that callers can hook into entity create update and delete events.And we added event handlers to clean up the Query Index records for those events. See the new package in Collections module:   org.apache.usergrid.persistence.collection.eventAnd in Core:   org.apache.usergrid.corepersistence.events',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-255',NULL,NULL,NULL,NULL,'Issues Summary'),('UserGrid','USERGRID-256','Use ApiResponse to parse out JsonNode responses','Currently in the rest tier tests we are forced to parse the JsonNode response to see what has been returned. Instead what we want to do is use our ApiResponse and use the methods in there to retrieve and check the responses. This will make the tests easier to understand.',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-259','Generify the ApiResponse so we can return any type of class','The ApiResponse should be converted to be a generic class so that we can type case it into the specific type we need. For example : the ApiResponse can return a User type if we have ApiResponse<T> we should be able to get back a ApiResponse<User>.',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-260','composition vs inheritance for the apiresponse json node deserialization','Check to see if we can get away with using Composition in the ApiResponse rather than using inheritance which will create a lot of different UserResponse kind of subclasses. Rather with composition we could have a User object or Organization object that gets populated.',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-267','Rework broken Scheduler Tests in two-dot-o branch','Our move to the using external Cassandra and ElasticSearch instances during testing cause the Scheduler tests in the Core and Services Module to fail when run multiple times unless you clear the Cassandra and ElasticSearch storage files between each run.One instance of this problem is: SchedulerRuntimeIntervalIT in the Core Module',NULL,NULL,'Issues'),('UserGrid','USERGRID-268','3 Rework broken Migration tests in two-dot-o branch','Our move to the using external Cassandra and ElasticSearch instances during testing cause the Migration tests in the Core Module to fail when run multiple times unless you clear the Cassandra and ElasticSearch storage files between each run.The two tests are in Core:- EntityDataMigrationIT- EntityTypeMappingMigrationIT',NULL,NULL,'Issues'),('UserGrid','USERGRID-269','fix broken notifications services test',NULL,NULL,'Shawn Feldman','Issues'),('UserGrid','USERGRID-273','5 Cleanup test harness and create a more declarative test framework','Currently our test harnesses are a mess of spaghetti.  We need to decouple this mess and allow us to cleanly define the rules and requirements of our system.  I think we need to break it down into the following behaviors.h1. Test Execution Environmentsh2. Parallel ExecutionThis should be the default behavior.  All tests are assumed to be parallelh2. Serial ExecutionThis should be the exception and only used when parallel execution cannot be accomplished.  Tests in this classification should run in a method at a time with no concurrencyh1. External resourcesh2. Cassandra# Configure the runtime# Pre invocation hook## Create default implementation of truncating column families.  This should be manually added and not execute by default.# Post invocation hookh2. ElasticSearch # Configure the runtime# Pre invocation hook## Create default implementation of truncating column families.  This should be manually added and not execute by default.# Post invocation hookh1. LifecycleA test itself can have numerous lifecycle operations.  These should be set up as rules both class and instance and should NOT be done via inheritance of abstract tests.  This is the old Junit3 way of operating and needs removed.',8,'David Johnson','Issues'),('UserGrid','USERGRID-276','Implement Collection/Entity calls for new REST testing framework',NULL,NULL,'George Reyes','Issues'),('UserGrid','USERGRID-278','Implement Organization methods in Management Class for REST tests','Implement Organization methods in Management Class for REST tests',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-279','Update Browser Compatibility to work with new REST test framework','Update all role tests to use the new test framework',NULL,'Rod Simpson','Issues'),('UserGrid','USERGRID-280','Implement Admin User methods in Management Class for REST tests','Implement Admin User methods in Management Class for REST tests. Ensure that AdminUsersIT test works.',3,'George Reyes','Issues'),('UserGrid','USERGRID-282','Update Query Tests to work with new REST test framework','Update Query Tests to work with new REST test framework',NULL,'ryan bridges','Issues'),('UserGrid','USERGRID-285','Implement Token methods in Management Class for REST tests','Implement Token methods in Management Class for REST tests',NULL,NULL,'Issues'),('UserGrid','USERGRID-286','Build Application and Collection Delete Async Distributed Workflow','Akka and the Usergrid ActorSystem module is now used in Usergrid from 2.1.1 onwards.  We need to develop an asynch distributed workflow leveraging this ActorSystem for things like data cleanup after app/collection deletion.',3,'Michael Russo','Issues'),('UserGrid','USERGRID-288','Update GEO Tests to work with new REST test framework','Fix the Geo tests to bring them up to standard.',NULL,'ryan bridges','Issues'),('UserGrid','USERGRID-289','Implement delete app','Need to implement delete app.  This first pass won\'t actually clean up the data it will just delete the app entity so the data can no longer be accessed.',NULL,NULL,'Issues'),('UserGrid','USERGRID-291','Update Users Tests to work with new REST test framework','https://issues.apache.org/jira/browse/USERGRID-276',NULL,'Shawn Feldman','Issues'),('UserGrid','USERGRID-293','Oversee release of 1.0.1',NULL,NULL,'David Johnson','Issues'),('UserGrid','USERGRID-294','move cleanup to before tests run in stack','move cleanup to before tests run in stack',5,'Todd Nine','Issues'),('UserGrid','USERGRID-295','Create ways to post organizations using new REST test framework',NULL,NULL,'George Reyes','Issues'),('UserGrid','USERGRID-296','Create ways to create users in new REST test framework',NULL,NULL,'Shawn Feldman','Issues'),('UserGrid','USERGRID-298','test',NULL,NULL,NULL,'Issues'),('UserGrid','USERGRID-299','Create way to get management token and store it using the rest test framework',NULL,NULL,'Shawn Feldman','Issues'),('UserGrid','USERGRID-302','Update Group Tests to work with new REST Test Framework',NULL,NULL,'Rod Simpson','Issues'),('UserGrid','USERGRID-304','Fix Paging test using new REST test framework','Fix the issues centered around paging by fixing the existing rest paging tests.',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-310','Update REST tests for Activities and Devices',NULL,NULL,'Shawn Feldman','Issues'),('UserGrid','USERGRID-311','Update remaining groups tests',NULL,NULL,'Rod Simpson','Issues'),('UserGrid','USERGRID-312','Implement App Delete in Usergrid 2 codebase','We need a way to delete an application from an organization.Should only work with an org-admin level auth token.When delete is executed we will- Add application to the deleted apps collection.- Delete the application entity from the management app collection.- Sometime later we will delete the application\'s collectionsLet\'s do this for 2.0 and 1.0.  It should be possible with EntityManager level APIs only.',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-313','Convert ConnectionResourceTest/OwnershipResourceIT/Permissions to new Rest Framework',NULL,NULL,'George Reyes','Issues'),('UserGrid','USERGRID-320','Add more meaningful query logic tests','The REST tests for logical operations in queries is sorely lacking.  We need more tests for union intersection and negation as well as proper query grammar',NULL,'ryan bridges','Issues'),('UserGrid','USERGRID-323','Implement Windows phone push notifications','We have apple and google push notifications - need to and windows phone support.----portal is done',NULL,'Shawn Feldman','Issues'),('UserGrid','USERGRID-324',NULL,NULL,NULL,NULL,'Issues Summary'),('UserGrid','USERGRID-325','Fix NotificationIT Tests by integrating it with new REST test framework.','Fix NotificationsIT by integrating it with',NULL,'Rod Simpson','Issues'),('UserGrid','USERGRID-326','Fix PartialUpdateTest by integrating it with new REST test framework.',NULL,NULL,'ryan bridges','Issues'),('UserGrid','USERGRID-327','Fix DuplicateNameIT test by integrating it with new REST test framework',NULL,NULL,'ryan bridges','Issues'),('UserGrid','USERGRID-328','Fix ConnectionResourceTest by integrating with new REST test framework.',NULL,NULL,'ryan bridges','Issues'),('UserGrid','USERGRID-329','Fix RetrieveUsersTest by integrating it with new REST test framework',NULL,NULL,'ryan bridges','Issues'),('UserGrid','USERGRID-330','Fix GeoPagingTest cast issue','Test fails with casting issuejava.lang.ClassCastException: org.apache.usergrid.rest.test.resource2point0.model.Entity cannot be cast to java.util.LinkedHashMapat org.apache.usergrid.rest.applications.queries.GeoPagingTest.groupQueriesWithConsistentResults(GeoPagingTest.java:201)at sun.reflect.NativeMethodAccessorImpl.invoke0(Native Method)at sun.reflect.NativeMethodAccessorImpl.invoke(NativeMethodAccessorImpl.java:57)at sun.reflect.DelegatingMethodAccessorImpl.invoke(DelegatingMethodAccessorImpl.java:43)at org.junit.runners.model.FrameworkMethod$1.runReflectiveCall(FrameworkMethod.java:47)at org.junit.internal.runners.model.ReflectiveCallable.run(ReflectiveCallable.java:12)at org.junit.runners.model.FrameworkMethod.invokeExplosively(FrameworkMethod.java:44)at org.junit.internal.runners.statements.InvokeMethod.evaluate(InvokeMethod.java:17)at org.junit.internal.runners.statements.RunBefores.evaluate(RunBefores.java:26)at org.junit.internal.runners.statements.RunAfters.evaluate(RunAfters.java:27)at org.apache.usergrid.rest.test.resource2point0.ClientSetup$1.evaluate(ClientSetup.java:65)at org.junit.rules.RunRules.evaluate(RunRules.java:20)at org.junit.runners.ParentRunner.runLeaf(ParentRunner.java:271)at org.junit.runners.BlockJUnit4ClassRunner.runChild(BlockJUnit4ClassRunner.java:70)at org.junit.runners.BlockJUnit4ClassRunner.runChild(BlockJUnit4ClassRunner.java:50)at org.junit.runners.ParentRunner$3.run(ParentRunner.java:238)at org.junit.runners.ParentRunner$1.schedule(ParentRunner.java:63)at org.junit.runners.ParentRunner.runChildren(ParentRunner.java:236)at org.junit.runners.ParentRunner.access$000(ParentRunner.java:53)at org.junit.runners.ParentRunner$2.evaluate(ParentRunner.java:229)at org.junit.rules.ExternalResource$1.evaluate(ExternalResource.java:48)at org.junit.rules.RunRules.evaluate(RunRules.java:20)at org.junit.runners.ParentRunner.run(ParentRunner.java:309)at org.junit.runner.JUnitCore.run(JUnitCore.java:160)at com.intellij.junit4.JUnit4IdeaTestRunner.startRunnerWithArgs(JUnit4IdeaTestRunner.java:74)at com.intellij.rt.execution.junit.JUnitStarter.prepareStreamsAndStart(JUnitStarter.java:211)at com.intellij.rt.execution.junit.JUnitStarter.main(JUnitStarter.java:67)at sun.reflect.NativeMethodAccessorImpl.invoke0(Native Method)at sun.reflect.NativeMethodAccessorImpl.invoke(NativeMethodAccessorImpl.java:57)at com.intellij.rt.execution.application.AppMain.main(AppMain.java:134)Might be fixed by one of the other pull requests but we would need to verify.',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-331','Fix AdminEmailEncodingIT by integrating it with new REST test framework',NULL,NULL,'ryan bridges','Issues'),('UserGrid','USERGRID-333','Fix ApplicationResourceIT',NULL,3,'David Johnson','Issues'),('UserGrid','USERGRID-335','Test Not Passing: CollectionsResourceIT',NULL,2,'George Reyes','Issues'),('UserGrid','USERGRID-336','Fix ContentTypeResourceIT',NULL,1,'ryan bridges','Issues'),('UserGrid','USERGRID-337','Fix GroupResourceIT',NULL,NULL,'Rod Simpson','Issues'),('UserGrid','USERGRID-338','Fix OwnershipResourceIT','Failing the contextualConnectionOwnership test everytime. The others pass.',1,'George Reyes','Issues'),('UserGrid','USERGRID-340','Fix RegistrationIT',NULL,1,'ryan bridges','Issues'),('UserGrid','USERGRID-341','Fix BrowserCompatibilityTest',NULL,3,'George Reyes','Issues'),('UserGrid','USERGRID-342','Fix AdminEmailEncodingIT',NULL,1,'ryan bridges','Issues'),('UserGrid','USERGRID-345','Fix RetrieveUsersTest',NULL,1,'George Reyes','Issues'),('UserGrid','USERGRID-347','Fix AccessTokenIT',NULL,3,'George Reyes','Issues'),('UserGrid','USERGRID-348','Update ExportResourceIT to new REST test framework',NULL,3,'George Reyes','Issues'),('UserGrid','USERGRID-35','Cannot delete an entity that has a connection to it','\"To repro attempt to delete an entity that has a connection to it such as: curl -X DELETE \"\"https://api.com/fdsafdsa/testapp/dog/Dachsund\"\" Notice that you get error message: {\"\"error\"\":\"\"class_cast\"\"\"\"timestamp\"\":1386200483978\"\"duration\"\":0\"\"exception\"\":\"\"java.lang.ClassCastException\"\"\"\"error_description\"\":\"\"org.usergrid.persistence.cassandra.ConnectedEntityRefImpl cannot be cast to org.usergrid.persistence.cassandra.ConnectionRefImpl\"\"} It is expected that the entity is deleted and the connection is deleted as well.\"',3,'George Reyes','Issues'),('UserGrid','USERGRID-352',NULL,NULL,NULL,NULL,'Issues Summary'),('UserGrid','USERGRID-359','[SPIKE] Perform profiling of the Entity Manager and Relation Manager',NULL,NULL,NULL,'Issues'),('UserGrid','USERGRID-360','Fix ImportIT REST tests',NULL,2,'George Reyes','Issues'),('UserGrid','USERGRID-361','Create REST test for app delete',NULL,2,'David Johnson','Issues'),('UserGrid','USERGRID-363','Provide REST test for Import Service','Provide REST test coverage for the parts of our Import Service implemented in the REST module.',NULL,'George Reyes','Issues'),('UserGrid','USERGRID-364','Get Import Service working with old queue system in 2.0','Get all existing Import Service tests working in the two-dot-o branch with the existing Scheduler & Queue system.',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-365',NULL,NULL,NULL,NULL,'Issues Summary'),('UserGrid','USERGRID-366','Eliminate 2 network calls for non optimistic transaction writes','Currently when a write occurs that is either a new entity or a non optimistic transaction (I.E no version included in the payload) we\'re performing 2 writes in the collection module.  Instead we should perform a single write to both the transaction log and entity storage to reduce our network I/O.',NULL,'Shawn Feldman','Issues'),('UserGrid','USERGRID-367','Refactor entity writes to run concurrently','We need to implement our operations concurrently to increase our throughput.  We need to execute the following operations in parallel.Entity WriteGraph Edge WriteEntity Indexing (still async)We have lazy repair on all reads if the system were to get out of sync.  Since we do not have a transactional store we can utilize this read repair to increase write throughput.  In the event a transaction fails we attempt to roll back. If the roll back fails it will be repaired the next time a stale entry is read.',NULL,NULL,'Issues'),('UserGrid','USERGRID-370','[FIXED?] Use ElasticSearch Filters instead of Term Query for exact matches','This is something recommended in the O\'Reilly ElasticSearch book.\"For exact value searches you probably want to use a filter instead of a query as a filter will be cached.\"Page 107 Chapter 7 \"Full Body Search\"',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-371','Ensure that all services that use amazon keys are using the same identifier for those amazon keys.','Currently the way notifications looks for access and secret keys is different from the way that export and import services look for keys. This needs to be changed so that we all look for the same name of the keys.',3,'George Reyes','Issues'),('UserGrid','USERGRID-374','Get basic import collections with connections work',NULL,NULL,'David Johnson','Issues'),('UserGrid','USERGRID-375','Implement test for resume import',NULL,3,NULL,'Issues'),('UserGrid','USERGRID-376','Test that you can update entities by importing',NULL,NULL,'David Johnson','Issues'),('UserGrid','USERGRID-377','Implement error handling for import and put tests in place to verify',NULL,NULL,'Todd Nine','Issues'),('UserGrid','USERGRID-381','3 Change serialization format that is used to store entities in Cassandra',NULL,3,'Todd Nine','Issues'),('UserGrid','USERGRID-382','Clean up migration code (move from Core to CP)','Refactor the data migrations to move from Core to Core Persistence for Entity Storage',3,'Todd Nine','Issues'),('UserGrid','USERGRID-383','Create Service integration tests for Import','Create Service integration tests- error checking  - send bad data  - check http status codes  - check exception codes',5,'George Reyes','Issues'),('UserGrid','USERGRID-384','Get import to work on a distributed system','1. write code and tests2. test on a distributed system',3,NULL,'Issues'),('UserGrid','USERGRID-385','Change import/export format to support multiple collections',NULL,5,'Todd Nine','Issues'),('UserGrid','USERGRID-386','Change the path for getting status for Import job',NULL,2,'Todd Nine','Issues'),('UserGrid','USERGRID-387','Migrate Import service tests to rest tests to better emulate end to end testing','Migrate relevant ImportCollectionIT and ImportServiceIT tests to the rest tier such that we have better end to end coverage of the system. Having all of our integration tests in the service tier means that there is still room for error when we go back up into the REST tier.',3,'George Reyes','Issues'),('UserGrid','USERGRID-388','Fix Import Resource endpoint to use services to lookup import information','It\'s not possible to perform standard collection/connection walking from org/app/import endpoints.  Fix this using overridden services.',3,'Todd Nine','Issues'),('UserGrid','USERGRID-390',NULL,NULL,NULL,NULL,'Issues Summary'),('UserGrid','USERGRID-391','Change log message level from log to debug','---------------------------------Change these from info to debug:---------------------------------2015-02-16 04:52:10056 [http-bio-8080-exec-289] INFO  org.apache.usergrid.rest.filters.MeteringFilter- Application: 1752a4f8-9d3f-11e4-8eb3-024d19876b16 sp',NULL,'David Johnson','Issues'),('UserGrid','USERGRID-392','Could not retrieve unique value for field name unable to verify','2015-02-16 05:33:23590 [http-bio-8080-exec-313] ERROR org.apache.usergrid.rest.exceptions.AbstractExceptionMapper- java.lang.RuntimeException Server Error (500)java.lang.RuntimeException: Could not retrieve unique value for field name unable to verify        at org.apache.usergrid.persistence.collection.mvcc.stage.write.WriteUniqueVerify.call(WriteUniqueVerify.java:167)        at org.apache.usergrid.persistence.collection.mvcc.stage.write.WriteUniqueVerify.call(WriteUniqueVerify.java:58)        at rx.Observable$12.onNext(Observable.java:4036)        at rx.internal.operators.OperatorDoOnEach$1.onNext(OperatorDoOnEach.java:61)        at rx.Observable$3.call(Observable.java:1551)        at rx.Observable$3.call(Observable.java:1546)        at rx.Observable.unsafeSubscribe(Observable.java:6839)        at rx.internal.operators.OperatorSubscribeOn$1$1.call(OperatorSubscribeOn.java:60)        at rx.internal.schedulers.ScheduledAction.run(ScheduledAction.java:43)        at java.util.concurrent.Executors$RunnableAdapter.call(Executors.java:471)        at java.util.concurrent.FutureTask$Sync.innerRun(FutureTask.java:334)        at java.util.concurrent.FutureTask.run(FutureTask.java:166)        at java.util.concurrent.ScheduledThreadPoolExecutor$ScheduledFutureTask.access$201(ScheduledThreadPoolExecutor.java:178)        at java.util.concurrent.ScheduledThreadPoolExecutor$ScheduledFutureTask.run(ScheduledThreadPoolExecutor.java:292)        at java.util.concurrent.ThreadPoolExecutor.runWorker(ThreadPoolExecutor.java:1145)        at java.util.concurrent.ThreadPoolExecutor$Worker.run(ThreadPoolExecutor.java:615)        at java.lang.Thread.run(Thread.java:722)Caused by: rx.exceptions.OnErrorThrowable$OnNextValue: OnError while emitting onNext value: CollectionIoEvent.class        at rx.exceptions.OnErrorThrowable.addValueAsLastCause(OnErrorThrowable.java:98)        at rx.internal.operators.OperatorDoOnEach$1.onNext(OperatorDoOnEach.java:63)        ... 13 more2015-02-16 05:33:23590 [http-bio-8080-exec-313] ERROR org.apache.usergrid.rest.exceptions.AbstractExceptionMapper- Server Error (500):{\"error\":\"runtime\"\"timestamp\":1424064803590\"duration\":0\"error_description\":\"Could not retrieve unique value for field name unable to verify\"\"exception\":\"java.lang.RuntimeException\"}2015-02-16 05:33:23600 [http-bio-8080-exec-488] ERROR org.apache.usergrid.rest.exceptions.ThrowableMapper- An uncaught exception occurred during HTTP invocationjava.lang.RuntimeException: Could not retrieve unique value for field name unable to verify        at org.apache.usergrid.persistence.collection.mvcc.stage.write.WriteUniqueVerify.call(WriteUniqueVerify.java:167)        at org.apache.usergrid.persistence.collection.mvcc.stage.write.WriteUniqueVerify.call(WriteUniqueVerify.java:58)        at rx.Observable$12.onNext(Observable.java:4036)        at rx.internal.operators.OperatorDoOnEach$1.onNext(OperatorDoOnEach.java:61)        at rx.Observable$3.call(Observable.java:1551)        at rx.Observable$3.call(Observable.java:1546)        at rx.Observable.unsafeSubscribe(Observable.java:6839)        at rx.internal.operators.OperatorSubscribeOn$1$1.call(OperatorSubscribeOn.java:60)        at rx.internal.schedulers.ScheduledAction.run(ScheduledAction.java:43)        at java.util.concurrent.Executors$RunnableAdapter.call(Executors.java:471)        at java.util.concurrent.FutureTask$Sync.innerRun(FutureTask.java:334)        at java.util.concurrent.FutureTask.run(FutureTask.java:166)        at java.util.concurrent.ScheduledThreadPoolExecutor$ScheduledFutureTask.access$201(ScheduledThreadPoolExecutor.java:178)        at java.util.concurrent.ScheduledThreadPoolExecutor$ScheduledFutureTask.run(ScheduledThreadPoolExecutor.java:292)        at java.util.concurrent.ThreadPoolExecutor.runWorker(ThreadPoolExecutor.java:1145)        at java.util.concurrent.ThreadPoolExecutor$Worker.run(ThreadPoolExecutor.java:615)        at java.lang.Thread.run(Thread.java:722)Caused by: rx.exceptions.OnErrorThrowable$OnNextValue: OnError while emitting onNext value: CollectionIoEvent.class        at rx.exceptions.OnErrorThrowable.addValueAsLastCause(OnErrorThrowable.java:98)',NULL,'Todd Nine','Issues'),('UserGrid','USERGRID-393','Create Batch Spike for Elastic Search (Todd)',NULL,3,'Shawn Feldman','Issues'),('UserGrid','USERGRID-395',NULL,NULL,NULL,NULL,'Issues Summary'),('UserGrid','USERGRID-396','Create UniqueIndexCleanup tool that works with 2.0','Current instance of tools don\'t work correctly with 2.0. This should have a RESTful endpoint that is trigged with a PUT.  We should have something like this endpoint.Check all unique values across the entire system => PUT /system/database/unqiuecheckCheck all unique values across a single applications => PUT /system/database/uniquecheck/[appid]Check all unique values in a single collection => PUT /system/database/uniquecheck/[appid]/[collectionname]Check a specific unique value for a collection.PUT=> system/database/uniquecheck/[appid]/[collectionname]/[unique value]The unique check will need to audit the unique index and ensure that the unique value exists for the entity specified. If the entity does not exist they should be removed.I think we should implement specific property cleanup first then implement the other operations as an input of Observables',3,'George Reyes','Issues'),('UserGrid','USERGRID-398',NULL,NULL,NULL,NULL,'Issues Summary'),('UserGrid','USERGRID-399',NULL,NULL,NULL,NULL,'Issues Summary'),('UserGrid','USERGRID-400',NULL,NULL,NULL,NULL,'Issues Summary'),('UserGrid','USERGRID-401',NULL,NULL,NULL,NULL,'Issues Summary'),('UserGrid','USERGRID-402','Remove old dictionary calls with Hector and migrate to the map module',NULL,1,'Michael Russo','Issues'),('UserGrid','USERGRID-403','Migrate counters from Hector to Datastax Java Driver','We need to migrate our counters from Hector to a more reliable counter framework.  Use counter column and leverage Datastax Java Driver for time being assuming Cassandra 2.1 improvements are solid.',3,'Michael Russo','Issues'),('UserGrid','USERGRID-405','Fix hotspot from continuous writes of entities (Shawn)','Currently performing a continuous PUT in 2.0 under heavy load causes a hotspot in our cassandra data.  Cause:# Under load entities can be PUT continuously# Asynchronous cleanups run and delete previous versions# These versions are retained in cassandra for long periods of time.  This causes severe row bloating before compaction occurs.Solution:For entity data we only care about the current max version.  We should change this column family to store only the maximum data format.  We will need to keep the log of previous versions so that we can bring ES into a consistent state',1,'Todd Nine','Issues'),('UserGrid','USERGRID-409','Enable system properties for customizable keyspaces','Keyspaces should be customizable for the usergrid system.  We need to implement the ability to set the keyspace based on system properties as well as the current defaults.  We should implement this in the following way.# Add these properties to the Cassandra Fig (or create a new fig configuration)# Add the fig to the injector# Reference the injector and the fig in the current EntityManager and CassandraService setup classes',3,'George Reyes','Issues'),('UserGrid','USERGRID-411','[FIXED?] Fix default index routing rules','When allocating indexes we\'ve seen issues with unbalanced shard allocation within our cluster.  To get around this we need to set the following setting in each index.  http://www.elasticsearch.org/guide/en/elasticsearch/reference/current/index-modules-allocation.html#_total_shards_per_nodeWe should allow this to be a configurable value via properties.  During new index allocation we\'ll also need to take this parameter in the payload of index allocation. We need to document this to be set asmax shards = # primaries + (# primaries * replicas) / number of nodes',NULL,NULL,'Issues'),('UserGrid','USERGRID-412','Random Tasks add tasks to comments with time',NULL,5,'Shawn Feldman','Issues'),('UserGrid','USERGRID-414','Set Build Version to Java 8','We\'re significantly behind our in our RX java implementation.  Before work on the EM/RM refactor work starts we should upgrade to Java 8 to clean up our functional syntax as well as upgrade to the latest RxJava for performance improvements.We should evaluate missing functions we use in RX as Java 8 streams.  If we can re-create our operations as Java 8 streams we should evaluate the performance of RX Java vs Java 8 streams and pick the most performant solution.',3,NULL,'Issues'),('UserGrid','USERGRID-415','Consider Not Logging this Exception','This exception probably shouldn\'t be logged at ERROR.  Please consider logging it at DEBUG or not at all.2015-02-25 02:35:55795 [http-bio-8080-exec-2] ERROR org.apache.usergrid.services.AbstractCollectionService- Entity 7 unable to be created in collection saparticlesorg.apache.usergrid.persistence.exceptions.DuplicateUniquePropertyExistsException: Entity saparticle requires that property named name be unique value of 000000000000226126-2538 existsat org.apache.usergrid.corepersistence.CpEntityManager.handleWriteUniqueVerifyException(CpEntityManager.java:2556)at org.apache.usergrid.corepersistence.CpEntityManager.batchCreate(CpEntityManager.java:2483)at org.apache.usergrid.corepersistence.CpEntityManager.create(CpEntityManager.java:334)at org.apache.usergrid.corepersistence.CpEntityManager.create(CpEntityManager.java:280)at org.apache.usergrid.corepersistence.CpEntityManager.create(CpEntityManager.java:266)at org.apache.usergrid.corepersistence.CpRelationManager.createItemInCollection(CpRelationManager.java:746)at org.apache.usergrid.corepersistence.CpEntityManager.createItemInCollection(CpEntityManager.java:1325)at org.apache.usergrid.services.AbstractCollectionService.postCollection(AbstractCollectionService.java:369)at org.apache.usergrid.services.AbstractService.invokeCollection(AbstractService.java:720)at org.apache.usergrid.services.AbstractService.invoke(AbstractService.java:634)at org.apache.usergrid.services.AbstractService.invoke(AbstractService.java:544)at org.apache.usergrid.services.ServiceRequest.execute(ServiceRequest.java:226)at org.apache.usergrid.services.ServiceRequest.execute(ServiceRequest.java:193)at org.apache.usergrid.rest.applications.ServiceResource.executeServiceRequest(ServiceResource.java:251)at org.apache.usergrid.rest.applications.ServiceResource.executePost(ServiceResource.java:401)at sun.reflect.GeneratedMethodAccessor135.invoke(Unknown Source)at sun.reflect.DelegatingMethodAccessorImpl.invoke(DelegatingMethodAccessorImpl.java:43)at java.lang.reflect.Method.invoke(Method.java:601)at com.sun.jersey.spi.container.JavaMethodInvokerFactory$1.invoke(JavaMethodInvokerFactory.java:60)at com.sun.jersey.server.impl.model.method.dispatch.AbstractResourceMethodDispatchProvider$TypeOutInvoker._dispatch(AbstractResourceMethodDispatchProvider.java:185)at com.sun.jersey.server.impl.model.method.dispatch.ResourceJavaMethodDispatcher.dispatch(ResourceJavaMethodDispatcher.java:75)at com.sun.jersey.server.impl.uri.rules.HttpMethodRule.accept(HttpMethodRule.java:302)at com.sun.jersey.server.i