DROP TABLE IF EXISTS `tarefas_sprints`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tarefas_sprints` (
  `projeto` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sprint_id` bigint NOT NULL,
  `issue_key` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pontos_iniciais` float DEFAULT NULL,
  `pontos_atuais` float DEFAULT NULL,
  PRIMARY KEY (`projeto`,`sprint_id`,`issue_key`),
  KEY `projeto` (`projeto`,`issue_key`),
  CONSTRAINT `tarefas_sprints_ibfk_1` FOREIGN KEY (`projeto`, `issue_key`) REFERENCES `tarefas` (`projeto`, `issue_key`),
  CONSTRAINT `tarefas_sprints_ibfk_2` FOREIGN KEY (`projeto`, `sprint_id`) REFERENCES `sprints` (`projeto`, `sprint_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
